    class InitConfig {
        static getAsset() {
            if (!this.asset) {
                this.asset = initConfig.asset;
            }
            if (Laya.Utils.getQueryString("asset")) {
                return Laya.Utils.getQueryString("asset");
            }
            if (this.asset && this.asset.indexOf("http") == -1) {
                return `http://${window.location.host}${this.asset}`;
            }
            return this.asset || "";
        }
        static getSyURL() {
            return initConfig.sy_url;
        }
        static get tcp() {
            if (initConfig) {
                return initConfig.tcp;
            }
        }
        static get frameRate() {
            if (initConfig) {
                return initConfig.frameRate || "slow";
            }
        }
        static getServerIp() {
            let url = Laya.Utils.getQueryString("url");
            if (url) {
                return "ws://" + url;
            }
            if (this.wxLoginResult) {
                return this.wxLoginResult.result.tcp;
            }
        }
        static getUI() {
            return "";
        }
        static getUI2() {
            if (!this.ui) {
                if (this.getAsset().length > 0) {
                    this.ui = this.getAsset();
                }
            }
            return this.ui || "";
        }
    }
