    class BaseCfg {
        constructor(_tableName) {
            let _name;
            if (_tableName) {
                this._tableName = _tableName;
                _name = _tableName;
            }
            else {
                _name = this.GetTabelName();
            }
            if (!_name) {
                throw Error("Please set your tabel name!");
            }
            this.Cfg = this.GetTabel(`cfg_${_name}`);
            if (!this.Cfg) {
                LogSys.Error(`${_name}...Cfg is null`);
            }
        }
        get ver() {
            if (this._ver == undefined) {
                let _name = this.GetTabelName();
                let arr = _name.split("_");
                let s = arr[arr.length - 1];
                this._ver = parseInt(s.substr(1, s.length - 1));
                if (isNaN(this._ver)) {
                    this._ver = 0;
                }
            }
            return this._ver;
        }
        get suffix() {
            return "";
        }
        get isHasData() {
            if (!this._isHasData) {
                let _name = this.GetTabelName();
                if (!_name) {
                }
                else {
                    this._isHasData = this.GetTabel(`cfg_${_name}`) != null;
                }
            }
            return this._isHasData;
        }
        GetDataById(id) {
            return this.getkv('f_id', id);
        }
        GetAllFids() {
            return this.getAllValue('f_id');
        }
        get isLoaded() {
            return this.Cfg != undefined;
        }
        getkv(keyStr, v) {
            let by = this.Cfg;
            if (!by) {
                return;
            }
            if (by.tableName && !by._mDataMap) {
                return by.getKv(keyStr, v);
            }
            for (var key in this.Cfg.mDataMap) {
                let element = this.Cfg.mDataMap[key];
                if (element[keyStr] == v)
                    return element;
            }
            return null;
        }
        getAllValue(keyStr) {
            let by = this.Cfg;
            if (by.tableName && !by._mDataMap) {
                return by.getAllByKey(keyStr);
            }
            let m = this.Cfg.mDataMap;
            let result = [];
            for (let key in m) {
                let element = m[key];
                result.push(element[keyStr]);
            }
            return result;
        }
        forEach(that, func) {
            let by = this.Cfg;
            by.getAllCallByKey(that, func);
        }
        get List() {
            if (this._list) {
                return this._list;
            }
            let by = this.Cfg;
            if (!by) {
                E.debugMsgBox(`table[${this.GetTabelName()}] not exist!`);
                this._list = [];
                return this._list;
            }
            if (by.tableName && !by._mDataMap) {
                let m1 = this.Cfg.mDataMap;
                this._list = by.list1;
                return this._list;
            }
            let _list1 = [];
            for (var key in this.Cfg.mDataMap) {
                let element = this.Cfg.mDataMap[key];
                _list1.push(element);
            }
            this._list = _list1;
            return this._list;
        }
        GetTabel(name) {
            return LoadUtil.GetJson(`o/config/export/${name}.json`);
        }
        dispose() {
            let by = this.Cfg;
            by.dispose();
        }
        checkVaild() {
        }
    }
