    class FuncSmallIcon {
        constructor() {
            this.used = false;
            this.isOpen = false;
            this.pos = 0;
        }
        initSkin(cls) {
            this.skin = new cls();
            this.statusLabel = "";
            this.onDisplay();
        }
        refresh(name, funcType, btnStyle, x = undefined, y = undefined) {
            let skin;
            if (name instanceof Laya.View) {
                skin = name;
            }
            else {
                skin = E.ViewMgr.Get(EViewType.Main).UI[name];
            }
            let pos = 0;
            let cfg = MainIconProxy.Ins.getCfgByFuncid(funcType);
            if (cfg && btnStyle == EButtonStyle.Pos) {
                pos = cfg.f_pos;
            }
            this.skin = skin;
            DebugUtil.draw(this.skin);
            if (debug) {
                if (!this._debugTF) {
                    this._debugTF = new Laya.Label();
                    this._debugTF.fontSize = 18;
                    this._debugTF.color = "#ff0000";
                }
                this.skin.addChild(this._debugTF);
                this._debugTF.text = funcType.toString();
            }
            this.pos = pos;
            this.btnStyle = btnStyle;
            let btnEffect = true;
            let btn = skin;
            if (btn.dot) {
                btn.dot.visible = false;
            }
            if (btnStyle == EButtonStyle.Bottom) {
                btnEffect = false;
                this.selected = false;
            }
            this.btnCtl = ButtonCtl.CreateBtn(this.skin, this, this.onClickHandler, btnEffect);
            if (btnStyle == EButtonStyle.Mid) {
                this.btnCtl.setpos(x, y);
            }
            skin.on(Laya.Event.DISPLAY, this, this.onDisplay);
            skin.on(Laya.Event.UNDISPLAY, this, this.onUnDisplay);
            this.setData(funcType);
            if (x != undefined) {
                this.btnCtl.setpos(x, y);
            }
            this.update();
        }
        update() {
        }
        set statusLabel(v) {
            if (this.skin.bg2) {
                if (v == "") {
                    this.skin.bg2.visible = this.skin.tf2.visible = false;
                }
                else {
                    this.skin.bg2.visible = this.skin.tf2.visible = true;
                    this.skin.tf2.text = v;
                }
            }
        }
        set selected(v) {
            this.skin.bg.visible = v;
        }
        setPos(x, y) {
            this.skin.x = x;
            this.skin.y = y;
        }
        onDisplay() {
            FunctionModel.Ins.on(TowerMainEvent.FuncSmallIconUpdate, this, this.onRedUpdate);
        }
        refreshView() {
            this.setData(this.funcId);
        }
        onUnDisplay() {
            FunctionModel.Ins.off(TowerMainEvent.FuncSmallIconUpdate, this, this.onRedUpdate);
            if (this._se) {
                this._se.dispose();
                this._se = null;
            }
        }
        onClickHandler() {
            if (!this.funcCfg)
                return;
            let arr = System_RefreshTimeProxy.Ins.getVal(57).split("|");
            if (arr.indexOf(this.funcId.toString()) != -1) {
                if (E.ta) {
                    let time = TimeUtil.timestamtoTime(TimeUtil.serverTimeMS);
                    E.ta.userSetOnce({ first_pack: time });
                    E.ta.userSetOnce({ first_pack_id: this.funcId });
                }
            }
            E.ViewMgr.OpenByFuncid(this.funcCfg.f_FunctionID, true, this.funcCfg.f_param);
        }
        midEmptyStatus() {
            this.funcId = 0;
            let skin = this.skin;
            skin.dot.visible = false;
            skin.tf2.visible = skin.bg2.visible = false;
            skin.icon.skin = `remote/main/main/weikaifang.png`;
            skin.tf.text = "";
        }
        onRedUpdate() {
            if (this.cfg) {
                let red = FunctionModel.Ins.getHasRed(this.funcId);
                let x = 0;
                let y = 20;
                if (this.btnStyle == EButtonStyle.Pos) {
                    x = 20;
                    y = 0;
                }
                if (this.btnStyle == EButtonStyle.Mid) {
                    x = 0;
                    y = 0;
                }
                if (red) {
                    DotManager.addDot(this.skin, x, y);
                }
                else {
                    DotManager.removeDot(this.skin);
                }
                DebugUtil.drawTF(this.skin, this.funcId + "," + (red ? 1 : 0));
            }
        }
        getName(cfg) {
            return cfg.f_name;
        }
        updateNameTfText() {
            this.skin.tf.text = this.getName(this.funcCfg);
        }
        setData(funcType) {
            this.funcId = funcType;
            let cfg = MainIconProxy.Ins.getCfgByFuncid(funcType);
            if (!cfg) {
                this.visible = false;
                this.isOpen = false;
                return;
            }
            let funcCfg = FuncProxy.Ins.getCfgByFuncId(funcType);
            this.funcCfg = funcCfg;
            this.cfg = cfg;
            this.updateNameTfText();
            let iconVal = "";
            let isOpen = FunctionModel.Ins.isOpenByFuncId(this.funcId);
            let vis = true;
            if (this.btnStyle == EButtonStyle.Mid) {
                let iconArr = cfg.f_icon.split(".");
                let a = iconArr[0];
                let icon = isOpen ? a : `${a}_1`;
                iconVal = `o/mainicon/${icon}.png`;
            }
            else if (this.btnStyle == EButtonStyle.Bottom) {
                let arr = cfg.f_icon.split(".");
                let _icon2 = "";
                if (isOpen) {
                    _icon2 = arr[0] + "." + "png";
                }
                else {
                    _icon2 = arr[0] + "_1." + "png";
                }
                iconVal = `o/mainicon/${_icon2}`;
            }
            else if (this.btnStyle == EButtonStyle.Pos) {
                vis = isOpen;
                iconVal = `o/mainicon/${cfg.f_icon}`;
            }
            if (cfg.f_animation != "") {
                this.skin.icon.visible = false;
                this.skin.sp.visible = true;
                if (!this._se) {
                    this._se = new SimpleEffect(this.skin.sp, `o/spine/succeed/${cfg.f_animation}/${cfg.f_animation}`, 8, 8);
                }
                this._se.play(0, true);
            }
            else {
                this.skin.icon.visible = true;
                this.skin.icon.skin = iconVal;
                this.skin.sp.visible = false;
            }
            this.visible = vis;
            this.isOpen = isOpen;
            this.onRedUpdate();
        }
        midReset() {
            this.skin.dot.visible = true;
            this.skin.tf2.visible = this.skin.bg2.visible = true;
        }
        set visible(v) {
            this.skin.visible = v;
        }
        dispose() {
            this.onUnDisplay();
            this.skin.removeSelf();
        }
    }

    class FunctionModel extends Laya.EventDispatcher {
        constructor() {
            super();
            this.redList = [];
            this.funList = [];
            this.stTimerList = [];
        }
        static get Ins() {
            if (!this._ins) {
                this._ins = new FunctionModel();
            }
            return this._ins;
        }
        isOpenByFuncId(funid, flag = true) {
            if (initConfig.enable_func) {
                return true;
            }
            let index = this.funList.findIndex(ele => ele === funid);
            let cfg = FuncProxy.Ins.getCfgByFuncId(funid);
            if (!cfg) {
                LogSys.Warn(`funid:${funid}配置未找到...`);
                return false;
            }
            if (index == -1) {
                if (flag) {
                    if (cfg.f_trophy && cfg.f_level) {
                        E.ViewMgr.ShowMidError(E.LangMgr.getLang("funcopentip3", cfg.f_trophy, cfg.f_level));
                    }
                    else if (cfg.f_trophy) {
                        E.ViewMgr.ShowMidError(E.LangMgr.getLang("funcopentip1", cfg.f_trophy));
                    }
                    else if (cfg.f_level) {
                        E.ViewMgr.ShowMidError(E.LangMgr.getLang("funcopentip2", cfg.f_level));
                    }
                }
                return false;
            }
            if (cfg.f_close) {
                return false;
            }
            if (cfg.f_activity_id) {
                let data = ActivityModel.Ins.getActivityStatusData(cfg.f_activity_id);
                if (data && data.status == 0) {
                    return false;
                }
            }
            if (t_Platform.Ins.isClose(funid)) {
                return false;
            }
            if (MainModel.Ins.isVerify(cfg)) {
                return false;
            }
            if (cfg.t_tab_func != "") {
                if (!this.isTabOpen(cfg.t_tab_func)) {
                    return false;
                }
            }
            return true;
        }
        isTabOpen(st) {
            let arr = st.split("-");
            for (let i = 0; i < arr.length; i++) {
                if (FunctionModel.Ins.isOpenByFuncId(parseInt(arr[i]), false)) {
                    return true;
                }
            }
            return false;
        }
        isSubOpen(cfg) {
            return false;
        }
        funcSetRed(fid, v) {
            let cfg = FuncProxy.Ins.getCfgByFuncId(fid);
            if (!cfg) {
                LogSys.Error(`not find funId:${fid}`);
                return;
            }
            if (v && cfg.f_close) {
                v = false;
            }
            let status = false;
            if (v) {
                let index = this.redList.indexOf(fid);
                if (index == -1) {
                    this.redList.push(fid);
                    status = true;
                }
            }
            else {
                let index = this.redList.indexOf(fid);
                if (index != -1) {
                    this.delRed(fid);
                    status = true;
                }
            }
            this.event(TowerMainEvent.FuncSmallIconUpdate);
        }
        delRed(fid) {
            for (let i = 0; i < this.redList.length; i++) {
                let cell = this.redList[i];
                if (fid == cell) {
                    this.redList.splice(i, 1);
                    i--;
                }
            }
        }
        getHasRed(funcId) {
            if (!this.isOpenByFuncId(funcId, false)) {
                return false;
            }
            let cfg = FuncProxy.Ins.getCfgByFuncId(funcId);
            if (cfg.t_tab_func != "") {
                return this.isTabRed(cfg.t_tab_func);
            }
            else {
                return this.redList.indexOf(funcId) != -1;
            }
        }
        isTabRed(st) {
            let arr = st.split("-");
            for (let i = 0; i < arr.length; i++) {
                if (FunctionModel.Ins.getHasRed(parseInt(arr[i]))) {
                    return true;
                }
            }
            return false;
        }
        showSmallTips(title, content, target, algin) {
            let _smallTipsData = {};
            _smallTipsData.content = content;
            _smallTipsData.title = title;
            _smallTipsData.target = target;
            _smallTipsData.algin = algin;
            E.ViewMgr.Open(EViewType.SmallTips, null, _smallTipsData);
        }
        showItemTip(data, target) {
            let obj = {};
            obj.data = data;
            obj.target = target;
            E.ViewMgr.Close(EViewType.ItemTip);
            Laya.timer.callLater(this, () => {
                E.ViewMgr.Open(EViewType.ItemTip, null, obj);
            });
        }
        showRewardTip(data, target, offX = 0, offY = 0, algin) {
            let obj = {};
            obj.data = data;
            obj.target = target;
            obj.offX = offX;
            obj.offY = offY;
            E.ViewMgr.Close(EViewType.RewardTip);
            Laya.timer.callLater(this, () => {
                E.ViewMgr.Open(EViewType.RewardTip, null, obj);
            });
        }
        showBoxTip(id, target, offX = 0, offY = 0, algin) {
            let obj = {};
            obj.id = id;
            obj.target = target;
            obj.offX = offX;
            obj.offY = offY;
            E.ViewMgr.Close(EViewType.BoxTip);
            Laya.timer.callLater(this, () => {
                E.ViewMgr.Open(EViewType.BoxTip, null, obj);
            });
        }
        createFuncIcon(name, funcId, btnStyle) {
            let o = MainModel.Ins.redNameKeyList.find(cell => cell.func_id == funcId);
            if (!o) {
                let obj = {};
                obj.func_id = funcId;
                obj.name = name;
                MainModel.Ins.redNameKeyList.push(obj);
            }
            let icon = new FuncSmallIcon();
            icon.refresh(name, funcId, btnStyle);
            return icon;
        }
    }

