    class CheckParamUtils {
        static checkCell(guide, s) {
            let arr = s.split("|");
            let model = guide.model;
            let type = parseInt(arr[0]);
            if (type == 4) {
                let heroId = parseInt(arr[1]);
                let vo = model.refreshList.find(o => o.fid == heroId);
                if (vo) {
                }
                else {
                    return true;
                }
            }
            else if (type == 5) {
                let uiView = parseInt(arr[1]);
                if (!E.ViewMgr.isOpenReg(uiView)) {
                    return true;
                }
            }
            else if (type == 6) {
                let uiView = parseInt(arr[1]);
                if (E.ViewMgr.isOpenReg(uiView)) {
                    return true;
                }
            }
            else if (type == 7) {
                let uid = parseInt(arr[1]);
                if (model.refreshList.find(o => o.uid == uid)) {
                    return true;
                }
            }
            else if (type == 8) {
                if (E.ViewMgr.isOpenReg(EViewType.CompSell)) {
                    let uid = parseInt(arr[1]);
                    let _data = E.ViewMgr.Get(EViewType.CompSell).data;
                    if (_data) {
                        if (_data.uid == uid) {
                        }
                        else {
                            return true;
                        }
                    }
                }
            }
            return false;
        }
        static checkArr(guide, f_check_param) {
            let arr = f_check_param.split(";");
            for (let i = 0; i < arr.length; i++) {
                let s = arr[i];
                if (!StringUtil.IsNullOrEmpty(s)) {
                    if (this.checkCell(guide, s) == false) {
                        return false;
                    }
                }
            }
            return true;
        }
        static check(guide, f_check_param, viewType) {
            let model = guide.model;
            if (!model) {
                return false;
            }
            if (!StringUtil.IsNullOrEmpty(f_check_param)) {
                let orList = f_check_param.split("@");
                let _status = false;
                for (let i = 0; i < orList.length; i++) {
                    let s1 = orList[i];
                    if (!StringUtil.IsNullOrEmpty(s1)) {
                        if (this.checkArr(guide, s1)) {
                            LogSys.Log(`${viewType != EViewType.None ? "hide:" + viewType : ""} check ${s1} succeed pre step...`);
                            _status = true;
                            break;
                        }
                    }
                }
                if (_status) {
                    guide.preGuideStep();
                    return true;
                }
            }
            return false;
        }
    }

    class GameList extends Laya.List {
        constructor() {
            super();
            this.mClipY = 0;
            this.disableScroll = false;
            this.on(Laya.Event.UNDISPLAY, this, this.onUnDisplay);
        }
        onScrollBarChange(e = null) {
            if (this.disableScroll) {
                return;
            }
            super.onScrollBarChange(e);
        }
        onUnDisplay() {
            this.disableScroll = false;
        }
        get cells() {
            return this._cells;
        }
        debugDrawRect() {
            DebugUtil.draw(this, "#ff0000", this.width, this.height - this.mClipY, 0, this.mClipY);
        }
    }
    class GamePanel extends Laya.Panel {
        constructor() {
            super();
            this.disableScroll = false;
            this.on(Laya.Event.UNDISPLAY, this, this.onUnDisplay);
        }
        onUnDisplay() {
            this.disableScroll = false;
        }
    }
    class GameImage extends Laya.Image {
        constructor() {
            super();
            this.on(Laya.Event.DISPLAY, this, this.onDisplay);
            this.on(Laya.Event.UNDISPLAY, this, this.onUnDisplay);
        }
        onDisplay() {
            E.EventMgr && E.EventMgr.on(EventID.TextureDestroy, this, this.onReloadImage);
        }
        onReloadImage(obj) {
            let url = obj.url;
            if (url == this.skin) {
                this.clear();
                this.skin = url;
                LogSys.Log(`................TextureDestroy onReloadImage set url ${url}`);
            }
        }
        onUnDisplay() {
            E.EventMgr && E.EventMgr.off(EventID.TextureDestroy, this, this.onReloadImage);
        }
        clear() {
            this.skin = "";
        }
    }
    class GameTex extends Laya.Image {
        constructor() {
            super();
            this.enableClearTex = true;
            this.on(Laya.Event.UNDISPLAY, this, this.onUnDisplay);
            this.on(Laya.Event.DISPLAY, this, this.onDisplay);
        }
        onDisplay() {
            LogSys.Log(`${this.name}: ${this.skin} is display`);
        }
        onUnDisplay() {
            this.clearTex();
        }
        clearTex() {
            if (this.enableClearTex) {
                AssetConfig.clearTextureRes(this.skin);
            }
        }
    }

    class AvatarOnceEffect {
        constructor() {
        }
        play(layar, avatar, url) {
            this.layer = layar;
            this.avatar = avatar;
            this.url = url;
            Laya.timer.frameLoop(1, this, this.onLoop);
        }
        dispose() {
            Laya.timer.clear(this, this.onLoop);
            this.effect = null;
            this.avatar = null;
        }
        onLoop() {
            if (this.effect && this.effect.isDestory || this.avatar.isDestory) {
                this.dispose();
                return;
            }
            if (!this.avatar.isDestory && this.avatar.coreSpine && this.avatar.coreSpine.skeleton) {
                let skel = this.avatar.coreSpine.skeleton;
                let parent = skel.parent;
                if (parent && parent.parent) {
                    let url = this.url;
                    let layer = this.layer;
                    let offset = layer.parent.localToGlobal(new Laya.Point(layer.x, layer.y));
                    let pos = parent.localToGlobal(new Laya.Point(skel.x, skel.y));
                    let ox = pos.x - offset.x + (this.offsetX || 0);
                    let oy = pos.y - offset.y + (this.offsetY || 0);
                    if (!this.effect) {
                        this.effect = SpineEffectMgr.playOnce(url, layer, ox, oy, 0);
                    }
                    this.effect.setPos(ox, oy);
                }
                else {
                }
            }
        }
    }

    class NoContainerSimpleEffect extends Laya.EventDispatcher {
        constructor(url) {
            super();
            this.mScale = 1;
            this.childIndex = -1;
            this.offsetX = 0;
            this.offsetY = 0;
            this.speed = 1;
            this.isDestory = false;
            this.isLoaded = false;
            this._loop = false;
            this.curAnim = 0;
            this.needPlay = false;
            this.anim = new BaseAnimSpine();
            this.mUrl = url;
        }
        setParent() {
        }
        set useSpineCache(v) {
            if (this.anim) {
                this.anim.useSpineCache = v;
            }
        }
        init() {
            this.anim.load(this.mUrl);
            this.anim.once(Laya.Event.COMPLETE, this, this.onInit);
        }
        set autoPlay(v) {
            this.needPlay = v;
        }
        dispose() {
            this.stop();
            this.mScale = 1;
            this.isDestory = true;
            this.callBack = null;
            this.target = null;
            this.remove();
            if (this.anim) {
                this.anim.dispose();
            }
        }
        remove() {
            if (this.anim.container) {
                this.anim.container.removeSelf();
            }
        }
        onInit() {
            if (this.isDestory) {
                return;
            }
            this.startAdd();
            this.anim.container.scaleX = this.anim.container.scaleY = this.mScale;
            this.setPos(this.offsetX, this.offsetY);
            this.anim.avatar.skeleton.playbackRate(this.speed);
            this.isLoaded = true;
            this.anim.avatar.skeleton.on(Laya.Event.LABEL, this, this.onLabelEvt);
            if (this.needPlay) {
                this.play(this.curAnim, this._loop, this.target, this.callBack, this.args);
                this.needPlay = false;
            }
            this.event(Laya.Event.COMPLETE, this);
        }
        setPos(x, y) {
            this.offsetX = x;
            this.offsetY = y;
            if (this.anim && this.anim.container) {
                this.anim.container.pos(x, y);
            }
        }
        onLabelEvt(e) {
            this.event(Laya.Event.LABEL, e);
        }
        get duration() {
            if (this.anim.avatar && this.anim.avatar.skeleton) {
                return this.anim.avatar.skeleton['_duration'];
            }
            return 0;
        }
        play(index = 0, loop = false, target, callBack = null, args, force = false) {
            this.needPlay = true;
            this.target = target;
            this.callBack = callBack;
            this.args = args;
            this.addtoStage();
            this._loop = loop;
            this.curAnim = index;
            if (loop) {
                this.anim.play(index, loop, force);
            }
            else {
                this.anim.playOnce(index, target, callBack, args, force);
            }
        }
        pause() {
            this.anim && this.anim.paused();
        }
        resume() {
            this.anim && this.anim.resume();
        }
        addtoStage() {
            if (this.anim.container && !this.anim.container.parent) {
                this.startAdd();
            }
        }
        startAdd() {
            if (this.container) {
                if (this.childIndex == -1) {
                    this.container.addChild(this.anim.container);
                }
                else {
                    this.container.addChildAt(this.anim.container, this.childIndex);
                }
            }
        }
        stop() {
            this.anim.stop();
            if (this.anim.container) {
                this.anim.container.removeSelf();
            }
            this.needPlay = false;
        }
    }

    class SpineEffectMgr {
        static playOnce(url, container, x = 0, y = 0, index = 0, childIndex = -1, playEnd = null) {
            let effect = new NoContainerSimpleEffect(url);
            effect.childIndex = childIndex;
            effect.container = container;
            effect.offsetX = x;
            effect.offsetY = y;
            effect.init();
            effect.play(index, false, this, this.onPlayEnd, [effect, playEnd]);
            effect.autoPlay = true;
            return effect;
        }
        static onPlayEnd(effect, playEnd) {
            effect.dispose();
            if (playEnd) {
                playEnd.run();
            }
        }
        static playOnceEnd(url, container, playEnd = null, ox = 0, oy = 0) {
            return this.playOnce(url, container, ox, oy, undefined, undefined, playEnd);
        }
        static playAvatarEffectOnce(layer, avatar, url, ox, oy) {
            let effect = new AvatarOnceEffect();
            effect.offsetX = ox;
            effect.offsetY = oy;
            effect.play(layer, avatar, url);
        }
        static createLoopNoSimpleEffect(url, container, ox = 0, oy = 0, animIndex = 0, childIndex = -1, mScale = 1) {
            let effect = new NoContainerSimpleEffect(url);
            effect.mScale = mScale;
            effect.childIndex = childIndex;
            effect.container = container;
            effect.offsetX = ox;
            effect.offsetY = oy;
            effect.init();
            effect.play(animIndex, true);
            return effect;
        }
        static createSimpleEffectSpineCache(url, container, ox = 0, oy = 0) {
            let effect = new NoContainerSimpleEffect(url);
            effect.useSpineCache = true;
            effect.mScale = 1;
            effect.childIndex = -1;
            effect.container = container;
            effect.offsetX = ox;
            effect.offsetY = oy;
            effect.init();
            effect.play(0, true);
            return effect;
        }
        static createNoSimpleEffect(url, container, ox = 0, oy = 0, childIndex = -1, mScale = 1) {
            let effect = new NoContainerSimpleEffect(url);
            effect.mScale = mScale;
            effect.childIndex = childIndex;
            effect.container = container;
            effect.offsetX = ox;
            effect.offsetY = oy;
            effect.init();
            return effect;
        }
        static onComplete(effect, that, func) {
            func.call(that, effect);
            effect.dispose();
        }
        static getAnimDuration(url, index, that, func) {
            let effect = new NoContainerSimpleEffect(url);
            effect.init();
            effect.play(index);
            effect.once(Laya.Event.COMPLETE, this, this.onComplete, [effect, that, func]);
        }
        static createMedalEffect(eff, cfgTr, _scale = 1) {
            eff.scaleX = eff.scaleY = cfgTr.f_size_zoom / 100 * _scale;
            let _hzEff = this.createLoopNoSimpleEffect(`o/spine/succeed/${cfgTr.f_medal_id}/${cfgTr.f_medal_id}`, eff);
            return _hzEff;
        }
        static createIllustration(cfg, eff, _mScale = 1) {
            let url = cfg.f_qua_label.split("-")[1];
            let scale = _mScale;
            let _spineEff = this.createLoopNoSimpleEffect(`o/spine/succeed/${url}/${url}`, eff, undefined, undefined, undefined, undefined, scale);
            return _spineEff;
        }
    }

