    class WalkVo {
    }
    class WalkList {
        constructor(type) {
            this.type = type;
            this.paths = this.splitPath;
        }
        createMoveVo(start, end, _walkVo, owner) {
            let paths = this.splitPath;
            let sub = end - start;
            if (sub < 0) {
                LogSys.Warn(`createMoveVo end is ${end},start is ${start}`);
            }
            let vo = new TowerMoveVo();
            let pos = paths[end];
            vo.time = sub / FightValueConfig.DEV_COUNT * _walkVo.time;
            vo.tx = pos.x;
            vo.ty = pos.y + (owner > EMonsterPos.Owner ? FightUtils.topOffsetY : 0);
            return vo;
        }
        get splitPath() {
            if (!this._splitPath) {
                let h = (ComposeConfig.mapH + 2) * ComposeConfig.Div - 2;
                let w = (ComposeConfig.mapW + 2) * ComposeConfig.Div - 2;
                let moveList = [];
                let _cutList = [];
                for (let i = 0; i < h; i++) {
                    let vo = {};
                    vo.isoX = 1;
                    vo.isoY = i + 1;
                    vo.dir = EIsoRegion.Left;
                    moveList.push(vo);
                }
                _cutList.push(moveList[0]);
                _cutList.push(moveList[moveList.length - 1]);
                for (let i = 1; i < w; i++) {
                    let vo = {};
                    vo.isoX = i + 1;
                    vo.isoY = h;
                    vo.dir = EIsoRegion.Top;
                    moveList.push(vo);
                }
                _cutList.push(moveList[moveList.length - 1]);
                for (let i = h; i > 1; i--) {
                    let vo = {};
                    vo.isoX = w;
                    vo.isoY = i - 1;
                    vo.dir = EIsoRegion.Right;
                    moveList.push(vo);
                }
                _cutList.push(moveList[moveList.length - 1]);
                for (let i = w; i > 1; i--) {
                    let vo = {};
                    vo.isoX = i - 1;
                    vo.isoY = 1;
                    vo.dir = EIsoRegion.Bottom;
                    moveList.push(vo);
                }
                const PER_DIV = FightValueConfig.DEV_COUNT;
                let _outlist = [];
                let _indexs = [];
                for (let i = 0; i < moveList.length; i++) {
                    let start = moveList[i];
                    let end = moveList[i + 1];
                    if (end) {
                        let type = this.type;
                        let sx = FightUtils.convertX(start.isoX, type);
                        let sy = FightUtils.convertY(start.isoY, type);
                        let ex = FightUtils.convertX(end.isoX, type);
                        let ey = FightUtils.convertY(end.isoY, type);
                        let subX = (ex - sx) / PER_DIV;
                        let subY = (ey - sy) / PER_DIV;
                        let cell = _cutList.find(o => o.isoX == start.isoX && o.isoY == start.isoY);
                        if (cell) {
                            _indexs.push(_outlist.length);
                        }
                        for (let n = 0; n < PER_DIV; n++) {
                            let x1 = sx + subX * n;
                            let y1 = sy + subY * n;
                            let walkVo = new WalkVo();
                            walkVo.x = x1;
                            walkVo.y = y1 + FightValueConfig.MonsterOffsetY;
                            walkVo.index = i + 1;
                            walkVo.region = start.dir;
                            _outlist.push(walkVo);
                        }
                    }
                }
                _indexs.push(_outlist.length - 1);
                let l = [];
                for (let i = 0; i < _indexs.length; i++) {
                    let min = i == 0 ? 0 : _indexs[i] + 1;
                    let max = _indexs[i + 1];
                    if (max) {
                        let _rangle = new RangleVal();
                        _rangle.min = min;
                        _rangle.max = max;
                        l.push(_rangle);
                    }
                }
                this.rangleList = l;
                this._splitPath = _outlist;
            }
            return this._splitPath;
        }
    }

    class RangleVal {
    }
    class FightUtils {
        static convertX(x, owner) {
            return ComposeConfig.MapCellW * x + ComposeConfig.MapCellW / 2;
        }
        static convertY(y, owner) {
            if (owner > EMonsterPos.Owner) {
                return y * ComposeConfig.MapCellH + ComposeConfig.MapCellH / 2;
            }
            return (this.height - y) * ComposeConfig.MapCellH + ComposeConfig.MapCellH / 2;
        }
        static init() {
            let h = (ComposeConfig.mapH + 2) * ComposeConfig.Div - 1;
            this.height = h;
        }
        static IsoxToPosX(isoX) {
            return isoX * ComposeConfig.cellW + ComposeConfig.cellW / 2;
        }
        static IsoyToPosY(isoY, owner) {
            if (owner > EMonsterPos.Owner) {
                return isoY * ComposeConfig.cellH + ComposeConfig.cellH / 2 + this.topOffsetY;
            }
            return (ComposeConfig.mapH - isoY - 1) * ComposeConfig.cellH + ComposeConfig.cellH / 2;
        }
        static get curMoveList() {
            if (!this.moveList) {
                let h = (ComposeConfig.mapH + 2) * ComposeConfig.Div - 2;
                let w = (ComposeConfig.mapW + 2) * ComposeConfig.Div - 2;
                let moveList = [];
                for (let i = 0; i < h; i++) {
                    let vo = {};
                    vo.isoX = 1;
                    vo.isoY = i + 1;
                    moveList.push(vo);
                }
                for (let i = 1; i < w; i++) {
                    let vo = {};
                    vo.isoX = i + 1;
                    vo.isoY = h;
                    moveList.push(vo);
                }
                for (let i = h; i > 1; i--) {
                    let vo = {};
                    vo.isoX = w;
                    vo.isoY = i - 1;
                    moveList.push(vo);
                }
                for (let i = w; i > 1; i--) {
                    let vo = {};
                    vo.isoX = i - 1;
                    vo.isoY = 1;
                    moveList.push(vo);
                }
                this.moveList = moveList;
            }
            return this.moveList;
        }
        static getPos(index) {
            return this.curMoveList[index];
        }
        static getNextIndex(index) {
            return this.curMoveList[index + 1] == undefined ? 0 : index + 1;
        }
        static getNextPos(i) {
            let index = this.getNextIndex(i);
            return this.getPos(index);
        }
        static getLength(sx, sy, endX, endY) {
            let x1 = endX - sx;
            let y1 = endY - sy;
            if (x1 == 0 && y1 == 0) {
                return 0;
            }
            let len = Math.sqrt(x1 * x1 + y1 * y1);
            return len;
        }
        static drawBrokenLine(_lineSpr, sx, sy, endX, endY, sectionLen, curColor, lineWidth) {
            _lineSpr.graphics.clear();
            let x1 = endX - sx;
            let y1 = endY - sy;
            let len = this.getLength(sx, sy, endX, endY);
            if (len == 0) {
                return;
            }
            let nx = x1 / len;
            let ny = y1 / len;
            if (isNaN(nx) || isNaN(ny)) {
            }
            else {
                let mLen = sectionLen;
                let m = len / mLen;
                let x2 = sx;
                let y2 = sy;
                let l = [];
                l.push(new Laya.Point(x2, y2));
                for (let i = 0; i < m; i++) {
                    x2 += nx * mLen;
                    y2 += ny * mLen;
                    l.push(new Laya.Point(x2, y2));
                    if (l.length % 2 == 1) {
                        let fx = l[i - 1].x;
                        let fy = l[i - 1].y;
                        let toX = l[i].x;
                        let toY = l[i].y;
                        _lineSpr.graphics.drawLine(fx, fy, toX, toY, curColor, lineWidth);
                    }
                }
            }
        }
        static getAvatarPos(heroCfg, index, isoX, isoY, owner) {
            let ox = FightUtils.IsoxToPosX(isoX);
            let oy = FightUtils.IsoyToPosY(isoY, owner);
            return this.convertAvatarPos(heroCfg, index, ox, oy);
        }
        static getAvataLocalrPos(heroId, index, owner) {
            let heroCfg = HeroListProxy.Ins.getCfgById(heroId);
            let ox = ComposeConfig.cellW / 2;
            let oy = ComposeConfig.cellH / 2;
            return this.convertAvatarPos(heroCfg, index, ox, oy);
        }
        static convertAvatarPos(heroCfg, index, ox, oy) {
            let w = ComposeConfig.cellW;
            let h = ComposeConfig.cellH;
            let pos = new Laya.Point();
            if (heroCfg.f_qua >= FightValueConfig.MAX_QUA) {
                pos.x = ox;
                pos.y = oy;
            }
            else {
                let div = 8;
                switch (index) {
                    case 0:
                        pos.x = ox;
                        pos.y = oy - h / div;
                        break;
                    case 1:
                        pos.x = ox - w / div;
                        pos.y = oy + h / div;
                        break;
                    case 2:
                        pos.x = ox + w / div;
                        pos.y = oy + h / div;
                        break;
                }
            }
            return pos;
        }
        static getWalkByType(type) {
            if (!this.walks) {
                this.walks = [];
                this.walks.push(new WalkList(EMonsterPos.Owner));
                this.walks.push(new WalkList(EMonsterPos.OtherPlayer));
            }
            return this.walks.find(o => o.type == type);
        }
        static buildWalkList(old, _walkVo, owner) {
            let walk = this.getWalkByType(owner);
            let paths = walk.splitPath;
            let cur = _walkVo.index;
            let oldIndex = walk.rangleList.findIndex(o => old >= o.min && old <= o.max);
            let curIndex = walk.rangleList.findIndex(o => cur >= o.min && cur <= o.max);
            if (oldIndex == curIndex) {
                return [walk.createMoveVo(old, _walkVo.index, _walkVo, owner)];
            }
            else {
                let v1 = walk.createMoveVo(old, walk.rangleList[oldIndex].max, _walkVo, owner);
                let v2 = walk.createMoveVo(walk.rangleList[curIndex].min, _walkVo.index, _walkVo, owner);
                return [v1, v2];
            }
        }
        static getRegion(owner, oldIndex) {
            let walk = this.getWalkByType(owner);
            let path = walk.splitPath;
            let vo = path[oldIndex];
            if (vo) {
                return vo.region;
            }
            LogSys.Error(`did't not find...${oldIndex}`);
            return EIsoRegion.Null;
        }
        static isOwnerCanMove(mIsoX, mIsoY) {
            if (mIsoX >= 0 && mIsoX <= ComposeConfig.mapW - 1 && mIsoY >= 0 && mIsoY <= ComposeConfig.mapH - 1) {
                return true;
            }
        }
        static calculateFightRadiu(heroId) {
            let cfg = HeroListProxy.Ins.getCfgById(heroId);
            let radiu = ComposeConfig.cellW / 3 * (cfg.f_range);
            return radiu;
        }
        static cloneStElement(vo) {
            let _v = new stElement();
            _v.fid = vo.fid;
            _v.num = vo.num;
            _v.playerId = vo.playerId;
            _v.uid = vo.uid;
            _v.x = vo.x;
            _v.y = vo.y;
            return _v;
        }
        static convertProgressVal(w, cur, max) {
            let v = cur / max;
            if (v == 0) {
                return 1;
            }
            if (v > 1) {
                v = 1;
            }
            return v * w;
        }
    }

    class SmallFingerView extends ui.views.compose.guide.ui_guide_handUI {
        constructor() {
            super();
            this.useTime = 1000;
            this.targetSpr = new Laya.Sprite();
            this._start = new Laya.Point();
            this._end = new Laya.Point();
            this.tween = new Laya.Tween();
            this.targetSpr.alpha = GuideRect.Alpha;
            this.addChildAt(this.targetSpr, 0);
            DebugUtil.draw(this, "#ff0000", 30, 30, 0, 0, true);
        }
        show(posStr) {
            const startX = 0;
            const startY = 2;
            let arr = posStr.split("|");
            let a = arr[0].split("-");
            let b = arr[1].split("-");
            let posX1 = parseInt(a[0]);
            let posY1 = parseInt(a[1]);
            let posX2 = parseInt(b[0]);
            let posY2 = parseInt(b[1]);
            let owner = EMonsterPos.Owner;
            let sx = FightUtils.IsoxToPosX(posX1);
            let sy = FightUtils.IsoyToPosY(posY1, owner);
            let ex = FightUtils.IsoxToPosX(posX2);
            let ey = FightUtils.IsoyToPosY(posY2, owner);
            let ox = sx - startX;
            let oy = sy - startY;
            ;
            let offsetX = 0;
            let offsetY = 0;
            this._start.x = offsetX + ox;
            this._start.y = offsetY + oy;
            this._end.x = ex - sx + offsetX + ox;
            this._end.y = ey - sy + offsetY + oy;
            let checkList = [];
            checkList.push(new Laya.Point(posX1, posY1), new Laya.Point(posX2, posY2));
            this.drawGreen(checkList);
            if (this.useAnim) {
                this.img1.visible = true;
                this.img1.x = this._start.x;
                this.img1.y = this._start.y;
                this.onPlayEnd();
            }
            else {
                this.img1.visible = false;
            }
        }
        drawGrid(ox, oy) {
            let graphics = this.targetSpr.graphics;
            let offset = 0;
            graphics.drawRect(ox * ComposeConfig.cellW, (oy - 1) * ComposeConfig.cellH + offset, ComposeConfig.cellW, ComposeConfig.cellH, "#000000");
        }
        drawGreen(posList) {
            this.targetSpr.graphics.clear();
            for (let i = 0; i < ComposeConfig.mapW; i++) {
                for (let n = 0; n < ComposeConfig.mapH; n++) {
                    let find;
                    for (let u = 0; u < posList.length; u++) {
                        let o = posList[u];
                        if (o.x == i && o.y == n) {
                            find = true;
                        }
                    }
                    if (!find) {
                        this.drawGrid(i, ComposeConfig.mapH - n);
                    }
                }
            }
        }
        onPlayEnd() {
            this.img1.x = this._start.x;
            this.img1.y = this._start.y;
            this.tween.to(this.img1, { x: this._end.x, y: this._end.y }, this.useTime, null, new Laya.Handler(this, this.onPlayEnd));
        }
        hide() {
            if (this.parent) {
                this.removeSelf();
            }
            this.tween.clear();
        }
    }

