    class LoadingView extends ViewBase {
        constructor() {
            super(...arguments);
            this.PageType = EPageType.None;
            this.checkGuide = false;
            this.initProgressW = 0;
            this._curVal = 0;
            this._tween = new Laya.Tween();
        }
        onEnter() {
        }
        onExit() {
            E.taLoginTrack("loadingcomplete");
            this.disposeEffect();
        }
        onFirstInit() {
            if (!this.UI) {
                this.UI = this._ui = new LoadingUI();
                this.yellowbg = new Laya.Sprite();
                this._ui.progressSkinBg.addChild(this.yellowbg);
                this.initProgressW = this._ui.progressSkinBg.width;
            }
        }
        disposeEffect() {
            if (this.effect) {
                this.effect.dispose();
                this.effect = null;
            }
        }
        onInit() {
            this.disposeEffect();
            if (!initConfig.disable_loading_effect) {
                this.effect = SpineEffectMgr.createLoopNoSimpleEffect(`o/spine/scene/dutiao/dutiao`, this._ui.kedu);
            }
            E.taLoginTrack("startloading");
            this.initUI();
            if (this.Data instanceof LoadingVo) {
                let vo = this.Data;
                this.playAnim(vo);
            }
        }
        onAddLoadRes() {
        }
        onAddEventListener() {
        }
        onChangeLanguage() {
        }
        UpdateProgress(num) {
            if (this._ui.destroyed) {
                return;
            }
            this._curVal = num;
            let showKedu = true;
            let flag = true;
            let v = Math.floor(num * 100).toString();
            this._ui.progressTf.text = `正在加载中...${v}%`;
            if (num > 0 && num <= 1) {
                if ((num * 100 > 50) && !this._flag) {
                    E.taLoginTrack("loading50");
                    this._flag = true;
                }
                this._ui.progressSkinBg.width = this.initProgressW * num;
                this.keduPosX = this._ui.progressSkinBg.width;
            }
            else if (num <= 0) {
                showKedu = false;
            }
            else {
                this._ui.progressSkinBg.width = this.initProgressW;
                this.keduPosX = this._ui.progressSkinBg.width;
            }
            if (showKedu) {
                this._ui.progressSkinBg.visible = true;
                this._ui.kedu.visible = true;
            }
            else {
                this._ui.progressSkinBg.visible = false;
                this._ui.kedu.visible = false;
            }
            this.yellowbg.graphics.clear();
            this.yellowbg.graphics.drawRect(0, 0, this._ui.progressSkinBg.width, this._ui.progressSkinBg.height, "#ffff00");
        }
        set keduPosX(x) {
            this._ui.kedu.x = x;
        }
        initUI() {
        }
        playAnim(vo) {
            let start = vo.start;
            let end = vo.end;
            let complete = vo.callBack;
            let duration = vo.duration;
            this._tween.clear();
            this.curVal = start;
            this._tween.to(this, { curVal: end }, duration, null, complete);
        }
        set curVal(val) {
            this.UpdateProgress(val);
        }
        get curVal() {
            return this._curVal;
        }
    }

    class FightReportVo {
        constructor(_data) {
            this.rowCount = 3;
            this.selfHeros = [];
            this.enemyHeros = [];
            this.data = _data;
            let arr = _data.superHeroFids.split("|");
            this.selfHeros = this.parseHeros(arr[0]);
            this.enemyHeros = this.parseHeros(arr[1]);
        }
        get maxHeroRow() {
            let len = Math.max(this.selfHeros.length, this.enemyHeros.length);
            let n = Math.ceil(len / this.rowCount);
            return Math.max(1, n);
        }
        get botY() {
            let _cellHeight = 295 + this.maxHeroRow * 80;
            return _cellHeight;
        }
        get cellHeight() {
            let botHeight = 60;
            return this.botY + botHeight;
        }
        parseHeros(data) {
            let heroids = [];
            if (!StringUtil.IsNullOrEmpty(data)) {
                let heros = data.split("-");
                for (let i = 0; i < heros.length; i++) {
                    let s = heros[i];
                    if (!StringUtil.IsNullOrEmpty(s)) {
                        heroids.push(parseInt(s));
                    }
                }
            }
            return heroids;
        }
        get resultDesc() {
            let arr = E.getLang("fightresulttypes").split("|");
            return arr[(this.data.result - 1) * 2 + this.data.win] || "";
        }
    }

    class ItemSlotCtl extends Laya.EventDispatcher {
        constructor(skin) {
            super();
            this.skin = skin;
            this.skin.on(Laya.Event.DISPLAY, this, this.onDisplay);
            this.skin.on(Laya.Event.UNDISPLAY, this, this.onunDisplay);
        }
        onClickHandler(e) {
            e.stopPropagation();
            if (!this._vo) {
                return;
            }
            if (!this._isClick) {
                return;
            }
            FunctionModel.Ins.showItemTip(this._vo, this.skin);
        }
        onDisplay() {
            this.skin.on(Laya.Event.CLICK, this, this.onClickHandler);
        }
        onunDisplay() {
            this.dispose();
        }
        setData(_vo, isClick = true) {
            this._vo = _vo;
            this._isClick = isClick;
            if (!this._vo) {
                return;
            }
            if (this.skin.quality) {
                this.skin.quality.skin = _vo.quaIcon();
            }
            this.skin.icon.skin = "";
            this.skin.icon.skin = _vo.getIcon();
            this.skin.tf1.text = _vo.count.toString();
            this.disposeSE();
            let cfg = ItemProxy.Ins.getCfg(_vo.cfgId);
            if (cfg.f_iconeffect != "") {
                if (!this.skel) {
                    this.skel = SpineEffectMgr.createSimpleEffectSpineCache(`o/spine/succeed/${cfg.f_iconeffect}/${cfg.f_iconeffect}`, this.skin.sp1, this.skin.width / 2, this.skin.height / 2);
                }
                this.skel.play(0, true);
            }
        }
        disposeSE() {
            if (this.skel) {
                this.skel.dispose();
                this.skel = null;
            }
        }
        dispose() {
            this.disposeSE();
            this._vo = null;
            this.skin.off(Laya.Event.CLICK, this, this.onClickHandler);
        }
    }
