    class BossCutdownView extends ui.views.compose.fightcell.ui_boss_bloodUI {
        constructor() {
            super();
            this.model = ComposeModel.Ins;
        }
        init() {
            this.clear();
            Laya.timer.frameLoop(1, this, this.onFrameLoop);
            this.on(Laya.Event.DISPLAY, this, this.onDisplay);
            this.on(Laya.Event.UNDISPLAY, this, this.onUnDisplay);
        }
        onDisplay() {
            this.model.on(ComposeEvent.Pause, this, this.onPause);
            this.model.on(ComposeEvent.Play, this, this.onPlay);
            this.clear();
            this.onCutDown();
        }
        onPause() {
            Laya.timer.clear(this, this.onCutDown);
        }
        onPlay() {
            this.onCutDown();
        }
        onUnDisplay() {
            this.model.off(ComposeEvent.Pause, this, this.onPause);
            this.model.off(ComposeEvent.Play, this, this.onPlay);
        }
        clear() {
            this.timeTf.text = "";
        }
        onCutDown() {
            if (this.parent) {
                let severTime = this.model.curAdapter.clockTimeMs;
                let sub = this.monster.vo.disappearTime * 1000 - severTime;
                if (sub < 0) {
                    this.dispose();
                    return;
                }
                this.timeTf.text = (sub / 1000).toFixed(1) + "s";
                Laya.timer.once(100, this, this.onCutDown);
            }
        }
        dispose() {
            Laya.timer.clear(this, this.onCutDown);
            Laya.timer.clear(this, this.onFrameLoop);
            this.removeSelf();
            this.curParent = null;
        }
        onFrameLoop() {
            this.x = this.monster.coreSpine.skeleton.x - this.width / 2;
            this.y = this.monster.coreSpine.skeleton.y + FightValueConfig.OffsetCutDownY;
            if (!this.parent && this.curParent) {
                this.curParent.addChild(this);
            }
        }
    }

    function normalize(x, y) {
        return Math.sqrt(x * x + y * y);
    }
    function Rad2Deg(radian) {
        return Laya.Utils.toAngle(radian);
    }
    function dot(x1, y1, x2, y2) {
        let len1 = normalize(x1, y1);
        let len2 = normalize(x2, y2);
        x1 /= len1;
        y1 /= len1;
        x2 /= len2;
        y2 /= len2;
        let d = x1 * x2 + y1 * y2;
        return d;
    }
    function vectorAngle(x1, y1, x2, y2) {
        if (x1 == x2 && y1 == y2) {
            return;
        }
        var cosAngle = (x1 * x2 + y1 * y2) / (normalize(x1, y1) * normalize(x2, y2));
        var aCosAngle = Math.acos(cosAngle);
        var angle = Rad2Deg(aCosAngle);
        let d1 = dot(x1, y1, x2, y2);
        let d2 = dot(x1, y1, 0, -1);
        if (d1 > 0 && d2 > 0 || d1 < 0 && d2 > 0) {
            angle = -angle;
        }
        return angle;
    }
    class ShootAvatar extends Laya.Image {
        constructor() {
            super();
            this.OFFSET_Y = 0;
            this.anchorX = 0.5;
            this.anchorY = 0.5;
        }
        get flyTime() {
            return ShootAvatar.ShootTime / AnimConfig.AnimScale;
        }
        addDebugShoot(sx, sy, a) {
            if (debug) {
                let sp = new Laya.Image();
                sp.x = sx;
                sp.y = sy;
                sp.anchorX = sp.anchorY = 0.5;
                sp.rotation = a;
                sp.skin = this.curURL;
                let sk = new Laya.Sprite();
                sp.addChild(sk);
                sk.graphics.drawRect(0, 0, sp.width, sp.height, null, "#ff0000");
                this._avatar.parent.addChild(sp);
                let sp1 = new Laya.Sprite();
                sp1.x = sx;
                sp1.y = sy;
                sp1.graphics.drawCircle(0, 0, 5, null, "#ff0000");
                this._avatar.parent.addChild(sp1);
            }
        }
        startMove(sx, sy, ex, ey) {
            this.x = sx;
            this.y = sy;
            let a = vectorAngle(ex - this.x, ey - this.y, 1, 0);
            this.rotation = a;
            if (this._tween) {
                this._tween.clear();
            }
            else {
                this._tween = new Laya.Tween();
            }
            this._tween.to(this, { x: ex, y: ey }, this.flyTime, null, new Laya.Handler(this, this.onCompleteHander));
        }
        moveAvatar(id, pet, cur1, ox = 0, oy = 0) {
            this.ox = ox;
            this.oy = oy;
            let shoot = Laya.Utils.getQueryString("shootres");
            if (shoot) {
                id = parseInt(shoot);
            }
            this.curURL = `o/bullet/${id}.png`;
            Laya.loader.load(this.curURL, new Laya.Handler(this, this.onComplete, [pet, cur1]));
        }
        onComplete(avatar, cur1) {
            this.skin = this.curURL;
            let ox = 0;
            let oy = 0;
            let bulletX = ox;
            let bulletY = oy;
            this._avatar = avatar;
            this.startMove(avatar.x + bulletX, avatar.y + bulletY, cur1.x + this.ox, cur1.y - this.OFFSET_Y + this.oy);
        }
        onCompleteHander() {
            this.destroy();
        }
    }
    ShootAvatar.ShootTime = 466;

