    class BulletViewSpine extends BulletView {
        constructor() {
            super();
        }
        moveAvatar(startX, startY, endX, endY) {
            let id = this.resId;
            let effect = SpineEffectMgr.playOnceEnd(`o/spine/skill/${id}/${id}`, this, new Laya.Handler(this, this.onPlayEnd));
            this.effect = effect;
            this.effect.once(Laya.Event.COMPLETE, this, this.onComplete, [startX, startY, endX, endY]);
        }
        onPlayEnd() {
            this.dispose();
        }
        onComplete(startX, startY, endX, endY) {
            if (this.pass) {
                this.effect.once(Laya.Event.LABEL, this, this.onLabel, [startX, startY, endX, endY]);
            }
            else {
                this.startMove(startX, startY, endX, endY);
            }
        }
        onLabel(startX, startY, endX, endY, e) {
            if (e.name == "show") {
                let p = new Laya.Point(endX - startX, endY - startY);
                p.normalize();
                let time = this.effect.duration * 1000;
                let per = time / this.flyTime;
                this.flyTime = time;
                endX = startX + p.x * ComposeConfig.cellW * per;
                endY = startY + p.y * ComposeConfig.cellH * per;
                this.startMove(startX, startY, endX, endY);
            }
        }
        onMoveEnd() {
        }
    }

    class AvatarEffect {
        constructor() {
            this.sumTime = 0;
            this.model = ComposeModel.Ins;
        }
        get isIce() {
            return this.data && (this.data.url == "o/skill/ice.png");
        }
        onDelEffectCardUid(vo) {
            if (this.data && this.data.playerId == vo.playerId && this.data.cardUid == vo.cardSerialNum) {
                this.dispose();
            }
        }
        onLoop() {
            this.sumTime += Laya.timer.delta;
            if (this.sumTime < FightValueConfig.delayMS) {
                return;
            }
            if (this.avatar.isDestory) {
                this.dispose();
                return;
            }
            if (this.avatar.coreSpine) {
                let skel = this.avatar.coreSpine.skeleton;
                if (skel && skel.parent) {
                    if (!this.effect) {
                        if (this.data.url.indexOf(".png") != -1) {
                            this.effect = new IceEffect(this.data.url);
                            this.effect.setParent(this.parent);
                        }
                        else {
                            this.effect = SpineEffectMgr.createLoopNoSimpleEffect(this.data.url, this.parent);
                        }
                    }
                    let parent = skel.parent;
                    let ox = 0;
                    let oy = 0;
                    if (this.data.type == EEffectTarget.Hero) {
                        ox = ComposeConfig.cellW;
                        oy = ComposeConfig.cellH;
                    }
                    ox += this.data.offsetX || 0;
                    oy += this.data.offsetY || 0;
                    this.effect.setPos(parent.x + ox + skel.x, parent.y + oy + skel.y);
                }
            }
        }
        dispose() {
            this.model.off(ComposeEvent.DelEffectCardUid, this, this.onDelEffectCardUid);
            this.model.off(ComposeEvent.MonsterRemove, this, this.onMonsterRemove);
            Laya.timer.clear(this, this.onLoop);
            if (this.effect) {
                this.effect.dispose();
                this.effect = null;
            }
        }
        onMonsterRemove(uid) {
            if (this.data.deadMonsterUID == uid) {
                this.dispose();
            }
        }
        load() {
            if (this.data.cardUid) {
                this.model.on(ComposeEvent.DelEffectCardUid, this, this.onDelEffectCardUid);
            }
            this.model.on(ComposeEvent.MonsterRemove, this, this.onMonsterRemove);
            Laya.timer.frameLoop(1, this, this.onLoop);
        }
    }

