    class TowerBaseAvatar {
        constructor() {
            this.effectList = [];
            this.isDestory = false;
            this.chindIndex = -1;
            this.isLoaded = false;
            this.playSpeed = 1;
        }
        updatePlaybackRate() {
            let v = this.playSpeed * FightValueConfig.speedScale;
            if (this.coreSpine) {
                this.coreSpine.playbackRate(v);
            }
        }
        playOnceEffect(url, layer, offsetY) {
            if (!this.isDestory) {
                if (this.coreSpine && this.coreSpine.skeleton) {
                    SpineEffectMgr.playAvatarEffectOnce(this.model.fightView.getLayer(EFightLayer.HitMonsterLayer), this, url, 0, offsetY);
                }
            }
            else {
                LogSys.Warn(`playOnceEffect fail ${url},avatar is isDestory!`);
            }
        }
        get model() {
            return ComposeModel.Ins;
        }
        dispose() {
            this.isDestory = true;
            this.playSpeed = 1;
            this.chindIndex = -1;
            while (this.effectList.length) {
                let cell = this.effectList.shift();
                cell.dispose();
            }
            if (this.coreSpine) {
                if (this.coreSpine.skeleton) {
                    let src = this.coreSpine.skeleton.getComponent(FightMonsterDebug);
                    if (src) {
                        src.destroy();
                    }
                }
                this.coreSpine.playbackRate(1);
                this.coreSpine.off(Laya.Event.COMPLETE, this, this.onSpine1Complete);
                this.coreSpine.dispose();
                this.coreSpine = null;
            }
        }
        bindEffect(url, ox = 0, oy = 0) {
            this.disposeBindEffect(url);
            FightFactory.createAvatarEasyEffect(this, url, ox, oy);
        }
        disposeBindEffect(url) {
            let cellIndex = this.effectList.findIndex(o => o.resURL == url);
            if (cellIndex != -1) {
                this.effectList[cellIndex].dispose();
            }
        }
    }

    class TowerAvatarCheck extends Laya.Script {
        onAwake() {
            this.model = ComposeModel.Ins;
            Laya.timer.frameLoop(1, this, this.onLoop);
        }
        onLoop() {
            if (this.owner.parent) {
                if (this.avatar.vo) {
                    let uid = this.avatar.vo.uid;
                    if (this.model && this.model.removeUIDs.indexOf(uid) != -1) {
                        this.model.event(ComposeEvent.MonsterRemove, uid);
                    }
                }
            }
            else {
                this.clear();
                this.destroy();
            }
        }
        clear() {
            this.model = null;
            Laya.timer.clear(this, this.onLoop);
        }
        onDestroy() {
            this.clear();
            this.avatar = null;
        }
    }

    class TowerAvatarView extends TowerBaseAvatar {
        constructor() {
            super();
            this.effects = [];
            this.bloodFlys = [];
            this.skillBuffList = [];
            this._vis = false;
            this.oldIndex = -1;
            this.model.on(ComposeEvent.AddFrontEffect, this, this.onAvatarEffect);
            this.model.on(ComposeEvent.FightResClear, this, this.dispose);
            this.model.on(ComposeEvent.PlayOnceEffect, this, this.onPlayOnceEffect);
            this.model.on(ComposeEvent.MonsterPlayOnceAnim, this, this.onPlayOnceAnim);
        }
        monsterPlayAnimOnceBack() {
            this.coreSpine.play(EAvatarAnim.MonsterMove, undefined, undefined, undefined, undefined, undefined, true);
        }
        onPlayOnceAnim(uid, anim) {
            if (this.vo && this.vo.uid == uid) {
                if (this.coreSpine) {
                    this.coreSpine.play(anim, this, this.monsterPlayAnimOnceBack);
                }
            }
        }
        get hasIce() {
            if (this.effects) {
                for (let i = 0; i < this.effects.length; i++) {
                    let effect = this.effects[i];
                    if (effect.isIce) {
                        return true;
                    }
                }
            }
            return false;
        }
        onPlayOnceEffect(obj) {
            if (this.checkTarget(obj)) {
                this.playOnceEffect(obj.url, obj.layer, obj.offsetY);
            }
        }
        checkTarget(obj) {
            if (obj.type == EEffectTarget.Monster && this.vo && obj.uid && obj.uid == this.vo.uid) {
                return true;
            }
        }
        onAvatarEffect(data) {
            if (this.checkTarget(data)) {
                this.createAvatarEffect(data);
            }
        }
        createAvatarEffect(data) {
            this.effects.push(FightFactory.createAvatarEffect(this, data));
        }
        stop() {
            this.coreSpine.stop();
        }
        init() {
            this.initEvt();
            this.coreSpine = this.create();
        }
        create() {
            return FightFactory.createFrameByMonsterBirth(this.vo, this, this.onSpine1Complete);
        }
        initEvt() {
            this.model.on(ComposeEvent.MonsterMove, this, this.onMonsterMove);
        }
        onMonsterMove(vo) {
            if (vo.uid == this.vo.uid) {
                if (!this.visible) {
                    let _newBir = this.vo;
                    if (_newBir) {
                        let sub = _newBir.birthTime - this.model.curAdapter.clockTimeMs;
                        if (sub > 0) {
                            _newBir.birthTime = this.model.curAdapter.clockTimeMs;
                            if (this.model.fightView) {
                                this.model.fightView.updateMonsterCount();
                            }
                        }
                    }
                }
                this.moveTo(vo);
            }
        }
        addAvatarCheck() {
            this._avatarCheck = this.coreSpine.skeleton.addComponent(TowerAvatarCheck);
            this._avatarCheck.avatar = this;
        }
        stopMove() {
            if (this._moveTween) {
                this._moveTween.clear();
                this._moveTween = null;
            }
        }
        dispose() {
            super.dispose();
            this.effects = null;
            this.model.off(ComposeEvent.AddFrontEffect, this, this.onAvatarEffect);
            this.model.off(ComposeEvent.FightResClear, this, this.dispose);
            this.model.off(ComposeEvent.MonsterMove, this, this.onMonsterMove);
            this.model.off(ComposeEvent.PlayOnceEffect, this, this.onPlayOnceEffect);
            this.model.off(ComposeEvent.MonsterPlayOnceAnim, this, this.onPlayOnceAnim);
            this.bloodFlys = [];
            while (this.skillBuffList.length) {
                this.skillBuffList.shift();
            }
            this.oldIndex = -1;
            this.isLoaded = false;
            if (this.bloodTxt) {
                this.bloodTxt.dispose();
                this.bloodTxt = null;
            }
            if (this.bloodView) {
                this.bloodView.dispose();
                this.bloodView = null;
            }
            if (this.bossCutdown) {
                this.bossCutdown.dispose();
                this.bossCutdown = null;
            }
            this.stopMove();
            if (this._avatarCheck) {
                this._avatarCheck.destroy();
                this._avatarCheck = null;
            }
        }
        addToParent() {
            if (!this.coreSpine) {
                LogSys.Error(`....addToParent fail!`);
                return;
            }
            let skel = this.coreSpine.skeleton;
            if (this.chindIndex == -1) {
                this.parent.addChild(skel);
            }
            else {
                this.parent.addChildAt(skel, this.chindIndex);
            }
            this.updatePlaybackRate();
            this.addDebug();
            let _newObj = this.vo;
            if (_newObj && _newObj.scale != undefined) {
                this.updateScale(_newObj.scale);
            }
            this.reconnectionCheck();
        }
        reconnectionCheck() {
            let _list = this.model.avatarEffectList;
            for (let i = 0; i < _list.length; i++) {
                let vo = _list[i];
                if (this.checkTarget(vo)) {
                    _list.splice(i, 1);
                    this.createAvatarEffect(vo);
                }
            }
        }
        onSpine1Complete() {
            this.isLoaded = true;
            if (!this.isDestory) {
                this.addToParent();
                this.dir = EAvatarDir.Right;
                this.moveTo(this.tmpWalkVo);
                if (this.vo.blood > 0) {
                    this.bloodView = FightFactory.createBloodImg(this);
                }
                let monsterType = this.model.fightTypeAdaper.monsterCfg.getCfgMonsterid(this.vo.fid).f_monster_type;
                this.monsterType = monsterType;
                if (monsterType == EMonsterType.Boss || monsterType == EMonsterType.LimitTimeBoss) {
                    let offsetSec = this.model.curAdapter.getDisappearTime(this.vo.fid);
                    let curTime = this.model.curAdapter.clockTimeMs / 1000;
                    if (!this.vo.disappearTime) {
                        this.vo.disappearTime = curTime + offsetSec;
                    }
                    else {
                        if (this.vo.disappearTime - curTime > offsetSec) {
                            this.vo.disappearTime = curTime + offsetSec;
                        }
                    }
                    if (!this.model.fightTypeAdaper.cfg.f_disable_boss_cutdown) {
                        this.bossCutdown = FightFactory.createCutdownTime(this);
                    }
                    this.bloodTxt = FightFactory.createFontTxt(this);
                }
                this.addAvatarCheck();
            }
        }
        addDebug() {
            if (debug) {
                this.coreSpine.skeleton.addComponent(FightMonsterDebug).avatar = this;
            }
        }
        onMoveEnd(vo) {
            this.updateDir(vo);
            if (this._moveTween) {
                this._moveTween.to(this.coreSpine.skeleton, { x: vo.tx, y: vo.ty }, vo.time);
            }
        }
        updateDir(vo) {
            if (vo.tx == this.coreSpine.skeleton.x && vo.ty == this.coreSpine.skeleton.y) {
                return;
            }
            let v;
            if (vo.tx < this.coreSpine.skeleton.x) {
                v = EAvatarDir.Left;
            }
            else if (vo.tx == this.coreSpine.skeleton.x) {
                let revert = 1;
                if (this.owner == EMonsterPos.Owner) {
                    revert = -1;
                }
                if (vo.ty < this.coreSpine.skeleton.y) {
                    v = EAvatarDir.Left;
                }
                else {
                    v = EAvatarDir.Right;
                }
                v = v * revert;
            }
            else {
                v = EAvatarDir.Right;
            }
            this.dir = v;
        }
        get owner() {
            return this.model.getOwnerType(this.vo.playerId);
        }
        updateScale(v) {
            if (this.coreSpine) {
                this.coreSpine.updateScale(v);
            }
            else {
                LogSys.Warn(`avatar未实例化...uid:${this.vo.uid}`);
            }
        }
        moveTo(_walkVo) {
            if (!_walkVo) {
                return;
            }
            this.tmpWalkVo = _walkVo;
            if (!this.isLoaded) {
                return;
            }
            let owner = this.owner;
            if (this.oldIndex != -1) {
                let walklist = FightUtils.buildWalkList(this.oldIndex, _walkVo, owner);
                if (walklist.length >= 1) {
                    let vo = walklist.shift();
                    if (!this._moveTween) {
                        this._moveTween = new Laya.Tween();
                    }
                    let _handler;
                    if (walklist.length > 0) {
                        _handler = new Laya.Handler(this, this.onMoveEnd, [walklist.shift()]);
                    }
                    this.updateDir(vo);
                    let timescale = 1;
                    this._moveTween.to(this.coreSpine.skeleton, { x: vo.tx, y: vo.ty }, vo.time * timescale, null, _handler);
                }
            }
            else {
                let walk = FightUtils.getWalkByType(owner);
                let pos = walk.paths[_walkVo.index];
                this.coreSpine.skeleton.x = pos.x;
                this.coreSpine.skeleton.y = pos.y + (owner > EMonsterPos.Owner ? FightUtils.topOffsetY : 0);
            }
            this.oldIndex = _walkVo.index;
        }
        get region() {
            return FightUtils.getRegion(this.owner, this.oldIndex);
        }
        get curPosIndex() {
            return this.oldIndex;
        }
        set dir(v) {
            this.coreSpine.dir = v;
        }
        get dir() {
            if (this.coreSpine) {
                return this.coreSpine.dir;
            }
            return EAvatarDir.Left;
        }
        set visible(v) {
            this._vis = v;
            if (this.coreSpine && this.coreSpine.skeleton) {
                this.coreSpine.skeleton.visible = v;
            }
        }
        get visible() {
            return this._vis;
        }
    }

    class HeroAvatarView extends TowerAvatarView {
        constructor() {
            super();
            this.resType = ECreateHero.HeroId;
            this.defaultScale = 1;
            this.offsetX = 0;
            this.offsetY = 0;
        }
        checkTarget(obj) {
            if (obj.type == EEffectTarget.Hero && this.heroVo && obj.uid == this.heroVo.uid) {
                return true;
            }
        }
        onSpine1Complete() {
            this.isLoaded = true;
            if (!this.isDestory) {
                if (this.heroVo) {
                    this.addHalo();
                }
                this.addToParent();
                this.laterUpdatePos();
            }
        }
        addHalo() {
            if (this.haloLayer) {
                this._halo = new HeroHalo();
                this._halo.haloLayer = this.haloLayer;
                this._halo.setHero(this);
            }
        }
        initEvt() {
        }
        init() {
            this.initEvt();
            this.coreSpine = this.create();
        }
        create() {
            return FightFactory.createHero(this.resId, this.resKey, this.defaultScale, this.defaultAnim, this, this.onSpine1Complete, this.resType);
        }
        laterUpdatePos() {
            let x;
            let y;
            if (this.heroVo) {
                let type = ComposeModel.Ins.getOwnerType(this.heroVo.playerId);
                let pos = FightUtils.getAvataLocalrPos(this.heroVo.fid, this.index, type);
                x = pos.x;
                y = pos.y;
            }
            else {
                x = this.offsetX;
                y = this.offsetY;
            }
            this.setPos(x, y);
        }
        setPos(x, y) {
            if (this.coreSpine && this.coreSpine.skeleton) {
                this.coreSpine.skeleton.pos(x, y);
            }
            else {
                LogSys.Warn(`this.coreSpine.skeleton is not init...x:${x} y:${y}`);
            }
        }
        dispose() {
            this.haloLayer = null;
            this.index = 0;
            this.heroVo = null;
            if (this._halo) {
                this._halo.dispose();
                this._halo = null;
            }
            if (this.skillBar) {
                this.skillBar.dispose();
                this.skillBar = null;
            }
            super.dispose();
        }
        walkTo(dis, dir) {
            this.dir = dir;
            this.playMove();
            Laya.timer.once(FightValueConfig.MOVE_GRID_TIME * dis, this, this.onPlayIdle);
        }
        playAtk(anim) {
            if (this.coreSpine) {
                this.coreSpine.play(anim, this, this.onPlayIdle);
            }
        }
        playMove() {
            if (this.coreSpine) {
                this.coreSpine.play(EAvatarAnim.TowerMove, null, null, null, false, true, true);
            }
        }
        onPlayIdle() {
            if (this.coreSpine) {
                this.coreSpine.play(EAvatarAnim.TowerIdle, null, null, null, false, true, true);
            }
        }
    }

