    class FightGuideDebug extends Laya.Sprite {
        constructor(target) {
            super();
            this.offsetX = 100;
            this.offsetY = 100;
            this.h = 30;
            this.target = target;
            this.alpha = 0.75;
            this.tf = new Laya.Label();
            this.tf.fontSize = 22;
            this.tf.stroke = 2;
            this.tf.strokeColor = "#000000";
            this.tf.color = "#ffffff";
            this.tf.bgColor = "#777777";
            this.tf.y = this.h;
            this.addChild(this.tf);
            Laya.timer.frameLoop(1, this, this.onLoop);
        }
        onLoop() {
            Laya.stage.addChild(this);
            let w = 200;
            let h = this.h;
            this.x = Laya.stage.width / 2 - ScreenAdapter.UIRefWidth / 2 + this.offsetX;
            this.y = this.offsetY;
            let n = 1;
            let vo = this.target;
            let curMs = vo.curMs;
            let all = vo.allMs;
            let per = curMs / all;
            this.graphics.clear();
            this.graphics.drawRect(0, 0, w, h, null, "#ffffff");
            this.graphics.drawRect(n, n, w * per - n * 2, h - n * 2, "#ff0000");
            this.tf.text = `${curMs}/${all} ms`;
        }
    }

