    class t_Box_Reward_Rate extends BaseCfg {
        constructor() {
            super();
            this._map = {};
            for (let i = 0; i < this.List.length; i++) {
                let id = this.List[i].f_box_id;
                if (!this._map[id]) {
                    this._map[id] = [];
                }
                this._map[id].push(this.List[i]);
            }
        }
        static get Ins() {
            if (!this._ins) {
                this._ins = new t_Box_Reward_Rate();
            }
            return this._ins;
        }
        GetTabelName() {
            return "t_Box_Reward_Rate";
        }
        getStById(id, type) {
            let arr = this._map[id];
            let st;
            let min = 0;
            let max = 0;
            for (let i = 0; i < arr.length; i++) {
                let cfg = arr[i];
                let a = cfg.f_quantity.split("|");
                if (cfg.f_reward == ECellType.JINBI.toString()) {
                    st = a[0] + "-" + a[1];
                }
                else {
                    if (cfg.f_drop_rate == 10000) {
                        min += parseInt(a[0]);
                        max += parseInt(a[1]);
                    }
                    else {
                        max += parseInt(a[1]);
                    }
                }
            }
            if (type == 1) {
                return st;
            }
            else if (type == 2) {
                return min + "-" + max;
            }
        }
    }

