    class PlayerVoFactory {
        static getVal(moneyInfo, type) {
            if (moneyInfo) {
                let moneyList = moneyInfo;
                for (let i = 0; i < moneyList.length; i++) {
                    let money = moneyList[i];
                    if (money.id == type) {
                        return money.count;
                    }
                }
            }
            return 0;
        }
        static str2stCellValue(v) {
            let arr = v.split("-");
            let vo = new stCellValue();
            vo.id = parseInt(arr[0]);
            vo.count = parseInt(arr[1]);
            return vo;
        }
        static mergeAttr(arr, sl = ":") {
            if (typeof arr == "string") {
                if (arr.length > 0 && arr.substr(arr.length - 1, 1) == "|") {
                    arr = arr.substr(0, arr.length - 1);
                }
                arr = [arr];
            }
            let _attrMaps = {};
            for (let i = 0; i < arr.length; i++) {
                let s = arr[i];
                if (s.length > 0) {
                    let a = s.split("|");
                    for (let n = 0; n < a.length; n++) {
                        let s1 = a[n].split(sl);
                        let id = parseInt(s1[0]);
                        let val = parseInt(s1[1]);
                        if (!_attrMaps[id]) {
                            _attrMaps[id] = 0;
                        }
                        _attrMaps[id] += val;
                    }
                }
            }
            let str = "";
            for (let n in _attrMaps) {
                str += n + sl + _attrMaps[n] + "|";
                delete _attrMaps[n];
            }
            if (str.length > 0) {
                str = str.substr(0, str.length - 1);
            }
            if (str.length > 0) {
                return str.split("|");
            }
            return [];
        }
    }
