    class HeroWeight {
        static calPercent(heroId) {
            let _heroCfg = HeroListProxy.Ins.getCfgById(heroId);
            let _all_weight = 0;
            let _curWeight = 0;
            if (!StringUtil.IsNullOrEmpty(_heroCfg.f_synthesis)) {
                let heroArr = _heroCfg.f_synthesis.split("|");
                let _heroCountMaps = {};
                let heroList = ComposeModel.Ins.refreshList;
                for (let i = 0; i < heroList.length; i++) {
                    let cell = heroList[i];
                    if (cell.playerId == MainModel.Ins.mRoleData.AccountId) {
                        if (!_heroCountMaps[cell.fid]) {
                            _heroCountMaps[cell.fid] = 0;
                        }
                        _heroCountMaps[cell.fid] += cell.num;
                    }
                }
                for (let i = 0; i < heroArr.length; i++) {
                    let _compHeroId = parseInt(heroArr[i]);
                    let _compHeroCfg = HeroListProxy.Ins.getCfgById(_compHeroId);
                    let val = t_Hero_Synthesis_Weight.Ins.getWeight(_compHeroCfg.f_qua);
                    _all_weight += val;
                    if (_heroCountMaps[_compHeroId] && _heroCountMaps[_compHeroId] > 0) {
                        _heroCountMaps[_compHeroId]--;
                        _curWeight += val;
                    }
                }
            }
            if (!StringUtil.IsNullOrEmpty(_heroCfg.f_synthesis_money)) {
                let _itemArr = _heroCfg.f_synthesis_money.split("|");
                for (let i = 0; i < _itemArr.length; i++) {
                    let cell = _itemArr[i].split("-");
                    let itemId = parseInt(cell[0]);
                    let count = parseInt(cell[1]);
                    let val = t_Hero_Synthesis_Weight.Ins.getWeight(itemId) * count;
                    _all_weight += val;
                    let have = MainModel.Ins.mRoleData.getVal(itemId);
                    if (have > count) {
                        _curWeight += val;
                    }
                    else {
                        _curWeight += have / count * val;
                    }
                }
            }
            return Math.floor(_curWeight / _all_weight * 100);
        }
    }

