    class TWZItem extends ui.views.main.ui_tuweiItemUI {
        constructor() {
            super();
            this.img.on(Laya.Event.CLICK, this, this.onclick);
            this.add.on(Laya.Event.CLICK, this, this.onAddclick);
        }
        onclick() {
            if (this._data && this._data.playerId) {
                if (this._data.status == 2) {
                    RankModel.Ins.watchPlayer(this._data.playerId);
                }
                else {
                    let req = new NewInvite_req;
                    req.pos = this._data.pos;
                    SocketMgr.Ins.SendMessageBin(req);
                }
            }
        }
        onAddclick() {
            if (initConfig.platform == PlatformConfig.TAPTAP) {
                E.ViewMgr.Open(EViewType.TWZView1);
            }
            else if (initConfig.platform == PlatformConfig.WeiXin) {
                E.sdk.goShareData('inviterId=' + MainModel.Ins.mRoleData.AccountId);
            }
        }
        setData(value) {
            if (!value)
                return;
            let itemVo = ItemViewFactory.convertItem(value.f_reward);
            this.icon.skin = itemVo.getIcon();
            this.lab.text = "+" + itemVo.count;
            this._data = TowerMainFightModel.Ins.newInvite.find(ele => ele.pos == value.f_id);
            DotManager.removeDot(this);
            if (this._data.playerId) {
                this.add.visible = false;
                this.img.visible = true;
                let headUrl = MainModel.Ins.convertHead(this._data.headUrl);
                MainModel.Ins.setTTHead(this.img, headUrl);
                if (this._data.status == 2) {
                    this.icon.visible = this.lab.visible = false;
                }
                else {
                    this.icon.visible = this.lab.visible = true;
                    DotManager.addDot(this, 20, 20);
                }
            }
            else {
                this.add.visible = true;
                this.img.visible = false;
                this.icon.visible = this.lab.visible = true;
            }
        }
    }

    class TWZItem1 extends ui.views.main.ui_tuweiItem1UI {
        constructor() {
            super();
            this._ctl = new ItemSlotCtl(this.view);
            this.view.on(Laya.Event.CLICK, this, this.onClick);
        }
        onClick() {
            if (!this._data)
                return;
            if (this._data.status == 1) {
                let req = new FirstPassRewardCoop_req;
                req.id = this._data.id;
                SocketMgr.Ins.SendMessageBin(req);
                return;
            }
            let cfg = t_First_Pass_Reward_Coop.Ins.GetDataById(this._data.id);
            FunctionModel.Ins.showItemTip(ItemViewFactory.convertItem(cfg.f_reward), this.view);
        }
        setData(value, index, type) {
            if (!value)
                return;
            this._data = TowerMainFightModel.Ins.firstPassRewardCoop.find(ele => ele.id == value.f_id);
            this.zOrder = 1000 - index;
            this.lab.text = value.f_wave + "波";
            let vo = ItemViewFactory.convertItem(value.f_reward);
            this._ctl.setData(vo, false);
            let num = RoleInfoModel.Ins.getMaxPveNum(type);
            if (num >= value.f_wave) {
                this.pro.visible = true;
                this.img.skin = "remote/base/btn_s_dwjl.png";
            }
            else {
                this.pro.visible = false;
                this.img.skin = "remote/base/btn_n_dwjl.png";
            }
            DotManager.removeDot(this);
            if (this._data) {
                if (this._data.status == 1) {
                    DotManager.addDot(this, 0, 30);
                    this.m.visible = false;
                }
                else if (this._data.status == 2) {
                    this.m.visible = true;
                }
                else {
                    this.m.visible = false;
                }
            }
            else {
                this.m.visible = false;
            }
        }
    }

