    class TowertMainShopModel extends Laya.EventDispatcher {
        constructor() {
            super();
        }
        static get Ins() {
            if (!this._ins) {
                this._ins = new TowertMainShopModel();
            }
            return this._ins;
        }
        initData() {
            this.doubleList = [];
            this.hideIdList = [];
            this.shopList = [];
            this.hotList = [];
            this.hotFreshList = [];
        }
        isRedTip(type = 0) {
            if (!FunctionModel.Ins.isOpenByFuncId(EFuncDef.Shop, false)) {
                return false;
            }
            for (let i = 0; i < this.shopList.length; i++) {
                let cfg = t_Shop.Ins.GetDataById(this.shopList[i].id);
                if (cfg) {
                    if (type == 0 || type == cfg.f_Page) {
                        if (this.shopList[i].cnt < cfg.f_free) {
                            return true;
                        }
                    }
                }
                else {
                    E.uploadErr(`stShop: id:${this.shopList[i].id} not exist!`);
                }
            }
            return false;
        }
        recharge(id) {
            E.sendTrack("shop_buy", { type: id });
            this.reqBill(id);
        }
        reqBill(id) {
            let req = new RechargeBill_req();
            req.id = id;
            SocketMgr.Ins.SendMessageBin(req);
        }
        isYDEn(id) {
            let vo = this.shopList.find(ele => ele.id == id);
            if (!vo)
                return false;
            let count = vo.cnt;
            let cfg = t_Shop.Ins.GetDataById(id);
            if (cfg.f_limit_type == 0 || count < cfg.f_limit_times) {
                if (TowerMainModel.Ins.isItemEnoughSt(cfg.f_Price)) {
                    return true;
                }
            }
            return false;
        }
    }
