    class FightPvpRoundHead extends IFightHead {
        constructor() {
            super();
            this.skin = new ui.views.compose.fightcell.ui_fight_pvpround_topUI();
        }
        init(container) {
            container.addChildAt(this.skin, 0);
            this.onInit();
            if (this.model.ownerPlayer) {
                this.skin.herart0.playerId = this.model.ownerPlayer.playerId;
                this.skin.herart1.playerId = this.model.enemyPlayer.playerId;
            }
            this.skin.centerView.init();
            this.model.on(ComposeEvent.PvpRoundStatusChange, this, this.onPvpRoundStatusChange);
            this.model.on(ComposeEvent.PvpTurnBasedMonsterNum, this, this.onPvpTurnBasedMonsterNum);
            this.onPvpTurnBasedMonsterNum(this.model.ownerMonster);
            this.onPvpTurnBasedMonsterNum(this.model.enemyMonster);
        }
        onPvpTurnBasedMonsterNum(revc) {
            if (revc) {
                if (revc.playerId == this.model.ownerPlayer.playerId) {
                    let cur = revc.total - revc.killNum;
                    this.skin.centerView.setLeft(cur, revc.total);
                }
                else {
                    let cur = revc.total - revc.killNum;
                    this.skin.centerView.setRight(cur, revc.total);
                }
            }
        }
        onShow() {
            this.onCenter();
        }
        onCenter() {
            if (!this.destroyed) {
                let _fightView = this.model.fightView;
                if (_fightView && _fightView.displayedInStage) {
                    let pos1 = _fightView.getCenterXY();
                    let pos2 = this.skin.parent.localToGlobal(new Laya.Point(this.skin.x, this.skin.y));
                    this.skin.centerView.y = pos1.y - pos2.y - this.skin.centerView.height / 2;
                    this.onPvpRoundStatusChange();
                }
                else {
                    LogSys.Warn(`onCenter fight is not in stage!`);
                }
            }
        }
        updateMonsterCount(cur, other) {
            if (this.model.curAdapter.isGuide) {
                let leftMax = this.model.ownerPlayer.maxMonster;
                let rightMax = this.model.enemyPlayer.maxMonster;
                this.model.showErrTips(cur, leftMax);
                this.skin.centerView.updateProgress(cur, other, leftMax, rightMax);
            }
        }
        set wave(_wave) {
            this.skin.centerView.waveTf.text = E.getLang("round", _wave);
        }
        set subTime(sub) {
            this.skin.centerView.timeTf.text = TimeUtil.subTimeHMS_EN(sub);
            let checkLimit = parseInt(System_RefreshTimeProxy.Ins.getVal(109)) / 1000;
            if (sub < checkLimit) {
                this.skin.centerView.timeTf.color = "#ff0000";
            }
            else {
                this.skin.centerView.timeTf.color = "#ffffff";
            }
        }
        onUpdateRoom() {
            this.updatePlayer(this.model.ownerPlayer, 0);
            this.updatePlayer(this.model.enemyPlayer, 1);
        }
        onPvpRoundStatusChange() {
            let status = this.model.fightTypeAdaper.pvpRoundStatus;
            switch (status) {
                case EPVPRoundFightStatus.Ready:
                case EPVPRoundFightStatus.SelfReadyComplete:
                    this.skin.herart0.pos(this.skin.centerView.x + 23, this.skin.centerView.y + 6);
                    this.skin.herart1.pos(this.skin.centerView.x + 498, this.skin.centerView.y + 6);
                    this.skin.centerView.fightStatus = false;
                    break;
                default:
                    this.skin.herart0.pos(84, 62);
                    this.skin.herart1.pos(451, 62);
                    this.skin.centerView.fightStatus = true;
                    break;
            }
        }
        updatePlayer(vo, k) {
            if (vo) {
                let img = this.skin[`headicon${k}`];
                let scroeTf = this.skin[`scroeTf${k}`];
                let nameTf = this.skin[`nameTf${k}`];
                let url = MainModel.Ins.convertHead(vo.headUrl);
                MainModel.Ins.setTTHead(img, url);
                scroeTf.text = vo.trophy + "";
                nameTf.text = FightUIFactory.convertNickName(vo);
            }
        }
        dispose() {
            super.dispose();
            this.skin.removeSelf();
            this.model.off(ComposeEvent.PvpTurnBasedMonsterNum, this, this.onPvpTurnBasedMonsterNum);
            this.model.off(ComposeEvent.PvpRoundStatusChange, this, this.onPvpRoundStatusChange);
        }
    }

    class PvpRoundFightAdapter extends IFightTypeAdapter {
        constructor() {
            super(EFightMode.PVP_Round);
        }
        get disableOperate() {
            if (this.pvpRoundStatus == EPVPRoundFightStatus.Ready) {
                return false;
            }
            return true;
        }
        get disableDrag() {
            let drag = parseInt(t_Battle_Config.Ins.getValueById(75));
            if (!drag) {
                if (this.disableOperate) {
                    return true;
                }
            }
            return false;
        }
        createVsSkin() {
            return new ui.views.compose.ui_fight_vsUI();
        }
        createFightTop() {
            let skin = new FightPvpRoundHead();
            return skin;
        }
        get taskTitle() {
            return "";
        }
        gambleExit() {
            if (this.pvpRoundStatus == EPVPRoundFightStatus.Ready) {
                E.ViewMgr.Open(EViewType.PvpRoundView);
            }
        }
        gambleOpen() {
            E.ViewMgr.Open(EViewType.Gamble);
            E.ViewMgr.Close(EViewType.PvpRoundView);
        }
        fightEnter() {
        }
        onRougeOpen(revc) {
            E.ViewMgr.Open(EViewType.PvpRoundCard, null, revc);
        }
        onRougeSelect(revc) {
            E.ViewMgr.Open(EViewType.PvpRoundCardPop, null, revc);
        }
        onPvpRoundStatusChange() {
            let status = this.pvpRoundStatus;
            LogSys.Log(`pvpround当前的状态:${status}`);
            switch (status) {
                case EPVPRoundFightStatus.Ready:
                    E.ViewMgr.Open(EViewType.PvpRoundReady, null, EPvpRoundReady.AllReady);
                    break;
                case EPVPRoundFightStatus.Fight:
                case EPVPRoundFightStatus.StartSelCard:
                case EPVPRoundFightStatus.EndSelCard:
                    E.ViewMgr.Close(EViewType.PvpRoundReady);
                    break;
                case EPVPRoundFightStatus.SelfReadyComplete:
                    E.ViewMgr.Open(EViewType.PvpRoundReady, null, EPvpRoundReady.WaitEmeny);
                    break;
            }
            switch (status) {
                case EPVPRoundFightStatus.Ready:
                    E.ViewMgr.Open(EViewType.PvpRoundView);
                    E.ViewMgr.Close(EViewType.PvpRoundFightView);
                    break;
                default:
                    E.ViewMgr.Close(EViewType.Gamble);
                    E.ViewMgr.Close(EViewType.PvpRoundView);
                    E.ViewMgr.Open(EViewType.PvpRoundFightView);
                    break;
            }
        }
        getSellMoney(heroId) {
            let cfg = HeroListProxy.Ins.getCfgById(heroId);
            let id;
            switch (cfg.f_qua) {
                case EHeroQua.White:
                    id = 62;
                    break;
                case EHeroQua.Blue:
                    id = 63;
                    break;
                case EHeroQua.Purple:
                    id = 64;
                    break;
                case EHeroQua.Orange:
                    id = 65;
                    break;
            }
            let str = t_Battle_Config.Ins.getValueById(id);
            return PlayerVoFactory.str2stCellValue(str);
        }
    }

