    class AtkBaseDectorator {
        constructor(source) {
            this._source = source;
        }
    }

    class AtkBuffDectorator extends AtkBaseDectorator {
        constructor(source) {
            super(source);
        }
        get model() {
            return ComposeModel.Ins;
        }
        parse(vo, _attacker, _monster) {
            if (_monster) {
                this._source.parse(vo, _attacker, _monster);
                let _skillCfg = vo.skillCfg;
                if (!StringUtil.IsNullOrEmpty(_skillCfg.f_enemy_buff)) {
                    let _enemyBuffArr = _skillCfg.f_enemy_buff.split("-");
                    let _skillBuffType = parseInt(_enemyBuffArr[0]);
                    let _skillMs = parseInt(_enemyBuffArr[1]);
                    let cfg = this.model.fightTypeAdaper.monsterCfg.getCfgMonsterid(_monster.vo.fid);
                    let iceScale = 1.5;
                    if (cfg.f_monster_type == EMonsterType.Monster) {
                        iceScale = 1.0;
                    }
                    if (_skillBuffType == ESkillBuffType.Ice) {
                        if (_monster.skillBuffList.indexOf(_skillBuffType) == -1) {
                            _monster.skillBuffList.push(_skillBuffType);
                            FightFactory.createIceSkill(_monster, _skillMs, iceScale);
                        }
                    }
                    else if (_skillBuffType == ESkillBuffType.Dizzy) {
                        if (_monster.skillBuffList.indexOf(_skillBuffType) == -1) {
                            _monster.skillBuffList.push(_skillBuffType);
                            FightFactory.createDizzySkill(_monster, _skillMs, iceScale);
                        }
                    }
                }
            }
        }
    }

    var EHitAnimatiionType;
    (function (EHitAnimatiionType) {
        EHitAnimatiionType[EHitAnimatiionType["Road"] = 1] = "Road";
        EHitAnimatiionType[EHitAnimatiionType["Directing"] = 2] = "Directing";
    })(EHitAnimatiionType || (EHitAnimatiionType = {}));

    class MonsterEffectDecorator extends AtkBaseDectorator {
        constructor() {
            super();
        }
        get model() {
            return ComposeModel.Ins;
        }
        parse(vo, _attacker, _monster) {
            if (_monster) {
                FightFactory.createNormalHit(_monster);
                let f_attack_number = vo.skillCfg.f_attack_number;
                let _skillCfg = vo.convertSkillCfg(_attacker.data.skinId);
                let offsetX = 0;
                let offsetY = 0;
                if (!StringUtil.IsNullOrEmpty(_skillCfg.f_hit_animation_offset)) {
                    let offsetArr = _skillCfg.f_hit_animation_offset.split("|");
                    offsetX = parseInt(offsetArr[0]);
                    offsetY = parseInt(offsetArr[1]);
                }
                let f_hit_animation = _skillCfg.f_hit_animation;
                if (f_hit_animation) {
                    let _monsterSkel = _monster.coreSpine.skeleton;
                    let rot = 0;
                    let sx = _monsterSkel.x;
                    let sy = _monsterSkel.y;
                    if (_skillCfg.f_hit_animation_type == EHitAnimatiionType.Road) {
                        if (_monster.region == EIsoRegion.Left || _monster.region == EIsoRegion.Right) {
                            rot = 90;
                        }
                    }
                    else if (_skillCfg.f_hit_animation_type == EHitAnimatiionType.Directing) {
                        sx = _attacker.x + 1.5 * ComposeConfig.cellW + offsetX;
                        sy = _attacker.y + 1.5 * ComposeConfig.cellH + offsetY;
                        rot = vectorAngle(_monsterSkel.x - sx, _monsterSkel.y - sy, 1, 0);
                    }
                    switch (f_attack_number) {
                        case EAttackPosType.Gird:
                            this.playGridEffect(_monster, _skillCfg);
                            break;
                        default:
                            FightFactory.createHitSkill(_skillCfg.f_hit_animation, _skillCfg.f_hit_animation_scale, sx, sy, rot);
                            break;
                    }
                }
            }
        }
        playGridEffect(_monster, _skillCfg) {
            let o = this.model.getTargetLayerXY(EEffectPos.GridCenter, _monster.vo.playerId);
            if (o) {
                let id = _skillCfg.f_hit_animation;
                let url = `o/spine/skill/${id}/${id}`;
                SpineEffectMgr.playOnce(url, o.layer, o.curX, o.curY, 0);
            }
        }
    }

    class MonsterHitSoundDecorator extends AtkBaseDectorator {
        get model() {
            return ComposeModel.Ins;
        }
        parse(vo, _attacker, _monster) {
            this._source.parse(vo, _attacker, _monster);
            if (_monster && !_monster.isDestory) {
                if (_monster.vo.playerId == MainModel.Ins.mRoleData.AccountId) {
                    let tempCfg = this.model.fightTypeAdaper.monsterCfg.getTempCfg(_monster.vo.fid);
                    if (tempCfg.f_sound > 0) {
                        E.AudioMgr.PlaySound1(`${tempCfg.f_sound}.mp3`);
                    }
                }
            }
        }
    }

    class ShootDectorator extends AtkBaseDectorator {
        parse(vo, _attacker, _monster) {
            this._source.parse(vo, _attacker, _monster);
            let avatar = _attacker.animal.getHeroAvatar(vo.index);
            if (avatar) {
                if (!this.shootCon) {
                    return;
                }
                let _skillCfg = vo.convertSkillCfg(_attacker.data.skinId);
                let offset = _attacker.animal.randomPos;
                let anim = EAvatarAnim.TowerAtk;
                if (_skillCfg.f_skill_act) {
                    anim = _skillCfg.f_skill_act;
                }
                avatar.playAtk(anim);
                if (vo.atktime > 0) {
                    let atkTime = HeroListProxy.Ins.getAtkTime(avatar.heroVo.fid);
                    let v = vo.atktime / atkTime;
                    avatar.playSpeed = v;
                    avatar.updatePlaybackRate();
                }
                let heroCon = _attacker;
                if (_monster && heroCon) {
                    let half = ComposeConfig.cellW / 2;
                    if (_attacker.parent) {
                        let start = _attacker.parent.localToGlobal(new Laya.Point(heroCon.x + offset.x + half, heroCon.y + offset.y + half));
                        let end = _monster.parent.localToGlobal(new Laya.Point(_monster.coreSpine.skeleton.x, _monster.coreSpine.skeleton.y));
                        if (end.x < start.x) {
                            avatar.dir = EAvatarDir.Left;
                        }
                        else {
                            avatar.dir = EAvatarDir.Right;
                        }
                        let bullet = FightFactory.createBullet(_skillCfg);
                        if (bullet) {
                            let shootConPos = this.shootCon.parent.localToGlobal(new Laya.Point(this.shootCon.x, this.shootCon.y));
                            let _speed = FightValueConfig.speedScale;
                            let flyTime = 0;
                            if (_skillCfg.f_bullet_speed) {
                                flyTime = _skillCfg.f_bullet_speed;
                            }
                            else {
                                flyTime = FightValueConfig.FLY_TIME;
                            }
                            bullet.flyTime = flyTime / _speed;
                            let sx = start.x - shootConPos.x;
                            let sy = start.y - shootConPos.y - ComposeConfig.cellH / 2;
                            let ex = end.x - shootConPos.x;
                            let ey = end.y - shootConPos.y;
                            bullet.pass = _skillCfg.f_bullet_spine_pass == 1;
                            bullet.moveAvatar(sx, sy, ex, ey);
                            this.shootCon.addChild(bullet);
                        }
                    }
                }
            }
            else {
                LogSys.Error(`not find destUID:${_attacker.uid}`);
            }
        }
        get shootCon() {
            let fight = ComposeModel.Ins.fightView;
            if (fight) {
                return fight.getLayer(EFightLayer.ShootLayer);
            }
        }
    }

