    class ChengHaoCtl {
        constructor(skin) {
            this._ui = skin;
            this._ui.on(Laya.Event.DISPLAY, this, this.onDisplay);
            this._ui.on(Laya.Event.UNDISPLAY, this, this.onUnDisplay);
        }
        onDisplay() {
        }
        onUnDisplay() {
            this.disEff();
        }
        setData(id, flag = true) {
            let cfg = t_Title.Ins.getCfgById(id);
            if (cfg) {
                if (cfg.f_title_icon) {
                    this._ui.img.visible = true;
                    this._ui.sp.visible = false;
                    this._ui.img.skin = t_Title.Ins.getSkinById(cfg.f_title_icon);
                }
                else if (cfg.f_animation) {
                    this._ui.img.visible = false;
                    this._ui.sp.visible = true;
                    if (flag) {
                        this.disEff();
                    }
                    if (!this.effect) {
                        this.effect = SpineEffectMgr.createLoopNoSimpleEffect(`o/spine/succeed/${cfg.f_animation}/${cfg.f_animation}`, this._ui.sp, 10, 10);
                    }
                }
            }
        }
        disEff() {
            if (this.effect) {
                this.effect.dispose();
                this.effect = null;
            }
        }
    }

    class FightVsItem {
        constructor(skin, startX, endX) {
            this._tw = new Laya.Tween();
            this.moveTime = 500;
            this._skin = skin;
            this.startX = startX;
            this.endX = endX;
        }
        get skin() {
            return this._skin;
        }
        updateItem(vo) {
            this._tw.clear();
            if (vo) {
                let item = this._skin;
                FightUIFactory.setPlayer(item, vo);
                let cfg = t_Trophy_Reward.Ins.getCfgByTrophyFront(vo.trophy);
                let sorce = item.score;
                if (sorce) {
                    this.refreshSorce(sorce, cfg);
                }
                item.lab_lv.text = `${vo.playerLevel}`;
                this._skin.x = this.startX;
                this._tw.to(this._skin, { x: this.endX }, this.moveTime);
                this.pveRefresh(item, vo);
            }
        }
        pveRefresh(item, vo) {
            if (item.ch) {
                this._ctl = new ChengHaoCtl(item.ch);
                this._ctl.setData(vo.titleId);
            }
            let cfgTr = t_Medal.Ins.getCfgByTr(vo.trophy);
            if (item.eff) {
                this._hzEff = SpineEffectMgr.createMedalEffect(item.eff, cfgTr);
            }
        }
        refreshSorce(sorce, cfg) {
            let arr = cfg.f_stage.split("-");
            sorce.img.skin = "remote/base/t_jl_d" + parseInt(arr[3]) + ".png";
            sorce.img1.skin = "remote/base/t_jl_d_" + parseInt(arr[2]) + ".png";
            sorce.img2.skin = "remote/base/t_jl_" + parseInt(arr[1]) + ".png";
            sorce.img3.skin = `o/trophyicon/${parseInt(arr[0])}.png`;
        }
        set visible(v) {
            this._skin.visible = v;
        }
        dispose() {
            if (this._hzEff) {
                this._hzEff.dispose();
                this._hzEff = null;
            }
            this._skin.destroy(true);
        }
    }

    class FightVsView extends ViewBase {
        constructor() {
            super(...arguments);
            this.autoFree = true;
        }
        onAddLoadRes() {
        }
        get winType() {
            return this.Data;
        }
        onExit() {
            this.disposeEffect();
            if (this.leftItem) {
                this.leftItem.dispose();
                this.leftItem = null;
            }
            if (this.rightItem) {
                this.rightItem.dispose();
                this.rightItem = null;
            }
            LogSys.Log(`####### 前端战斗准备阶段完成,通知后端 #######`);
            this.model.curAdapter.readyComplete();
        }
        disposeEffect() {
            if (this.effect) {
                this.effect.dispose();
                this.effect = null;
            }
        }
        onFirstInit() {
            if (!this.UI) {
                this.model = ComposeModel.Ins;
                this.UI = this._ui = this.model.fightTypeAdaper.createVsSkin();
                this.pvpTipsVisible = false;
                this.leftItem = new FightVsItem(this._ui.item0, -this._ui.item0.width, 0);
                this.rightItem = new FightVsItem(this._ui.item1, ScreenAdapter.UIRefWidth, ScreenAdapter.UIRefWidth - this._ui.item1.width);
                this.leftItem.visible = this.rightItem.visible = false;
            }
        }
        onInit() {
            this.disposeEffect();
            this.effect = SpineEffectMgr.createNoSimpleEffect(this.model.fightTypeAdaper.vs, this._ui, this._ui.width / 2, this._ui.height / 2, 0);
            this.effect.on(Laya.Event.LABEL, this, this.onLabelEvt);
            this.effect.play(0, false, this, this.onPlayEnd);
            if (typeof this._ui['monsterCntTf'] != "undefined") {
                let all = this.model.ownerPlayer.maxMonster + this.model.enemyPlayer.maxMonster;
                this._ui["monsterCntTf"].text = `${all}`;
            }
        }
        set pvpTipsVisible(v) {
            if (typeof this._ui.pvptips != "undefined") {
                this._ui.pvptips.visible = v;
            }
        }
        onEmpty() {
        }
        onLabelEvt(e) {
            if (this.destroyed) {
                return;
            }
            if (e.name == 'start') {
                this.pvpTipsVisible = true;
                this.leftItem.visible = this.rightItem.visible = true;
                if (this.model.fightTypeAdaper.mode == EFightMode.PVE) {
                    this.leftItem.updateItem(this.model.ownerPlayer);
                    this.rightItem.updateItem(this.model.enemyPlayer);
                }
                else {
                    this.leftItem.updateItem(this.model.enemyPlayer);
                    this.rightItem.updateItem(this.model.ownerPlayer);
                }
            }
            else if (e.name == 'stop1') {
                if (this.winType == EFightSceneStatus.PVP_Fight_New_Guide) {
                    if (this.effect) {
                        this.effect.pause();
                    }
                    GuideModel.Ins.event(EGuideEvent.ActionNextStep);
                    if (this.leftItem) {
                        ButtonCtl.CreateBtn(this.leftItem.skin, this, this.onEmpty, false);
                    }
                    else {
                        LogSys.Error(`leftItem is null`);
                    }
                }
            }
            else if (e.name == "end") {
                this.pvpTipsVisible = false;
                this.leftItem.visible = this.rightItem.visible = false;
            }
        }
        onPlayEnd() {
            if (this.winType == EFightSceneStatus.PVP_Fight_New_Guide) {
            }
            else {
                this.Close();
            }
        }
    }

    class FrientFightResultView extends ViewBase {
        constructor() {
            super(...arguments);
            this.mHitFull = true;
            this.autoFree = true;
            this.mMask = true;
            this.isWatchAD = false;
        }
        get model() {
            return ComposeModel.Ins;
        }
        onAddLoadRes() {
            this.addAtlas("fightresult.atlas");
        }
        clearEffect() {
            if (this._succeed) {
                this._succeed.dispose();
                this._succeed = null;
            }
        }
        onExit() {
            this.clearEffect();
            if (this.okBtn) {
                this.okBtn.dispose();
                this.okBtn = null;
            }
            if (this.adCk) {
                this.adCk.dispose();
                this.adCk = null;
            }
            if (this.lifeTimeCk) {
                this.lifeTimeCk.dispose();
                this.lifeTimeCk = null;
            }
            if (this.timeCtl) {
                this.timeCtl.dispose();
                this.timeCtl = null;
            }
            this.model.event(ComposeEvent.EnterMainScene);
        }
        onFirstInit() {
            if (!this.UI) {
                this.UI = this._ui = new ui.views.compose.ui_frient_fight_resultUI();
                this.okBtn = ButtonCtl.CreateBtn(this._ui.okBtn, this, this.onOkHandler);
                ValCtl.Create(this._ui.money1.lab, this._ui.money1.icon, ECellType.TILI, this._ui.money1.sp);
                this._ui.rewardList.itemRender = SoltItemView;
                this._ui.rewardList.renderHandler = new Laya.Handler(this, this.onRewardHandler);
                this.adCk = new CheckBoxCtl(this._ui.ck0);
                this.adCk.selectHander = new Laya.Handler(this, this.onAdCkSelect);
                this.adCk.selected = false;
                this.lifeTimeCk = new CheckBoxCtl(this._ui.ck1);
                this.lifeTimeCk.selectHander = new Laya.Handler(this, this.onLifetimeCk);
                this.lifeTimeCk.selected = false;
                this.timeCtl = new TimeCtl();
            }
        }
        onOkHandler() {
            let multi = 0;
            if (this.adCk.selected) {
                multi = 2;
            }
            else if (this.lifeTimeCk.selected) {
                multi = 3;
            }
            if (multi > 0) {
                let req = new PveMultiReward_req();
                req.multi = multi;
                req.roomId = this.model.rootId;
                SocketMgr.Ins.SendMessageBin(req);
            }
            this.Close();
        }
        onCheckHandler() {
            if (!TeQuanKaModel.Ins.isOpenZSK()) {
                E.ViewMgr.ShowMidError(E.getLang("err01"));
                return false;
            }
            return true;
        }
        onAdCkSelect(sel) {
            this.updateReward();
            if (E.sdk.canFreeLook) {
                if (sel) {
                    if (this.lifeTimeCk.selected) {
                        this.lifeTimeCk.selected = false;
                    }
                }
                return;
            }
            if (this.isWatchAD) {
                return;
            }
            if (sel) {
                const _watchKey = "FrientFightResult";
                E.sendTrack("ad_watch", { type: _watchKey });
                E.sdk.lookVideo((type) => {
                    let _sel = false;
                    switch (type) {
                        case 0:
                            break;
                        case 1:
                            E.sendTrack("ad_finish", { type: _watchKey });
                            this.isWatchAD = true;
                            _sel = true;
                            break;
                        case 2:
                            break;
                    }
                    if (this.adCk) {
                        this.adCk.selected = _sel;
                    }
                    else {
                        LogSys.Warn(`adCk is dispose...`);
                    }
                });
            }
        }
        get multiplyingPower() {
            let p = 1;
            if (this.adCk.selected) {
                p = 2;
            }
            else if (this.lifeTimeCk.selected) {
                p = 3;
            }
            return p;
        }
        convertItems() {
            let _l = [];
            let result = this._data.owner.itemList;
            let p = this.multiplyingPower;
            for (let i = 0; i < result.length; i++) {
                let o = result[i];
                let cell = new stCellValue();
                cell.count = o.count * p;
                cell.id = o.id;
                _l.push(cell);
            }
            return _l;
        }
        updateReward() {
            let l = this.convertItems();
            this._ui.rewardList.array = ItemViewFactory.cellValue2ItemVos(l);
            let p = this.multiplyingPower;
            let n = p - 1;
            if (n <= 0) {
                this._ui.phyimg.visible = false;
            }
            else {
                this._ui.phyimg.visible = true;
                let str = t_Battle_Config.Ins.getValueById(EBattle_Config.PVE_PHYSICAL_POWER);
                let itemVo = ItemViewFactory.convertItem(str);
                this._ui.itemicon.skin = IconUtils.getIconByCfgId(itemVo.cfgId);
                this._ui.countTf.text = `x${n * itemVo.count}`;
            }
        }
        onLifetimeCk(sel) {
            if (sel) {
                if (this.adCk.selected) {
                    this.adCk.selected = false;
                }
            }
            this.updateReward();
        }
        onInit() {
            this.model.fightView.updateMonsterCount();
            this.isWatchAD = false;
            let _data = this.model.fightResultVo;
            this._data = _data;
            if (!this._data) {
                this.Close();
                return;
            }
            if (this._data.data.newGuide == 1
                || this.model.ownerPlayer.playerLevel < parseInt(System_RefreshTimeProxy.Ins.getVal(92))
                || this.model.fightTypeAdaper.cfg.f_hide_wactAD) {
                this._ui.bot.visible = false;
            }
            else {
                this._ui.bot.visible = true;
            }
            this.clearEffect();
            this._succeed = SpineEffectMgr.createNoSimpleEffect(`o/spine/succeed/WIN/win`, this._ui.bg, this._ui.bg.width / 2, 90);
            this._succeed.play(0, false, this, this.onPlayEnd);
            if (TeQuanKaModel.Ins.isOpenZSK()) {
                this._ui.tf03.visible = false;
                this.lifeTimeCk.disable = false;
                this.lifeTimeCk.gray = false;
                this._ui.tf02.gray = false;
            }
            else {
                this._ui.tf03.visible = true;
                this.lifeTimeCk.disable = true;
                this.lifeTimeCk.gray = true;
                this._ui.tf02.gray = true;
            }
            this.refreshPlayer(this._ui.owner, this.model.ownerPlayer);
            this.refreshPlayer(this._ui.enemy, this.model.enemyPlayer);
            this._ui.nameTf0.text = this.model.ownerPlayer.nickName;
            this._ui.nameTf1.text = this.model.enemyPlayer.nickName;
            this.updateReward();
            let time = parseInt(System_RefreshTimeProxy.Ins.getVal(ESystemRefreshTime.PveCloseTime));
            this.timeCtl.start(time, undefined, new Laya.Handler(this, this.onTimeEndClose));
            this.updateKillNum(_data.owner.killNum, _data.enemy.killNum);
            this._ui.waveTf.text = _data.data.wave + "";
            if (_data.owner.isBest) {
                this._ui.bestImg.visible = true;
            }
            else {
                this._ui.bestImg.visible = false;
            }
        }
        onTimeEndClose() {
            this.Close();
        }
        updateKillNum(m, n) {
            if (m == 0 && n == 0) {
                m = 1;
                n = 1;
            }
            let all = m + n;
            const per = 100;
            let a = Math.floor(m / all * per);
            let b = per - a;
            this._ui.lb0.text = a + "%";
            this._ui.lb1.text = b + "%";
            let progress = this._ui.gongxiandu;
            progress.b0.width = progress.width * (a / 100);
            progress.b1.width = progress.width - progress.b0.width;
            progress.b1.x = progress.b0.width;
            progress.b2.x = progress.b0.width - progress.b2.width / 2;
        }
        refreshPlayer(skin, vo) {
            FightUIFactory.setHerdIcon(skin.headicon, vo.headUrl);
            skin.scroeTf.text = vo.trophy + "";
        }
        onRewardHandler(item) {
            item.setData(item.dataSource);
        }
        onPlayEnd() {
            this._succeed.play(1, true);
        }
    }

