    class GainVo {
        constructor() {
            this.cardPriceDoubles = [];
            this.cardList = [];
            this.skelURL = "";
            this.model.on(ComposeEvent.DelEffectCardUid, this, this.onDelHandler);
        }
        get priceDoubles() {
            let l = this.cardPriceDoubles;
            let n = 0;
            for (let i = 0; i < l.length; i++) {
                let o = l[i];
                n += o.priceDouble;
            }
            if (l.length > 0) {
                return n;
            }
            return 1;
        }
        get model() {
            return ComposeModel.Ins;
        }
        onDelHandler(targetObj) {
            let _index = this.cardList.findIndex(o => o.serialNum == targetObj.cardSerialNum);
            if (_index != -1) {
                this.cardList.splice(_index, 1);
                this.model.event(ComposeEvent.GainBtnUpdate);
            }
            let u = this.cardPriceDoubles.findIndex(o => o.cardSerialNum == targetObj.cardSerialNum);
            if (u != -1) {
                this.cardPriceDoubles.splice(u, 1);
            }
        }
        reset() {
            this.cardList = [];
            this.cardPriceDoubles = [];
        }
        update(_data) {
            let _index = this.cardList.findIndex(o => o.serialNum == _data.serialNum);
            if (_index != -1) {
                this.cardList[_index] = _data;
            }
            else {
                this.cardList.push(_data);
            }
            let u = this.cardPriceDoubles.findIndex(o => o.cardSerialNum == _data.serialNum);
            if (u != -1) {
                this.cardPriceDoubles.splice(u, 1);
            }
            let vo = new CardUiEffectVo();
            vo.cardSerialNum = _data.serialNum;
            vo.status = _data.state;
            vo.cardId = _data.cardId;
            this.cardPriceDoubles.push(vo);
            this.model.event(ComposeEvent.GainBtnUpdate);
            this.model.event(ComposeEvent.CardPriceDoubles);
        }
        get animIndex() {
            let effectIds = [];
            for (let i = 0; i < this.cardList.length; i++) {
                let cell = this.cardList[i];
                let cfg = t_Function_Card.Ins.getCfgById(cell.cardId);
                if (effectIds.indexOf(cfg.f_effect_id) == -1) {
                    effectIds.push(cfg.f_effect_id);
                }
            }
            let len = effectIds.length;
            let _animIndex = -1;
            if (len > 0) {
                let cfg = t_Battle_Effect.Ins.getByEffectId(effectIds[len - 1]);
                let k = cfg.f_effect_name;
                this.skelURL = `${cfg.f_spine_path}/${k}/${k}`;
                return cfg.f_effect_anim;
            }
            return _animIndex;
        }
        get aniRes() {
            return this.skelURL;
        }
    }
    class GainDecorator extends BaseBtnDecorator {
        constructor(btnSkin) {
            super(btnSkin);
        }
        onInit() {
            this.model.on(ComposeEvent.GainBtnUpdate, this, this.onRefresh);
            this.onRefresh();
        }
        onRefresh() {
            let gainVo = this.model.gainVo;
            let animIndex = gainVo.animIndex;
            this.startPlay(animIndex, gainVo.aniRes);
        }
        onExit() {
            this.model.off(ComposeEvent.GainBtnUpdate, this, this.onRefresh);
            this.disposeEffect();
        }
    }

    class FuncCardCellView extends ui.views.compose.fightcell.ui_func_card_cellUI {
        constructor() {
            super();
            this.selCon = new Laya.Sprite();
            this.OFFSET_X = 0;
            this.OFFSET_Y = 0;
            this.model = ComposeModel.Ins;
            this.tween = new Laya.Tween();
            this.disableIce.visible = false;
            this.aniCon.addChildAt(this.selCon, 0);
            this.OFFSET_X = this.aniCon.width / 2;
            this.OFFSET_Y = this.aniCon.height / 2;
            this.btnCtl = ButtonCtl.CreateBtn(this.btn, this, this.onBtnClickHandler, undefined, undefined, true);
            this.aniCon.btnCtl = this.btnCtl;
            let clickImgBtn = ButtonCtl.CreateBtn(this.clickImg, this, this.onClickHandler, false, undefined, true);
            this.on(Laya.Event.DISPLAY, this, this.onDisplay);
            this.on(Laya.Event.UNDISPLAY, this, this.onUnDisplay);
            this.gainDecorator = new GainDecorator(this.btn);
        }
        onCardPriceDoubles() {
            this.onUpdateLab();
        }
        onPlayPie(_result) {
            if (this.vo.data.serialNum != _result.serialNum) {
                this.timeCheckCd();
            }
        }
        onUnDisplay() {
            this.disposeEffect();
            this.model.off(ComposeEvent.CardPriceDoubles, this, this.onCardPriceDoubles);
            this.model.off(ComposeEvent.PlayPie, this, this.onPlayPie);
            this.model.off(ComposeEvent.DelEffectCardUid, this, this.onDelIceHandler);
            this.model.off(ComposeEvent.IceCards, this, this.onIceCards);
            TowerMainModel.Ins.off(TowerMainEvent.ValChangeCell, this, this.onUpdateLab);
            this.gainDecorator.onExit();
        }
        onDelIceHandler(obj) {
            let vo = this.model.iceCardsVo;
            if (vo.playerId == obj.playerId && vo.cardSerialNum == obj.cardSerialNum) {
                this.disableIce.visible = vo.bCardIce;
            }
        }
        onIceCards() {
            let vo = this.model.iceCardsVo;
            this.disableIce.visible = vo.bCardIce;
            this.pieSelect = false;
        }
        onDisplay() {
            this.gainDecorator.onInit();
            this.model.on(ComposeEvent.CardPriceDoubles, this, this.onCardPriceDoubles);
            this.model.on(ComposeEvent.DelEffectCardUid, this, this.onDelIceHandler);
            this.model.on(ComposeEvent.IceCards, this, this.onIceCards);
            this.model.on(ComposeEvent.PlayPie, this, this.onPlayPie);
            TowerMainModel.Ins.on(TowerMainEvent.ValChangeCell, this, this.onUpdateLab);
            this.onIceCards();
            let vo = this.vo;
            DebugUtil.drawTF(this, `uid:${vo.data.serialNum} card:${vo.data.fCardId}`, "#ff0000", 0, -36);
            this.timeCheckCd();
        }
        timeCheckCd() {
            if (this.vo.cdTime) {
                let sub = this.vo.cdTime - TimeUtil.serverTimeMS;
                if (sub > 0) {
                    this.aniCon.playPie(sub);
                }
            }
        }
        onUpdateLab() {
            ItemViewFactory.setlb2(this.moneyTf, this.vo.needItemVo.cfgId, this.vo.needItemVo.count);
        }
        onBtnClickHandler() {
            if (this.aniCon.pieCtl.isPlaying) {
                return;
            }
            this.model.useCard(this.vo.data.serialNum, this.vo.needItemVo);
        }
        removeCard() {
            this.tween.clear();
            let useTime = this.animTime / 2;
            this.tween.to(this, { y: FightValueConfig.cardOffsetY - this.height * 2 }, useTime);
            Laya.timer.once(useTime, this, this.dispose);
        }
        get animTime() {
            return this.model.curAdapter.cardMoveTime;
        }
        toLeft() {
            this.tween.clear();
            let oldx = this.x;
            this.tween.to(this, { x: oldx - FightValueConfig.cardCellWidth }, this.animTime);
        }
        onStageClick() {
            this.pieSelect = false;
        }
        onClickHandler() {
            if (this.model.iceCardsVo.bCardIce) {
                return;
            }
            if (this.cardCtl) {
                this.cardCtl.onSelectHandler(this);
                Laya.stage.once(Laya.Event.CLICK, this, this.onStageClick);
            }
            this.model.closeHeroTips();
            let type = EViewType.FuncCardShow;
            if (E.ViewMgr.isOpenReg(type)) {
                E.ViewMgr.Get(type).refresh(this.vo);
            }
            else {
                E.ViewMgr.Open(type, null, this.vo);
            }
        }
        setData(vo) {
            this.vo = vo;
            let cfg = vo.cfg;
            let itemVo = vo.needItemVo;
            this.moneyIcon.skin = itemVo.getIcon();
            this.onUpdateLab();
            this.aniCon.cfg = cfg;
        }
        dispose() {
            this.alpha = 1.0;
            E.ViewMgr.Close(EViewType.FuncCardShow);
            this.btnCtl.visible = true;
            this.aniCon.y = 0;
            if (this.tween) {
                this.tween.clear();
            }
            this.vo = null;
            this.removeSelf();
            Laya.Pool.recover(FuncCardCellView.CLS_KEY, this);
        }
        get angleToVector() {
            let angle = this.rotation;
            return {
                x: Math.cos(angle),
                y: Math.sin(angle)
            };
        }
        disposeEffect() {
            if (this.effect) {
                this.effect.dispose();
                this.effect = null;
            }
        }
        set pieSelect(v) {
            const offsetH = -30;
            if (v) {
                let old = this.model.cardList.find(o => o.data.serialNum == this.vo.data.serialNum);
                if (!old) {
                    return;
                }
                if (!this.effect) {
                    this.effect = SpineEffectMgr.createLoopNoSimpleEffect(`o/spine/scene/Card_Idle/Card_Idle`, this, this.width / 2, this.height / 2 + offsetH - 7.5);
                }
                this.aniCon.y = offsetH;
            }
            else {
                this.disposeEffect();
                this.aniCon.y = 0;
            }
        }
        flyAndDel() {
            this.vo.playSound();
            SpineEffectMgr.playOnce(FightValueConfig.CardPlay, this.selCon, this.OFFSET_X, this.OFFSET_Y);
            this.btnCtl.visible = false;
            this.tween.clear();
            this.tween.to(this.aniCon, { y: -200 }, FightValueConfig.cardShowTime, null, new Laya.Handler(this, this.onComplete));
        }
        alphaShow() {
            this.alpha = 0.0;
            this.tween.clear();
            this.tween.to(this, { alpha: 1.0 }, FightValueConfig.cardShowTime);
        }
        onComplete() {
            this.dispose();
        }
        updateSort() {
            this.vo.sortNum = this.rotation;
        }
        set displayAniCon(v) {
            this.aniCon.visible = v;
            this.btnCtl.visible = v;
        }
    }
    FuncCardCellView.CLS_KEY = "FuncCardCellView";

    class FuncCardCtl {
        constructor() {
            this.rot = 9;
            this.startRot = -18;
            this.model = ComposeModel.Ins;
            this.maxShowCardCount = parseInt(t_Battle_Config.Ins.getValueById(EBattle_Config.PVE_MAX_CARD));
            LogSys.Log(this.maxShowCardCount);
        }
        onInit() {
            this.model.on(ComposeEvent.UpdateCards, this, this.onRefresh);
            this.model.on(ComposeEvent.AddCard, this, this.onAddCard);
            this.onRefresh();
        }
        onAddCard(vo) {
            let n = this.con1.numChildren;
            let cell = this.createCell(vo);
            cell.timeCheckCd();
            cell.displayAniCon = false;
            FightFactory.createPveShowCard(vo.cfg.f_cardid, cell, cell.width / 2, cell.height / 2 - 5, new Laya.Handler(this, this.onAnimEnd, [cell]));
            cell.rotation = this.startRot + this.rot * n;
            cell.updateSort();
            this.view.updateCardCount();
        }
        onAnimEnd(cell) {
            cell.displayAniCon = true;
        }
        onRefresh() {
            this.clearCards();
            let cur = 0;
            this.model.cardList.sort((a, b) => {
                if (a.sortNum < b.sortNum) {
                    return -1;
                }
                else if (a.sortNum > b.sortNum) {
                    return 1;
                }
                return 0;
            });
            for (let i = 0; i < this.maxShowCardCount; i++) {
                let vo = this.model.cardList[i];
                if (vo) {
                    let cell = this.createCell(vo);
                    cell.rotation = this.startRot + this.rot * cur;
                    cell.updateSort();
                    cur++;
                }
            }
            this.view.updateCardCount();
        }
        createCell(vo, index = -1) {
            let cell = Laya.Pool.getItemByClass(FuncCardCellView.CLS_KEY, FuncCardCellView);
            cell.cardCtl = this;
            cell.setData(vo);
            cell.x = 0;
            cell.y = 0;
            if (index == -1) {
                this.con1.addChild(cell);
            }
            else {
                if (index > this.con1.numChildren - 1) {
                    index = this.con1.numChildren - 1;
                    if (index < 0) {
                        index = 0;
                    }
                }
                this.con1.addChildAt(cell, index);
            }
            return cell;
        }
        onExit() {
            this.clearCards();
            this.model.off(ComposeEvent.UpdateCards, this, this.onRefresh);
            this.model.off(ComposeEvent.AddCard, this, this.onAddCard);
        }
        clearCards() {
            while (this.con1.numChildren) {
                let cell = this.con1.getChildAt(0);
                cell.dispose();
            }
        }
        onSelectHandler(item) {
            let selitem;
            for (let i = 0; i < this.con1.numChildren; i++) {
                let cell = this.con1.getChildAt(i);
                if (cell == item) {
                    selitem = cell;
                }
                else {
                    cell.pieSelect = false;
                }
            }
            if (selitem) {
                selitem.pieSelect = true;
            }
        }
        onMoveCard(moveVo) {
            for (let i = 0; i < this.con1.numChildren; i++) {
                let cell = this.con1.getChildAt(i);
                cell.pieSelect = false;
                if (cell.vo.data.serialNum == moveVo.uid) {
                    cell.flyAndDel();
                    Laya.timer.once(FightValueConfig.cardFlyTime * 2, this, this.onDelEnd, [cell.rotation, i]);
                }
            }
        }
        onDelEnd(rot, index) {
            let uids = [];
            for (let i = 0; i < this.con1.numChildren; i++) {
                let cell = this.con1.getChildAt(i);
                uids.push(cell.vo.data.serialNum);
            }
            let _l = this.model.cardList;
            let notFind = true;
            for (let i = 0; i < _l.length; i++) {
                let vo = _l[i];
                if (uids.indexOf(vo.data.serialNum) == -1) {
                    let cell = this.createCell(vo, index);
                    cell.rotation = rot;
                    cell.updateSort();
                    cell.alphaShow();
                    notFind = false;
                    break;
                }
            }
            if (notFind) {
                for (let i = 0; i < this.con1.numChildren; i++) {
                    let cell = this.con1.getChildAt(i);
                    cell.rotation = this.startRot + this.rot * i;
                    cell.updateSort();
                }
            }
        }
    }

    class FuncSommonCardCtl {
        get model() {
            return ComposeModel.Ins;
        }
        onInit() {
            this.sommonBtn = ButtonCtl.CreateBtn(this.sommonImg, this, this.onSommonHandler);
            this.betterBtn = ButtonCtl.CreateBtn(this.betterImg, this, this.onGambleHandler);
            this.supplicatiorDecorator = new SupplicatiorDecorator(this.betterImg);
            this.supplicatiorDecorator.onInit();
            this.moneyCtl = FightUIFactory.createCardMoney(this.copperTf, null, ECellType.FIGHT_MONEY);
            this.jadeTfCtl = FightUIFactory.createCardMoney(this.jadeTf, null, ECellType.FIGHT_STONE);
            TowerMainModel.Ins.on(TowerMainEvent.ValChangeCell, this, this.onValChangeCell);
            this.model.on(ComposeEvent.CostUpdate, this, this.onCostUpdate);
            this.model.on(ComposeEvent.UpdateOwnerHeroCount, this, this.onUpdateOwnerHeroCount);
            this.model.on(ComposeEvent.CardUiEffectAdd, this, this.onCardUiEffect);
            GuideModel.Ins.on(EGuideEvent.SommonUnlock, this, this.onSommonStyle);
            this.model.on(ComposeEvent.DelEffectCardUid, this, this.onDelEffectCardUid);
            this.onSommonStyle();
            this.initMoney();
            this.onUpdateOwnerHeroCount();
            this.onCardUiEffect();
        }
        onGambleHandler() {
            Laya.timer.callLater(this, this.onLaterOpenGamble);
        }
        onLaterOpenGamble() {
            this.model.fightTypeAdaper.gambleOpen();
        }
        initMoney() {
            this.moneyCtl.update();
            this.jadeTfCtl.update();
            this.onCostUpdate();
        }
        onCostUpdate() {
            let id = ECellType.FIGHT_MONEY;
            ItemViewFactory.setlb2(this.costLabel, id, this.model.getCost(id));
        }
        onValChangeCell(id) {
            if (id == ECellType.FIGHT_MONEY) {
                this.onCostUpdate();
                this.moneyCtl.play();
            }
            else if (id == ECellType.FIGHT_STONE) {
                this.jadeTfCtl.play();
            }
        }
        onExit() {
            this.supplicatiorDecorator.onExit();
            this.disposeSummonEffectButton();
            GuideModel.Ins.off(EGuideEvent.SommonUnlock, this, this.onSommonStyle);
            TowerMainModel.Ins.off(TowerMainEvent.ValChangeCell, this, this.onValChangeCell);
            this.model.off(ComposeEvent.CardUiEffectAdd, this, this.onCardUiEffect);
            this.model.off(ComposeEvent.CostUpdate, this, this.onCostUpdate);
            this.model.off(ComposeEvent.UpdateOwnerHeroCount, this, this.onUpdateOwnerHeroCount);
            this.model.off(ComposeEvent.DelEffectCardUid, this, this.onDelEffectCardUid);
            if (this.sommonBtn) {
                this.sommonBtn.dispose();
                this.sommonBtn = null;
            }
            if (this.betterBtn) {
                this.betterBtn.dispose();
                this.betterBtn = null;
            }
            if (this.jadeTfCtl) {
                this.jadeTfCtl.dispose();
                this.jadeTfCtl = null;
            }
            if (this.moneyCtl) {
                this.moneyCtl.dispose();
                this.moneyCtl = null;
            }
        }
        onSommonHandler() {
            this.model.curAdapter.fresh();
        }
        onUpdateOwnerHeroCount() {
            if (this.model.ownerPlayer) {
                this.peoTf.text = `${this.model.heroCount}/${this.model.ownerPlayer.maxHero}`;
            }
        }
        onSommonStyle() {
            if (this.model.curAdapter.sommonUnLockedStyle) {
                this.sommonBtn.grayMouseDisable = false;
                this.lockimg.visible = false;
            }
            else {
                this.sommonBtn.grayMouseDisable = true;
                this.lockimg.visible = true;
            }
        }
        onCardUiEffect() {
            this.disposeSummonEffectButton();
            if (this.model.summonEffectVo.status == EEffectStatus.Open) {
                let ox = this.sommonImg.x + this.sommonImg.width / 2;
                let oy = this.sommonImg.y + this.sommonImg.height / 2;
                this.sommonEffect = SpineEffectMgr.createLoopNoSimpleEffect(this.model.summonEffectVo.url, this.sommonImg.parent, ox, oy, undefined, undefined, 0.9);
                this.sommonEffect.data = this.model.summonEffectVo.cardSerialNum;
            }
        }
        disposeSummonEffectButton() {
            if (this.sommonEffect) {
                this.sommonEffect.dispose();
                this.sommonEffect = null;
            }
        }
        onDelEffectCardUid(vo) {
            if (this.sommonEffect && vo.cardSerialNum == this.sommonEffect.data) {
                this.disposeSummonEffectButton();
            }
        }
    }

