    class HeartComponent extends ui.views.compose.fightcell.fight_heartUI {
        constructor() {
            super(...arguments);
            this.defaultMax = 5;
            this.maxHp = this.defaultMax;
        }
        set value(v) {
            for (let i = 0; i < this.defaultMax; i++) {
                let star = this[`s${i}`];
                if (i < this.maxHp) {
                    if (i < v) {
                        star.skin = `remote/fight/img_ax.png`;
                    }
                    else {
                        star.skin = `remote/fight/img_ax1.png`;
                    }
                }
                else {
                    star.skin = "";
                }
            }
        }
        centerLayoutX() {
            let w = this.s0.width;
            let gap = this.s1.x - this.s0.x - w;
            let cw = w * this.maxHp;
            let ox = (this.width - cw) / 2;
            for (let i = 0; i < this.maxHp; i++) {
                let star = this[`s${i}`];
                star.x = ox + i * (w + gap);
            }
        }
        playBroken(i) {
            let star = this[`s${i}`];
            SpineEffectMgr.playOnce(`o/spine/scene/xinxin/xinxin`, star, star.width / 2, star.height / 2);
        }
    }

