    var EGuideMode;
    (function (EGuideMode) {
        EGuideMode[EGuideMode["PveGuide"] = 1] = "PveGuide";
        EGuideMode[EGuideMode["PvpRound"] = 2] = "PvpRound";
    })(EGuideMode || (EGuideMode = {}));
