    class PveGuideData {
        constructor() {
            this.heroPoolConfigStr = "";
            this.composeHeroConfigStr = `7-02-1-5`;
            this.gambleConfigArr1 = [];
            this.gambleConfigArr2 = [];
            this.gambleConfigArr3 = [];
            this.heroMythosConfigStr = "";
        }
        dispose() {
            if (this.fightStopMgr) {
                this.fightStopMgr.dispose();
                this.fightStopMgr = null;
            }
        }
        initGambleArr(s) {
            let a1 = s.split(";");
            for (let i = 0; i < a1.length; i++) {
                if (!StringUtil.IsNullOrEmpty(a1[i])) {
                    let a2 = a1[i].split("|");
                    for (let n = 0; n < a2.length; n++) {
                        if (!StringUtil.IsNullOrEmpty(a2[n])) {
                            this[`gambleConfigArr${(i + 1)}`].push(a2[n]);
                        }
                    }
                }
            }
        }
        clearMoney() {
            let list = ItemViewFactory.convertCellList(`${ECellType.FIGHT_MONEY}-0|${ECellType.FIGHT_STONE}-0`);
            FightGuideUtils.setMoney(list);
        }
        initDebugParam() {
            let _id;
            if (Laya.Utils.getQueryString("pveChapterId")) {
                _id = parseInt(Laya.Utils.getQueryString("pveChapterId"));
            }
            if (initConfig.pveChapterId) {
                _id = initConfig.pveChapterId;
            }
            if (_id) {
                MainModel.Ins.pveChapterId = _id;
            }
        }
        init() {
            this.initDebugParam();
            let chapterId = MainModel.Ins.pveChapterId;
            let chaperCfg = E.tableMgr.getTable(t_GuideChapter.NAME).GetDataById(chapterId);
            if (!chaperCfg) {
                LogSys.Error(`chapterId:${chapterId}配置异常`);
                return;
            }
            this.guideTableName = chaperCfg.f_flow;
            this.taskId = 0;
            this.clearMoney();
            switch (chapterId) {
                case 1:
                    this.heroPoolConfigStr = t_PVE_Guide_Init.Ins.getVal(2);
                    this.composeHeroConfigStr = t_PVE_Guide_Init.Ins.getVal(3);
                    this.initGambleArr(t_PVE_Guide_Init.Ins.getVal(4));
                    break;
                case 2:
                    this.heroPoolConfigStr = t_PVE_Guide_Init.Ins.getVal(6);
                    this.composeHeroConfigStr = t_PVE_Guide_Init.Ins.getVal(7);
                    this.initGambleArr(t_PVE_Guide_Init.Ins.getVal(8));
                    this.heroMythosConfigStr = t_PVE_Guide_Init.Ins.getVal(9);
                    break;
                case 4:
                    break;
                default:
                    LogSys.Log(`使用章节引导id${chaperCfg}`);
                    break;
            }
            if (!StringUtil.IsNullOrEmpty(chaperCfg.f_stop_check)) {
                this.fightStopMgr = new FightStopMgr();
                this.fightStopMgr.init(chaperCfg.f_stop_check);
            }
            this.refresh();
        }
        refresh() {
            let proxy = GuideModel.Ins.getTable(this.guideTableName);
            this.selfId = MainModel.Ins.mRoleData.AccountId;
            this.enemyId = this.selfId + 1;
            this.target.createHeroPool(this.heroPoolConfigStr);
            GuideModel.Ins.proxy = proxy;
            GuideModel.Ins.taskId = this.taskId;
            let cfg = proxy.List[0];
            if (cfg.f_param) {
                let obj = FightGuideUtils.createRoom(cfg.f_param);
                if (obj) {
                    this.initSommon(obj.mode);
                    FightGuideUtils.createRoomInfo(this.selfId, this.enemyId, obj.mode, obj.lv, obj.nickName, obj.trophy, obj.headUrl, obj.ownerMonsterMaxCount, obj.enemyMonsterMaxCount);
                }
                else {
                    LogSys.Error(`${proxy.GetTabelName()} 第一条数据必须为房间信息`);
                }
            }
        }
        initSommon(mode) {
            let cfg = E.tableMgr.getTable(t_FightStyle.NAME).GetDataById(mode);
            let sommonMoneyConfigId = cfg.f_sommon_id;
            let itemArr = t_Battle_Config.Ins.getValueById(sommonMoneyConfigId).split("-");
            let itemonceArr = t_Battle_Config.Ins.getValueById(sommonMoneyConfigId + 1).split("-");
            this.sommonOffsetPrice = parseInt(itemonceArr[1]);
            this.sommonPriceItemId = parseInt(itemArr[0]);
            this.sommonPriceInitVal = parseInt(itemArr[1]);
        }
        check(ms) {
            return this.fightStopMgr && this.fightStopMgr.check(ms);
        }
    }

    class PveGuide extends BaseGuide {
        constructor() {
            super();
            this.enemyHeros = [];
            this.curWaveSec = FightValueConfig.WaveSec;
        }
        clientFresh() {
            let itemId = this.curData.sommonPriceItemId;
            if (MainModel.Ins.mRoleData.getVal(itemId) < this.sommonNeedVal) {
                E.ViewMgr.ShowMidLabel(E.getLang("itemnotenough", ItemProxy.Ins.getCfg(itemId).f_name));
                return;
            }
            FightGuideUtils.clientFresh(this.ownerHerosPool, this, this.updateSommonHeroCost, this.onSucceedHandler);
        }
        onSucceedHandler() {
            this.sommonCount++;
        }
        createSelfHero(str) {
            return FightGuideUtils.createHeroVo(str, this.selfId);
        }
        clearData() {
            if (this.guidePreCheck) {
                this.guidePreCheck.dispose();
                this.guidePreCheck = null;
            }
            this.stop();
            if (this.curData) {
                this.curData.dispose();
                this.curData = null;
            }
            this.clearEvt();
        }
        initData() {
            this.guidePreCheck = new GuidePreCheck(this);
            FightGuideUtils.clearUID();
            this.sommonCount = 0;
            this.curData = new PveGuideData();
            this.curData.target = this;
            this.curData.init();
            this.model.setPveFightAdapter();
            this.model.curAdapter.init();
            this.selfId = this.curData.selfId;
            this.enemyId = this.curData.enemyId;
            this.sommonNeedVal = this.curData.sommonPriceInitVal;
            this.updateSommonHeroCost();
            this.onInit();
        }
        updateSommonHeroCost() {
            let revc = new SommonHeroCost_revc();
            revc.moneyInfo = ItemViewFactory.convertCellList(`${this.curData.sommonPriceItemId}-${this.sommonNeedVal}`);
            this.sommonNeedVal += this.curData.sommonOffsetPrice;
            this.model.onSommonHeroCost(revc);
        }
    }

