    class CmdVo {
        constructor(str, time) {
            this.str = str;
            this.time = time;
        }
    }
    class DebugCmdShow extends IDebugDecorator {
        constructor() {
            super(...arguments);
            this.curCmds = [];
        }
        parseCmd(str) {
            let cmdList = str.split(";");
            for (let i = 0; i < cmdList.length; i++) {
                let s = cmdList[i];
                if (!StringUtil.IsNullOrEmpty(s)) {
                    this.curCmds.push(new CmdVo(s, Laya.timer.currTimer + 100 * i));
                }
            }
        }
        onLoop() {
            this.target.onLoop();
            if (this.curCmds.length) {
                let vo = this.curCmds[0];
                if (vo.time <= Laya.timer.currTimer) {
                    this.curCmds.shift();
                    MainModel.Ins.gm(vo.str);
                }
            }
        }
        init() {
            this.target.init();
            Laya.timer.frameLoop(1, this, this.onLoop);
        }
    }

