    var EScene2DType;
    (function (EScene2DType) {
        EScene2DType[EScene2DType["None"] = 0] = "None";
    })(EScene2DType || (EScene2DType = {}));
    class Scene2DManager {
        constructor() {
            this._hasInit = false;
        }
        Init() {
            if (this._hasInit)
                return false;
            this._hasInit = true;
            this._scenes = new Map();
            this._openScenes = [];
            this.initRegScenes();
            return true;
        }
        initRegScenes() {
        }
        Reg(type, view) {
            if (view == null)
                return;
            if (this._scenes[type])
                return;
            this._scenes[type] = view;
        }
        UnReg(type) {
            if (!this._scenes[type])
                return;
            this._scenes[type] = null;
            delete this._scenes[type];
        }
        Get(type) {
            return this._scenes[type];
        }
        CurOpenNum() {
            return this.CurOpenNum.length;
        }
        Open(type, callback, data) {
            let scene = this.Get(type);
            if (scene == null) {
                LogSys.Warn("场景未注册 type:" + type);
                return;
            }
            E.ResMgr.LoadGroup(scene.ResGroup, Callback.Create(this, () => {
                scene.Enter(data);
                this._openScenes.push(type);
                if (callback != null)
                    callback.Invoke();
            }), Callback.Create(this, (v) => {
            }));
        }
        Close(type) {
            let scene = this.Get(type);
            if (scene == null)
                return;
            ListUtil.Remove(this._openScenes, type);
            scene.Exit();
        }
        HasReg(type) {
            if (this._scenes[type])
                return true;
            return false;
        }
        Clear() {
            this.CloseAll();
            this._scenes = null;
        }
        CloseAll() {
            for (let i = 0; i < this._openScenes.length; i++) {
                this.Close(this._openScenes[i]);
            }
        }
        Destroy(type, newScene = null) {
            let oldScene = this.Get(type);
            if (oldScene) {
                this.UnReg(type);
                oldScene.Exit();
                oldScene = null;
            }
            this.Reg(type, newScene);
        }
    }

    function addVersionPrefix(url) {
        let key = Laya.ResourceVersion.manifest;
        let arr = url.split("?");
        if (arr.length > 1) {
            url = arr[0];
        }
        if (url && key[url]) {
            let u;
            if (arr.length > 1) {
                u = key[url] + "?" + arr[1];
            }
            else {
                u = key[url];
            }
            return "e/" + u + "/" + url;
        }
        return url;
    }
    class LoadMainnfestParse {
        constructor(end) {
            this._end = end;
            let fManifestUrl = `${InitConfig.getAsset()}manifest.json?${Math.random()}`;
            this.mManifestUrl = fManifestUrl;
            LogSys.Log("fManifestUrl:" + fManifestUrl);
            let _defaultRes = new ResItemGroup();
            _defaultRes.Add(fManifestUrl, Laya.Loader.JSON);
            E.ViewMgr.Loading(_defaultRes, new Laya.Handler(this, this.onLoadComplete));
        }
        onLoadComplete() {
            let data = Laya.Loader.getRes(this.mManifestUrl);
            if (!data) {
                E.ViewMgr.Open(EViewType.MsgBoxNormal, null, "网络异常");
                return;
            }
            data["o/config/game.json"] = null;
            data[EResPath.LANG_CN] = null;
            this.data = data;
            Laya.ResourceVersion.manifest = data;
            Laya.URL.customFormat = addVersionPrefix;
            this._end.runWith(this);
        }
    }

