    class XianShiLiBaoItem extends ui.views.xianshilibao.ui_xianshilibaoItemUI {
        constructor() {
            super();
            this.on(Laya.Event.UNDISPLAY, this, this.onUnDisplay);
            this._ctl = new ItemSlotCtl(this.view);
            this._ctl1 = new ItemSlotCtl(this.view1);
            this._timeCtl = new TimeCtl(this.lab_time);
            ButtonCtl.Create(this.btn2, new Laya.Handler(this, this.onBtnClick));
        }
        onUnDisplay() {
            if (this._timeCtl) {
                this._timeCtl.dispose();
                this._timeCtl = null;
            }
        }
        onBtnClick() {
            if (!this._cfg)
                return;
            TowertMainShopModel.Ins.recharge(this._cfg.f_recharge);
        }
        setData(value) {
            if (!value)
                return;
            this._cfg = t_Limited_Time_Pack.Ins.GetDataById(value.id);
            this.img.skin = `remote/xianshilibao/tx_lxxs_${this._cfg.f_pack_title}.png`;
            this.img1.skin = `remote/xianshilibao/tx_lb_${this._cfg.f_headline}.png`;
            this.img2.skin = `remote/xianshilibao/img_lb_${this._cfg.f_pack_icon}.png`;
            let arr = ItemViewFactory.convertItemList(this._cfg.f_reward);
            this._ctl.setData(arr[0]);
            this._ctl1.setData(arr[1]);
            this.lab.text = this._cfg.f_discount / 100 + "%";
            this.lab2.text = StringUtil.moneyCv(this._cfg.f_original_price) + "";
            this.lab3.text = "(" + value.param1 + "/" + this._cfg.f_limited_times + ")";
            let rCfg = t_Recharge.Ins.getCfgById(this._cfg.f_recharge);
            this.lab1.text = StringUtil.moneyCv(rCfg.f_price) + "元";
            let endtime = 0;
            let data = XianShiLiBaoModel.Ins.limitPackTimeList.find(ele => ele.id == this._cfg.f_id);
            if (data) {
                endtime = data.endtime;
            }
            let time = endtime - TimeUtil.serverTime;
            if (time > 0) {
                this._timeCtl.start(time, new Laya.Handler(this, this.onUpdateTime), new Laya.Handler(this, this.endTime));
            }
            else {
                this._timeCtl.stop();
            }
        }
        onUpdateTime() {
            let time_str = TimeUtil.subTime(this._timeCtl.tickVal);
            this._timeCtl.setText(time_str);
        }
        endTime() {
            this._timeCtl.setText("00:00:00");
        }
    }

    class XianShiLiBaoView extends ViewBase {
        constructor() {
            super(...arguments);
            this.mMask = true;
            this.mMainSnapshot = true;
            this.autoFree = true;
        }
        onAddLoadRes() {
            this.addAtlas('xianshilibao.atlas');
        }
        onFirstInit() {
            if (!this.UI) {
                this.UI = this._ui = new ui.views.xianshilibao.ui_xianshilibaoViewUI();
                this.bindClose(this._ui.btn_close);
                this._ui.list.itemRender = XianShiLiBaoItem;
                this._ui.list.renderHandler = new Laya.Handler(this, this.onRenderHandler);
            }
        }
        onRenderHandler(item) {
            item.setData(item.dataSource);
        }
        onInit() {
            ActivityModel.Ins.on(ActivityModel.UPDATE_DATA, this, this.onUpdateView);
            XianShiLiBaoModel.Ins.on(XianShiLiBaoModel.UPDATE_DATA, this, this.onUpdateView);
            this.updateView();
        }
        onExit() {
            ActivityModel.Ins.off(ActivityModel.UPDATE_DATA, this, this.onUpdateView);
            XianShiLiBaoModel.Ins.off(XianShiLiBaoModel.UPDATE_DATA, this, this.onUpdateView);
        }
        onUpdateView() {
            Laya.timer.callLater(this, this.updateView);
        }
        updateView() {
            let data = ActivityModel.Ins.getActivityData(EActivityID.XianShiLiBao);
            if (!data)
                return;
            let arr = [];
            for (let i = 0; i < data.datalist.length; i++) {
                let cfg = t_Limited_Time_Pack.Ins.GetDataById(data.datalist[i].id);
                if (cfg.f_hide) {
                    continue;
                }
                if (data.datalist[i].param1 < cfg.f_limited_times) {
                    arr.push(data.datalist[i]);
                }
            }
            arr.sort(this.onSort);
            this._ui.list.array = arr;
            if (arr.length == 0) {
                this.Close();
            }
        }
        onSort(a, b) {
            let aa = t_Limited_Time_Pack.Ins.GetDataById(a.id);
            let bb = t_Limited_Time_Pack.Ins.GetDataById(b.id);
            return bb.f_pack_sort - aa.f_pack_sort;
        }
    }

