    class ZhanLinModel extends Laya.EventDispatcher {
        constructor() {
            super();
        }
        static get Ins() {
            if (!this._ins) {
                this._ins = new ZhanLinModel();
            }
            return this._ins;
        }
        setRedTip() {
            if (this.isRedTip1() || this.isRedTip2()) {
                FunctionModel.Ins.funcSetRed(EFuncDef.ZhanLin, true);
            }
            else {
                FunctionModel.Ins.funcSetRed(EFuncDef.ZhanLin, false);
            }
        }
        isRedTip1() {
            let data = ActivityModel.Ins.getActivityData(EActivityID.ZhanLin);
            if (data) {
                for (let i = 0; i < data.datalist.length; i++) {
                    let status = data.datalist[i].param1;
                    if (status == 1 || status == 11 || status == 13) {
                        return true;
                    }
                }
            }
            return false;
        }
        isRedTip2(type = 0) {
            if (!this.taskList)
                return false;
            for (let i = 0; i < this.taskList.length; i++) {
                let cfg = t_Battle_Pass_Task.Ins.getCfgById(this.taskList[i].id);
                if (type == 0 || cfg.f_task_type == type) {
                    let status = this.taskList[i].status;
                    if (status == 1) {
                        return true;
                    }
                }
            }
            return false;
        }
        isChongZhi() {
            let data = ActivityModel.Ins.getActivityData(EActivityID.ZhanLin);
            if (data) {
                for (let i = 0; i < data.datalist.length; i++) {
                    let status = data.datalist[i].param1;
                    if (status == 11 || status == 12 || status == 13) {
                        return true;
                    }
                }
            }
            return false;
        }
    }
    ZhanLinModel.UPDATE_DATA = "UPDATE_DATA";

    class t_Battle_Pass extends BaseCfg {
        constructor() {
            super();
            this._map = {};
            for (let i = 0; i < this.List.length; i++) {
                let season = this.List[i].f_season;
                if (!this._map[season]) {
                    this._map[season] = [];
                }
                this._map[season].push(this.List[i]);
            }
        }
        static get Ins() {
            if (!this._ins) {
                this._ins = new t_Battle_Pass();
            }
            return this._ins;
        }
        GetTabelName() {
            return "t_Battle_Pass";
        }
        getCfgById(id) {
            return this.List.find(item => item.f_id == id);
        }
        getCfgBySeason(season, lv) {
            let arr = this._map[season];
            return arr.find(item => item.f_level == lv);
        }
        getListBySeason(season) {
            return this._map[season];
        }
        getMaxBySeason(season) {
            let arr = this._map[season];
            return arr[arr.length - 1].f_level;
        }
    }

