    class ChengHaoItem extends ui.views.chenghao.ui_chenghaoItemUI {
        constructor() {
            super();
            this._ctl = new ChengHaoCtl(this.view);
            this._timeCtl = new TimeCtl(this.lab);
            this.on(Laya.Event.CLICK, this, this.onClick);
            this.on(Laya.Event.DISPLAY, this, this.onDisplay);
            this.on(Laya.Event.UNDISPLAY, this, this.onUnDisplay);
        }
        onDisplay() {
        }
        onUnDisplay() {
            if (this._timeCtl) {
                this._timeCtl.dispose();
                this._timeCtl = null;
            }
        }
        onClick() {
            if (!this._data)
                return;
            let data = ChengHaoModel.Ins.getDataById(this._data.f_title_id);
            if (data && data.isNew) {
                let req = new TitleNewClick_req;
                req.titleId = data.id;
                SocketMgr.Ins.SendMessageBin(req);
            }
        }
        setData(value) {
            if (!value)
                return;
            this._data = value;
            this._ctl.setData(value.f_title_id, false);
            if (value.f_title_id == ChengHaoModel.Ins.titleId) {
                this.img.visible = true;
            }
            else {
                this.img.visible = false;
            }
            this.lab.text = "";
            this.sp.visible = false;
            let data = ChengHaoModel.Ins.getDataById(value.f_title_id);
            if (data) {
                this.sp_m.visible = false;
                let time = data.exp - TimeUtil.serverTime;
                if (time > 0) {
                    this._timeCtl.start(time, new Laya.Handler(this, this.onUpdateTime), new Laya.Handler(this, this.endTime));
                }
                else {
                    this._timeCtl.stop();
                }
                if (data.isNew) {
                    this.sp.visible = true;
                }
            }
            else {
                this._timeCtl.stop();
                this.sp_m.visible = true;
            }
        }
        onUpdateTime() {
            let time_str = TimeUtil.subTime(this._timeCtl.tickVal);
            this._timeCtl.setText(time_str);
        }
        endTime() {
            this._timeCtl.setText("");
        }
    }

    class ChengHaoView extends ViewBase {
        constructor() {
            super(...arguments);
            this.mMask = true;
            this.mMainSnapshot = true;
            this.autoFree = true;
        }
        onAddLoadRes() {
            this.addAtlas("chenghao.atlas");
        }
        onFirstInit() {
            if (!this.UI) {
                this.UI = this._ui = new ui.views.chenghao.ui_chenghaoViewUI;
                this.bindClose(this._ui.btn_close);
                this.btnList.push(ButtonCtl.Create(this._ui.btn_js, new Laya.Handler(this, this.onBtnClick)));
                this._ui.list.itemRender = ChengHaoItem;
                this._ui.list.renderHandler = new Laya.Handler(this, this.onRenderHandler);
                this._ui.list.selectEnable = true;
                this._ctl = new ChengHaoCtl(this._ui.view);
            }
        }
        onBtnClick() {
            let req = new TitleSwitch_req;
            req.titleId = this._ui.list.selectedItem.f_title_id;
            SocketMgr.Ins.SendMessageBin(req);
        }
        onRenderHandler(item, index) {
            item.setData(item.dataSource);
            if (index == this._ui.list.selectedIndex) {
                item.sel.visible = true;
                this.updateView1();
            }
            else {
                item.sel.visible = false;
            }
        }
        onInit() {
            ChengHaoModel.Ins.on(ChengHaoModel.UPDATE_DATA, this, this.onUpdateView);
            ChengHaoModel.Ins.on(ChengHaoModel.UPDATE_TITLE, this, this.onUpdateView);
            this.updateView();
        }
        onExit() {
            ChengHaoModel.Ins.off(ChengHaoModel.UPDATE_DATA, this, this.onUpdateView);
            ChengHaoModel.Ins.off(ChengHaoModel.UPDATE_TITLE, this, this.onUpdateView);
        }
        onUpdateView() {
            this.updateView1();
            this._ui.list.refresh();
        }
        updateView1() {
            let cfg = this._ui.list.selectedItem;
            this._ctl.setData(cfg.f_title_id);
            this._ui.lab.text = cfg.f_access;
            if (cfg.f_title_id == ChengHaoModel.Ins.titleId) {
                this._ui.img1.visible = true;
                this._ui.btn_js.visible = false;
            }
            else {
                this._ui.img1.visible = false;
                this._ui.btn_js.visible = true;
                let data = ChengHaoModel.Ins.getDataById(cfg.f_title_id);
                if (data) {
                    this._ui.btn_js.disabled = false;
                    this._ui.lab1.text = "穿戴";
                }
                else {
                    this._ui.btn_js.disabled = true;
                    this._ui.lab1.text = "未拥有";
                }
            }
        }
        updateView() {
            let arr = t_Title.Ins.List;
            let arr1 = [];
            let arr2 = [];
            let arr3 = [];
            for (let i = 0; i < arr.length; i++) {
                if (arr[i].f_title_id == ChengHaoModel.Ins.titleId) {
                    arr1.push(arr[i]);
                }
                else {
                    let data = ChengHaoModel.Ins.getDataById(arr[i].f_title_id);
                    if (data) {
                        arr2.push(arr[i]);
                    }
                    else {
                        arr3.push(arr[i]);
                    }
                }
            }
            arr2.sort(this.onSort);
            arr3.sort(this.onSort);
            this._ui.list.array = arr1.concat(arr2).concat(arr3);
            this._ui.list.selectedIndex = 0;
        }
        onSort(a, b) {
            return a.f_sort - b.f_sort;
        }
    }

    class ChengHaoModule extends BaseModel {
        static get Ins() {
            if (!this._ins) {
                this._ins = new ChengHaoModule();
            }
            return this._ins;
        }
        onInitCallBack() { }
        initMsg() {
            this.Reg(new ChengHaoView(EViewType.ChengHaoView));
            E.MsgMgr.AddMsg(SERVER_MSGID.TitleInit, this.TitleInit, this);
            E.MsgMgr.AddMsg(SERVER_MSGID.TitleSwitch, this.TitleSwitch, this);
            E.MsgMgr.AddMsg(SERVER_MSGID.TitleAction, this.TitleAction, this);
        }
        TitleInit(value) {
            ChengHaoModel.Ins.titleId = value.titleId;
            ChengHaoModel.Ins.titleList = value.datalist;
        }
        TitleSwitch(value) {
            ChengHaoModel.Ins.titleId = value.titleId;
            ChengHaoModel.Ins.event(ChengHaoModel.UPDATE_TITLE);
        }
        TitleAction(value) {
            for (let i = 0; i < value.datalist.length; i++) {
                let index;
                if (value.action == 0) {
                    index = ChengHaoModel.Ins.titleList.findIndex(ele => ele.id === value.datalist[i].id);
                    if (index != -1) {
                        ChengHaoModel.Ins.titleList.splice(index, 1);
                    }
                }
                else if (value.action == 1) {
                    ChengHaoModel.Ins.titleList.push(value.datalist[i]);
                }
                else if (value.action == 2) {
                    index = ChengHaoModel.Ins.titleList.findIndex(ele => ele.id === value.datalist[i].id);
                    if (index != -1) {
                        ChengHaoModel.Ins.titleList[index] = value.datalist[i];
                    }
                }
            }
            ChengHaoModel.Ins.event(ChengHaoModel.UPDATE_DATA);
        }
    }

    class DayTaskModel extends Laya.EventDispatcher {
        constructor() {
            super();
            this.activationRewards = [];
            this.dailyTasks = [];
            this.achieveTasks = [];
        }
        static get Ins() {
            if (!this._ins) {
                this._ins = new DayTaskModel();
            }
            return this._ins;
        }
        isRedTip() {
            if (this.isTabRedTip1() || this.isTabRedTip2()) {
                return true;
            }
            return false;
        }
        isTabRedTip1() {
            for (let i = 0; i < this.activationRewards.length; i++) {
                if (this.activationRewards[i].status == 1) {
                    return true;
                }
            }
            for (let i = 0; i < this.dailyTasks.length; i++) {
                if (this.dailyTasks[i].status == 1) {
                    return true;
                }
            }
            return false;
        }
        isTabRedTip2() {
            for (let i = 0; i < this.achieveTasks.length; i++) {
                if (this.achieveTasks[i].status == 1) {
                    return true;
                }
            }
            return false;
        }
        sendCmd(flag, id) {
            let req = new TaskOutReward_req;
            req.flag = flag;
            req.id = id;
            SocketMgr.Ins.SendMessageBin(req);
        }
    }
