    class DayTaskView extends ViewBase {
        constructor() {
            super(...arguments);
            this.mMask = true;
            this.mMainSnapshot = true;
            this.autoFree = true;
        }
        onAddLoadRes() {
            this.addAtlas("daytask.atlas");
        }
        onFirstInit() {
            if (!this.UI) {
                this.UI = this._ui = new ui.views.task.ui_taskViewUI;
                this.bindClose(this._ui.btn_close);
                const tabsSkin = [this._ui.tab1, this._ui.tab2];
                this.tabList = ["任务", "成就"];
                this.tabsCtl = new TabControl();
                this.tabsCtl.init(tabsSkin, new Laya.Handler(this, this.onTabSelectHandler), new Laya.Handler(this, this.itemTabHandler));
                this._ui.list.itemRender = DayTaskItem;
                this._ui.list.renderHandler = new Laya.Handler(this, this.onRenderHandler);
                this._ui.list1.itemRender = DayTaskItem1;
                this._ui.list1.renderHandler = new Laya.Handler(this, this.onRenderHandler1);
                this._ui.list2.itemRender = DayTaskItem2;
                this._ui.list2.renderHandler = new Laya.Handler(this, this.onRenderHandler2);
                this._wid = this._ui.pro.width;
            }
        }
        onRenderHandler(item) {
            item.setData(item.dataSource);
        }
        onRenderHandler1(item) {
            item.setData(item.dataSource);
        }
        onRenderHandler2(item) {
            item.setData(item.dataSource);
        }
        onTabSelectHandler(v) {
            if (v == -1)
                return;
            switch (v) {
                case 0:
                    this._ui.sp1.visible = true;
                    this._ui.sp2.visible = false;
                    this._ui.lab.text = "每日任务";
                    break;
                case 1:
                    this._ui.sp1.visible = false;
                    this._ui.sp2.visible = true;
                    this._ui.lab.text = "成就";
                    break;
            }
        }
        itemTabHandler(tabSkin, index, sel, data) {
            let skin = tabSkin;
            skin.lab.text = this.tabList[index];
            if (sel) {
                skin.img.skin = "remote/daytask/bt_s.png";
                skin.lab.color = "#ffffff";
                skin.lab.strokeColor = "#bb5c00";
            }
            else {
                skin.img.skin = "remote/daytask/bt_n.png";
                skin.lab.color = "#fdf3eb";
                skin.lab.strokeColor = "#91724e";
            }
        }
        onInit() {
            DayTaskModel.Ins.on(DayTaskModel.UPDATE_TASK, this, this.updateView);
            this.updateView();
            this.tabsCtl.selectIndex = 0;
            this.disposeHero();
            this._anim1 = FightFactory.createBigHeroAvatar(5, this._ui.sp, 0, 10);
        }
        onExit() {
            DayTaskModel.Ins.off(DayTaskModel.UPDATE_TASK, this, this.updateView);
            this.tabsCtl.selectIndex = -1;
            this.disposeHero();
        }
        updateView() {
            this._ui.list.array = DayTaskModel.Ins.activationRewards;
            this._ui.list1.array = TowerMainModel.Ins.sortList(DayTaskModel.Ins.dailyTasks);
            this._ui.list2.array = TowerMainModel.Ins.sortList(DayTaskModel.Ins.achieveTasks);
            this._ui.icon.skin = IconUtils.getIconByCfgId(ECellType.HYD);
            this._ui.lab1.text = DayTaskModel.Ins.activation + "";
            let need = t_Daily_Task_Reward.Ins.List[t_Daily_Task_Reward.Ins.List.length - 1].f_activation;
            if (DayTaskModel.Ins.activation >= need) {
                this._ui.pro.width = this._wid;
            }
            else {
                this._ui.pro.width = DayTaskModel.Ins.activation / need * this._wid;
            }
            this._ui.pro1.x = this._ui.pro.width - 25;
            if (DayTaskModel.Ins.isTabRedTip1()) {
                this._ui.sp11.visible = true;
            }
            else {
                this._ui.sp11.visible = false;
            }
            if (DayTaskModel.Ins.isTabRedTip2()) {
                this._ui.sp22.visible = true;
            }
            else {
                this._ui.sp22.visible = false;
            }
        }
        disposeHero() {
            if (this._anim1) {
                this._anim1.dispose();
                this._anim1 = null;
            }
        }
    }

    class DayTaskModule extends BaseModel {
        static get Ins() {
            if (!this._ins) {
                this._ins = new DayTaskModule();
            }
            return this._ins;
        }
        onInitCallBack() { }
        initMsg() {
            this.Reg(new DayTaskView(EViewType.DayTaskView));
            TowerMainModel.Ins.on(TowerMainEvent.MainViewInit, this, this.onMainViewInit);
            E.MsgMgr.AddMsg(SERVER_MSGID.TaskOutInit, this.TaskOutInit, this);
            E.MsgMgr.AddMsg(SERVER_MSGID.TaskOutActivation, this.TaskOutActivation, this);
            E.MsgMgr.AddMsg(SERVER_MSGID.TaskOutChange, this.TaskOutChange, this);
            E.MsgMgr.AddMsg(SERVER_MSGID.TaskOutActivationReward, this.TaskOutActivationReward, this);
        }
        onMainViewInit() {
            Laya.timer.callLater(this, this.setDot);
        }
        setDot() {
            if (DayTaskModel.Ins.isRedTip()) {
                FunctionModel.Ins.funcSetRed(EFuncDef.DayTask, true);
            }
            else {
                FunctionModel.Ins.funcSetRed(EFuncDef.DayTask, false);
            }
        }
        TaskOutInit(value) {
            DayTaskModel.Ins.activation = value.activation;
            DayTaskModel.Ins.achieveTasks = value.achieveTasks;
            DayTaskModel.Ins.activationRewards = value.activationRewards;
            DayTaskModel.Ins.dailyTasks = value.dailyTasks;
        }
        TaskOutActivation(value) {
            DayTaskModel.Ins.activation = value.activation;
            DayTaskModel.Ins.event(DayTaskModel.UPDATE_TASK);
        }
        TaskOutChange(value) {
            if (value.flag == 0) {
                for (let i = 0; i < value.tasks.length; i++) {
                    let index = DayTaskModel.Ins.dailyTasks.findIndex(ele => ele.id === value.tasks[i].id);
                    if (index != -1) {
                        DayTaskModel.Ins.dailyTasks[index] = value.tasks[i];
                    }
                }
            }
            else {
                for (let i = 0; i < value.tasks.length; i++) {
                    let type = t_Achieve_Task.Ins.GetDataById(value.tasks[i].id).f_task_type;
                    let index = DayTaskModel.Ins.achieveTasks.findIndex(ele => t_Achieve_Task.Ins.GetDataById(ele.id).f_task_type === type);
                    if (index != -1) {
                        DayTaskModel.Ins.achieveTasks[index] = value.tasks[i];
                    }
                }
            }
            DayTaskModel.Ins.event(DayTaskModel.UPDATE_TASK);
            this.onMainViewInit();
        }
        TaskOutActivationReward(value) {
            for (let i = 0; i < value.rewards.length; i++) {
                let index = DayTaskModel.Ins.activationRewards.findIndex(ele => ele.id === value.rewards[i].id);
                if (index != -1) {
                    DayTaskModel.Ins.activationRewards[index] = value.rewards[i];
                }
            }
            DayTaskModel.Ins.event(DayTaskModel.UPDATE_TASK);
            this.onMainViewInit();
        }
    }

