    class NewYearModel extends Laya.EventDispatcher {
        constructor() {
            super();
            this.signInList = [];
            this.timeList = [];
            this.dailyRechargeList = [];
            this.dailyRechargeSumList = [];
            this.shoplist = [];
        }
        static get Ins() {
            if (!this._ins) {
                this._ins = new NewYearModel();
            }
            return this._ins;
        }
        isRedTip() {
            if (this.isRedTab1() || this.isRedTab3() || this.isRedTab4()) {
                return true;
            }
            return false;
        }
        isRedTab1() {
            if (!this.isOpen())
                return false;
            let num = this.getNumById(1);
            if (num > 0) {
                return true;
            }
            return false;
        }
        isRedTab3() {
            if (!this.isOpen())
                return false;
            if (this.isSign()) {
                return true;
            }
            return false;
        }
        isRedTab4() {
            if (!this.isOpen())
                return false;
            for (let i = 0; i < this.dailyRechargeList.length; i++) {
                if (this.dailyRechargeList[i].status == 1) {
                    return true;
                }
            }
            for (let i = 0; i < this.dailyRechargeSumList.length; i++) {
                if (this.dailyRechargeSumList[i].status == 1) {
                    return true;
                }
            }
            return false;
        }
        isOpen(flag = false) {
            if (!this.rankTime) {
                if (flag)
                    E.ViewMgr.ShowMidError("活动已结束");
                return false;
            }
            if (TimeUtil.serverTime > this.rankTime.end) {
                if (flag)
                    E.ViewMgr.ShowMidError("活动已结束");
                return false;
            }
            return true;
        }
        getNumById(id) {
            if (this.timeList.length == 0) {
                return 0;
            }
            return this.timeList.find(ele => ele.category == id).times;
        }
        isSign() {
            for (let i = 0; i < this.signInList.length; i++) {
                if (this.signInList[i].state == 3) {
                    return true;
                }
            }
            return false;
        }
    }
