                this._ui.btn2.on(Laya.Event.MOUSE_DOWN, this, this.onBtn2Click);
                this._ui.money1.on(Laya.Event.CLICK, this, this.onMoneyClick);
                this.btnList.push(ButtonCtl.Create(this._ui.btn_close, new Laya.Handler(this, this.onCloseClick)), ButtonCtl.Create(this._ui.btn, new Laya.Handler(this, this.onBtnClick)), ButtonCtl.Create(this._ui.btn1, new Laya.Handler(this, this.onBtn1Click)), ButtonCtl.Create(this._ui.btn3, new Laya.Handler(this, this.onBtn3Click)), ButtonCtl.Create(this._ui.btn4, new Laya.Handler(this, this.onBtn4Click)), ButtonCtl.Create(this._ui.btn5, new Laya.Handler(this, this.onBtn5Click)));
                this._ui.list.itemRender = ShengShouItem;
                this._ui.list.renderHandler = new Laya.Handler(this, this.onRenderHandler);
