    class SheZhiModel extends Laya.EventDispatcher {
        constructor() {
            super();
            this.localNoticeList = [];
            this.noticeSel = new NoticePopTipSelVo();
            this.gameClubData = { join: 0, like: 0, publish: 0 };
        }
        static get Ins() {
            if (!this._ins) {
                this._ins = new SheZhiModel();
            }
            return this._ins;
        }
        isYQRedTip() {
            if (this.isYQRedTipTab2()) {
                return true;
            }
            return false;
        }
        isYQRedTipTab2() {
            return false;
        }
        isSQRedTip() {
            if (this.isSQRedTipTab1()) {
                return true;
            }
            return false;
        }
        isSQRedTipTab1() {
            if (!this.gameClubList)
                return false;
            for (let i = 0; i < this.gameClubList.length; i++) {
                if (this.gameClubList[i].times == 1) {
                    return true;
                }
            }
            return false;
        }
        getGameClubData() {
            E.sdk.getGameClubData((res) => {
                var _a;
                if (res) {
                    const d = JSON.parse(res);
                    const dataList = (_a = d === null || d === void 0 ? void 0 : d.data) === null || _a === void 0 ? void 0 : _a.dataList;
                    if (dataList && dataList.length) {
                        const m = new Map([
                            [1, 'join'], [4, 'like'], [5, 'publish'],
                        ]);
                        dataList.forEach((element, i) => {
                            const key = m.get(element.dataType.type);
                            this.gameClubData[key] = element.value;
                        });
                        this.event(SheZhiModel.GameClubUpdate);
                    }
                }
                else {
                    this.event(SheZhiModel.GameClubUpdate);
                }
            });
        }
        getGameCount(type) {
            let count = 0;
            if (type == 1) {
                if (SheZhiModel.Ins.gameClubData.join) {
                    count = 1;
                }
            }
            else if (type == 4) {
                count = SheZhiModel.Ins.gameClubData.like;
            }
            else if (type == 5) {
                count = SheZhiModel.Ins.gameClubData.publish;
            }
            return count;
        }
        openPopNotice(cellList) {
            if (cellList.length <= 0) {
                E.ViewMgr.ShowMidError("没有公告数据");
                return;
            }
            let result = new PopNoticeVo();
            result.dataList = cellList;
            result.noticeSel = this.noticeSel;
            E.ViewMgr.Open(EViewType.NoticePop, null, result);
        }
        openServerNotice(title, content) {
            let result = new PopNoticeVo();
            let cell = new stNotice();
            cell.content = content;
            cell.title = title;
            result.dataList = [];
            result.dataList.push(cell);
            E.ViewMgr.Open(EViewType.NoticePop, null, result);
        }
    }
