    class t_Invite_Reward extends BaseCfg {
        constructor() {
            super();
            this._map = {};
            for (let i = 0; i < this.List.length; i++) {
                let type = this.List[i].f_invite_type;
                if (!this._map[type]) {
                    this._map[type] = [];
                }
                this._map[type].push(this.List[i]);
            }
        }
        static get Ins() {
            if (!this._ins) {
                this._ins = new t_Invite_Reward();
            }
            return this._ins;
        }
        GetTabelName() {
            return "t_Invite_Reward";
        }
        getListByType(type) {
            let arr = this._map[type];
            let array = [];
            for (let i = 0; i < arr.length; i++) {
                if (arr[i].f_plat_type == initConfig.platform) {
                    array.push(arr[i]);
                }
            }
            return array;
        }
    }

    class YaoQingItem1 extends ui.views.shezhi.ui_yaoqingItem1UI {
        constructor() {
            super();
            this.on(Laya.Event.CLICK, this, this.onClick);
        }
        onClick() {
            if (!this._data)
                return;
            if (this._data.times == 1) {
                let req = new InviteReward_req;
                req.id = this._data.flag;
                SocketMgr.Ins.SendMessageBin(req);
            }
            else {
                let cfg = t_Invite_Reward.Ins.GetDataById(this._data.flag);
                FunctionModel.Ins.showRewardTip(cfg.f_reward, this);
            }
        }
        setData(value) {
            if (!value)
                return;
            this.lab.text = value.f_invite_number + "";
            this._data = SheZhiModel.Ins.yqList.find(ele => ele.flag === value.f_id);
            DotManager.removeDot(this.img);
            if (this._data.times == 0) {
                this.img.skin = "remote/shezhi/ico_bx.png";
            }
            else if (this._data.times == 1) {
                this.img.skin = "remote/shezhi/ico_bx.png";
                DotManager.addDot(this.img);
            }
            else {
                this.img.skin = "remote/shezhi/ico_bx1.png";
            }
        }
    }

    class YaoQingItem2 extends ui.views.shezhi.ui_yaoqingItem2UI {
        constructor() {
            super();
            this._ctl = new ItemSlotCtl(this.view);
            this._wid = this.pro.width;
            ButtonCtl.Create(this.btn, new Laya.Handler(this, this.onBtnClick));
        }
        onBtnClick() {
            if (!this._data)
                return;
            let req = new InviteReward_req;
            req.id = this._data.flag;
            SocketMgr.Ins.SendMessageBin(req);
        }
        setData(value) {
            if (!value)
                return;
            this._ctl.setData(ItemViewFactory.convertItem(value.f_reward));
            this.lab.text = E.getLang("yaoqing1", value.f_invite_number);
            let need = value.f_invite_number;
            if (SheZhiModel.Ins.yqInvitedCnt >= need) {
                this.pro.width = this._wid;
            }
            else {
                this.pro.width = SheZhiModel.Ins.yqInvitedCnt / need * this._wid;
            }
            this.lab1.text = SheZhiModel.Ins.yqInvitedCnt + "/" + need;
            this._data = SheZhiModel.Ins.yqList.find(ele => ele.flag === value.f_id);
            DotManager.removeDot(this.btn);
            this.sp.visible = this.sp1.visible = this.btn.visible = false;
            if (this._data.times == 0) {
                this.sp1.visible = true;
            }
            else if (this._data.times == 1) {
                this.btn.visible = true;
                DotManager.addDot(this.btn);
            }
            else {
                this.sp.visible = true;
            }
        }
    }

