    class CardCQView1 extends ViewBase {
        constructor() {
            super(...arguments);
            this.mMask = true;
            this.mMaskClick = false;
            this.mMainSnapshot = true;
            this.autoFree = true;
        }
        onAddLoadRes() {
            this.addAtlas("cardcq.atlas");
        }
        onFirstInit() {
            if (!this.UI) {
                this.UI = this._ui = new ui.views.cardcq.ui_cardCQView2UI();
                this.bindClose(this._ui.btn_close);
                this._panelCtl = new ScrollPanelControl();
                this._panelCtl.init(this._ui.panel);
            }
        }
        onInit() {
            let arr = this.getList();
            this._panelCtl.clear();
            for (let i = 0; i < arr.length; i++) {
                if (arr[i].type == 1) {
                    this._panelCtl.split([arr[i].data], CardCQViewNode, 39);
                }
                else if (arr[i].type == 2) {
                    this._panelCtl.split([arr[i].data], CardCQViewNode1, 24);
                }
                else if (arr[i].type == 3) {
                    this._panelCtl.split(arr[i].data, CardCQViewNode2, 266, 15, 4);
                }
            }
            this._panelCtl.end();
            this._ui.img.skin = `remote/cardcq/${TowertMainCardModel.Ins.selectKBId}.png`;
        }
        onExit() {
        }
        getList() {
            let array = [];
            let arr = t_Function_Card_Extract_Rate.Ins.getListById(TowertMainCardModel.Ins.selectKBId);
            for (let i = arr.length - 1; i >= 0; i--) {
                let vo = {};
                vo.type = 1;
                vo.data = arr[i].f_qua;
                array.push(vo);
                let voo = {};
                voo.type = 2;
                voo.data = arr[i].f_qua + "-" + arr[i].f_drop_probability;
                array.push(voo);
                let vooo = {};
                vooo.type = 3;
                vooo.data = arr[i].f_reward.split("|");
                array.push(vooo);
            }
            return array;
        }
    }

    class CardCQView2 extends ViewBase {
        constructor() {
            super(...arguments);
            this.PageType = EPageType.None;
            this.mMask = true;
            this.mMaskClick = false;
            this.mMainSnapshot = true;
            this.autoFree = true;
        }
        onAddLoadRes() {
            this.addAtlas("cardcq.atlas");
        }
        onFirstInit() {
            if (!this.UI) {
                this.UI = this._ui = new ui.views.cardcq.ui_cardCQView1UI();
                this.bindClose(this._ui.btn_close);
                this.btnList.push(ButtonCtl.Create(this._ui.btn, new Laya.Handler(this, this.onBtnClick)));
                for (let i = 1; i < 6; i++) {
                    this._ui["sp" + i].on(Laya.Event.CLICK, this, this.onClick, [i]);
                    this._ui["s" + i].on(Laya.Event.CLICK, this, this.onSClick, [i]);
                }
                this._ui.on(Laya.Event.CLICK, this, this.onUIClick);
                this.ckCtl1 = new CheckBoxCtl({ bg: this._ui.bg, gou: this._ui.gou });
                this.ckCtl1.selectHander = new Laya.Handler(this, this.onSelectHander1);
                this.ckCtl2 = new CheckBoxCtl({ bg: this._ui.bg1, gou: this._ui.gou1 });
                this.ckCtl2.selectHander = new Laya.Handler(this, this.onSelectHander2);
            }
        }
        onSelectHander1() {
            TowertMainCardModel.Ins.cqAuto = this.ckCtl1.selected;
            TowertMainCardModel.Ins.event(TowertMainCardModel.UPDATE_AUTO);
        }
        onSelectHander2() {
            TowertMainCardModel.Ins.cqTG = this.ckCtl2.selected;
            TowertMainCardModel.Ins.event(TowertMainCardModel.UPDATE_AUTO);
        }
        onUIClick() {
            if (TowertMainCardModel.Ins.cqAuto && !this._isAutoClick) {
                this._isAutoClick = true;
            }
        }
        onSClick(i) {
            let data = this._list[i - 1];
            let cfg = t_Function_Card.Ins.getCfgById(data.id);
            E.ViewMgr.Open(EViewType.TowertMainCardTip1, null, cfg);
        }
        onBtnClick() {
            let cfg = t_Function_Card_Match.Ins.getCfgById(TowertMainCardModel.Ins.cqKBId);
            if (TowerMainModel.Ins.isItemEnoughSt(cfg.f_consume_item, true)) {
                TowertMainCardModel.Ins.sendCQCmd(TowertMainCardModel.Ins.cqKBId);
            }
        }
        onClick(i) {
            this._ui["sp" + i].visible = false;
            this.playFCard(i);
            E.AudioMgr.StopSound();
            E.AudioMgr.PlaySound1("1004.mp3");
        }
        playFCard(i) {
            let data = this._list[i - 1];
            let cfg = t_Function_Card.Ins.getCfgById(data.id);
            this["_card" + i].play(cfg.f_qua, this, this.onPlayCardEnd, [this["_card" + i], cfg, i], true);
        }
        playAutoFCard() {
            for (let i = 0; i < 5; i++) {
                Laya.timer.once(i * 200, this, () => {
                    this.playFCard(i + 1);
                }, null, false);
            }
        }
        onPlayCardEnd(card, cfg, i) {
            card.play(cfg.f_qua + 4);
            this._ui["s" + i].visible = true;
            this._num++;
            if (this._num == 5) {
                this._ui.lab_auto1.visible = false;
                TowertMainCardModel.Ins.event(TowertMainCardModel.CQYD2);
                if (this._isAutoClick) {
                    TowertMainCardModel.Ins.cqAuto = false;
                    this.ckCtl1.selected = TowertMainCardModel.Ins.cqAuto;
                    TowertMainCardModel.Ins.event(TowertMainCardModel.UPDATE_AUTO);
                }
                if (TowertMainCardModel.Ins.cqAuto) {
                    let cfg = t_Function_Card_Match.Ins.getCfgById(TowertMainCardModel.Ins.cqKBId);
                    if (TowerMainModel.Ins.isItemEnoughSt(cfg.f_consume_item, true)) {
                        TowertMainCardModel.Ins.sendCQCmd(TowertMainCardModel.Ins.cqKBId);
                    }
                    else {
                        this._ui.btn_close.visible = true;
                        let vo = TowertMainCardModel.Ins.cardGuaranteList.find(ele => ele.packageid == TowertMainCardModel.Ins.cqKBId);
                        if (vo)
                            this._ui.sp_3.visible = true;
                        this._ui.btn.visible = true;
                        this._ui.sp_5.visible = true;
                        this._ui.lab_auto.visible = false;
                    }
                }
                else {
                    this._ui.btn_close.visible = true;
                    let vo = TowertMainCardModel.Ins.cardGuaranteList.find(ele => ele.packageid == TowertMainCardModel.Ins.cqKBId);
                    if (vo)
                        this._ui.sp_3.visible = true;
                    this._ui.btn.visible = true;
                    this._ui.sp_5.visible = true;
                    this._ui.lab_auto.visible = false;
                }
            }
        }
        onInit() {
            this._cardNum = 0;
            this.updateView(this.Data);
        }
        updateView(data) {
            this._list = data;
            this._num = 0;
            this._isAutoClick = false;
            let vo = TowertMainCardModel.Ins.cardGuaranteList.find(ele => ele.packageid == TowertMainCardModel.Ins.cqKBId);
            if (vo)
                this._ui.lab.text = vo.guarante + "";
            this._ui.btn_close.visible = false;
            this._ui.sp_1.visible = false;
            this._ui.sp_2.visible = false;
            this._ui.sp_3.visible = false;
            this._ui.card.visible = false;
            this._ui.btn.visible = false;
            this._ui.sp_5.visible = false;
            this.ckCtl1.selected = TowertMainCardModel.Ins.cqAuto;
            this.ckCtl2.selected = TowertMainCardModel.Ins.cqTG;
            this._ui.lab_auto.visible = false;
            this._ui.lab_auto1.visible = false;
            for (let i = 1; i < 6; i++) {
                this._ui["sp" + i].visible = true;
                this._ui["s" + i].visible = false;
            }
            this.playEff();
            this.playCard();
        }
        onExit() {
            if (this.skel) {
                this.skel.dispose();
                this.skel = null;
            }
            for (let i = 1; i < 6; i++) {
                if (this["_card" + i]) {
                    this["_card" + i].dispose();
                    this["_card" + i] = null;
                }
            }
            Laya.timer.clear(this, this.onPlayEnd1);
            TowertMainCardModel.Ins.isYD = false;
        }
        playEff() {
            if (!this.skel) {
                this.skel = new SpineCoreSkel();
            }
            let curURL = t_Function_Card_Match.Ins.getIcon(TowertMainCardModel.Ins.selectKBId);
            this.skel.setSlotImg("icon_kb_3", curURL);
            this.skel.once(Laya.Event.COMPLETE, this, this.onCompleteHander);
            if (TowertMainCardModel.Ins.cqTG) {
                this.onPlayEnd();
            }
            else {
                this.skel.play(2, this, this.onPlayEnd, undefined, true);
                E.AudioMgr.StopSound();
                E.AudioMgr.PlaySound1("1003.mp3");
            }
            this.skel.load(`o/spine/succeed/chouka/chouka.skel`);
        }
        onCompleteHander() {
            if (this.skel && this.skel.skeleton) {
                this.skel.skeleton.pos(8, -30);
                this._ui.sp.addChild(this.skel.skeleton);
            }
            else {
                LogSys.Error(`yonr this.skel.skeleton is null`);
            }
        }
        onPlayEnd() {
            this.skel.play(3);
            this._ui.lab_auto.visible = TowertMainCardModel.Ins.cqAuto;
            this._ui.lab_auto1.visible = !TowertMainCardModel.Ins.cqAuto;
            this._ui.sp_2.visible = true;
            this._ui.card.visible = true;
            this.onPlayEnd1();
        }
        onPlayEnd1() {
            if (this._cardNum >= 5) {
                Laya.timer.callLater(this, () => {
                    if (TowertMainCardModel.Ins.cqAuto || TowertMainCardModel.Ins.isYD) {
                        this.playAutoFCard();
                    }
                    else {
                        this._ui.sp_1.visible = true;
                    }
                });
            }
            else {
                Laya.timer.once(30, this, this.onPlayEnd1);
            }
        }
        playCard() {
            for (let i = 1; i < 6; i++) {
                let data = this._list[i - 1];
                let cfg = t_Function_Card.Ins.getCfgById(data.id);
                if (!this["_card" + i]) {
                    this["_card" + i] = new SpineCoreSkel();
                }
                this["_card" + i].setSlotImg("img_kp_1", t_Function_Card.Ins.getQuaSkin(cfg.f_qua));
                this["_card" + i].setSlotImg("img_kp_1_1", t_Function_Card.Ins.getIconById(cfg.f_card_imageid));
                this["_card" + i].once(Laya.Event.COMPLETE, this, this.onCardCompleteHander, [this["_card" + i], i]);
                this["_card" + i].play(0);
                this["_card" + i].load(`o/spine/succeed/chouka_fankai/chouka_fankai.skel`);
            }
        }
        onCardCompleteHander(card, i) {
            if (card && card.skeleton) {
                card.skeleton.pos(8, 3);
                this._ui["card" + i].addChild(card.skeleton);
                this._cardNum++;
            }
            else {
                LogSys.Error(`yonr this.skel.skeleton is null`);
            }
        }
    }

    class TowertMainCardModule extends BaseModel {
        static get Ins() {
            if (!this._ins) {
                this._ins = new TowertMainCardModule();
            }
            return this._ins;
        }
        onInitCallBack() { }
        initMsg() {
            this.Reg(new TowertMainCardView1(EViewType.TowertMainCardView1));
            this.Reg(new TowertMainCardView2(EViewType.TowertMainCardView2));
            this.Reg(new TowertMainCardTip(EViewType.TowertMainCardTip));
            this.Reg(new TowertMainCardTip1(EViewType.TowertMainCardTip1));
            this.Reg(new CardCQView(EViewType.CardCQView));
            this.Reg(new CardCQView1(EViewType.CardCQView1));
            this.Reg(new CardCQView2(EViewType.CardCQView2));
            E.MsgMgr.AddMsg(SERVER_MSGID.FCardInit, this.FCardInit);
            E.MsgMgr.AddMsg(SERVER_MSGID.FCardChange, this.FCardChange);
            E.MsgMgr.AddMsg(SERVER_MSGID.FCardPlanChange, this.FCardPlanChange);
            E.MsgMgr.AddMsg(SERVER_MSGID.FCardChangePlan, this.FCardChangePlan);
            E.MsgMgr.AddMsg(SERVER_MSGID.FCardGuaranteChange, this.FCardGuaranteChange);
            E.MsgMgr.AddMsg(SERVER_MSGID.FCardExtract, this.FCardExtract);
        }
        FCardInit(value) {
            TowertMainCardModel.Ins.cardList = value.cards;
            TowertMainCardModel.Ins.cardPlanList = value.cardPlans;
            TowertMainCardModel.Ins.planId = value.planId;
            TowertMainCardModel.Ins.newList = [];
            TowertMainCardModel.Ins.cardGuaranteList = value.guaranteList;
        }
        FCardChange(value) {
            for (let i = 0; i < value.cards.length; i++) {
                let index = TowertMainCardModel.Ins.cardList.findIndex(ele => ele.id == value.cards[i].id);
                if (index == -1) {
                    let obj = {};
                    obj.id = value.cards[i].id;
                    obj.isSelect = false;
                    TowertMainCardModel.Ins.newList.push(obj);
                }
            }
            TowertMainCardModel.Ins.cardList = value.cards;
            TowertMainCardModel.Ins.event(TowertMainCardModel.UPDATE_CARD);
        }
        FCardPlanChange(value) {
            TowertMainCardModel.Ins.planId = value.planId;
            TowertMainCardModel.Ins.event(TowertMainCardModel.UPDATE_PLANID);
        }
        FCardChangePlan(value) {
            for (let i = 0; i < value.cards.length; i++) {
                let index = TowertMainCardModel.Ins.cardPlanList.findIndex(ele => ele.id === value.cards[i].id);
                TowertMainCardModel.Ins.cardPlanList[index] = value.cards[i];
            }
            TowertMainCardModel.Ins.event(TowertMainCardModel.UPDATE_PLAN);
        }
        FCardGuaranteChange(value) {
            for (let i = 0; i < value.datalist.length; i++) {
                let index = TowertMainCardModel.Ins.cardGuaranteList.findIndex(ele => ele.packageid === value.datalist[i].packageid);
                if (index != -1) {
                    TowertMainCardModel.Ins.cardGuaranteList[index] = value.datalist[i];
                }
            }
        }
        FCardExtract(value) {
            TowertMainCardModel.Ins.cqKBId = value.packageid;
            if (E.ViewMgr.isOpenReg(EViewType.CardCQView2)) {
                E.ViewMgr.Get(EViewType.CardCQView2).updateView(value.cards);
            }
            else {
                E.ViewMgr.Open(EViewType.CardCQView2, null, value.cards);
            }
            TowertMainCardModel.Ins.event(TowertMainCardModel.UPDATE_CQLIST);
        }
    }

    class HeroHuanZhuangItem extends ui.views.hero.ui_huanzhuangItemUI {
        constructor() {
            super();
            ButtonCtl.Create(this.btn1, new Laya.Handler(this, this.onBtnClick));
            ButtonCtl.Create(this.btn_l, new Laya.Handler(this, this.onBtnLClick));
            this.on(Laya.Event.UNDISPLAY, this, this.disposeHero);
        }
        onBtnLClick() {
            if (!this._data)
                return;
            E.ViewMgr.Open(EViewType.HeroSkinView, null, this._data.f_skinid);
        }
        onBtnClick() {
            if (!this._data)
                return;
            let vo = new ItemVo;
            vo.cfgId = this._data.f_itemid;
            vo.count = 1;
            let vo1 = ItemViewFactory.convertItem(this._data.f_unlock_price);
            E.ViewMgr.showMsgBoxView(vo, vo1, new Laya.Handler(this, () => {
                let req = new HeroBuySkin_req;
                req.skinItemId = this._data.f_itemid;
                SocketMgr.Ins.SendMessageBin(req);
            }));
        }
        disposeHero() {
            if (this._heroAnim) {
                this._heroAnim.dispose();
                this._heroAnim = null;
            }
        }
        setData(value, id) {
            this._data = t_Hero_Skin.Ins.getCfgById(parseInt(value));
            this.lab.text = this._data.f_skin_name;
            let _curScale = HeroListProxy.Ins.getScaleById(id);
            let arr = this._data.f_pos.split("|");
            if (!this._heroAnim) {
                this._heroAnim = FightFactory.createByImageId(this._data.f_imageid, this.sp, parseInt(arr[0]), parseInt(arr[1]), _curScale);
            }
            let status = 0;
            let data = TowertMainHeroModel.Ins.getHeroById(id);
            if (data) {
                if (data.skinId == this._data.f_skinid) {
                    status = 1;
                }
                else if (data.skins.indexOf(this._data.f_skinid) != -1) {
                    status = 2;
                }
            }
            this.img.visible = this.img1.visible = this.img2.visible = this.btn1.visible = false;
            if (status == 0) {
                this.sp1.visible = true;
                if (this._data.f_unlock_price != "") {
                    this.btn1.visible = true;
                    let vo = ItemViewFactory.convertItem(this._data.f_unlock_price);
                    this.icon.skin = vo.getIcon();
                    this.lab_icon.text = vo.count + "";
                }
                else if (this._data.f_unlock_way != "") {
                    this.img.visible = true;
                    this.lab1.text = this._data.f_unlock_way;
                }
                else {
                    this.img2.visible = true;
                    this.lab3.text = "未拥有";
                }
            }
            else {
                this.sp1.visible = false;
                if (status == 1) {
                    this.img1.visible = true;
                }
                else if (status == 2) {
                    this.img2.visible = true;
                    this.lab3.text = "已拥有";
                }
            }
            if (this._data.f_illustration_type) {
                this.btn_l.visible = true;
            }
            else {
                this.btn_l.visible = false;
            }
            this.btn.visible = this.sp2.visible = false;
        }
    }

    class HeroHuanZhuangView extends ViewBase {
        constructor() {
            super(...arguments);
            this.mMask = true;
            this.mMainSnapshot = true;
            this.autoFree = true;
        }
        onAddLoadRes() {
            this.addAtlas('hero.atlas');
        }
        onFirstInit() {
            if (!this.UI) {
                this.UI = this._ui = new ui.views.hero.ui_huanzhuangViewUI();
                this.bindClose(this._ui.btn_close);
                this.btnList.push(ButtonCtl.Create(this._ui.btn_js, new Laya.Handler(this, this.onBtnClick)));
                this._ui.list.itemRender = HeroHuanZhuangItem;
                this._ui.list.renderHandler = new Laya.Handler(this, this.onRenderHandler);
                this._ui.list.selectEnable = true;
            }
        }
        onBtnClick() {
            let req = new HeroSwitchSkin_req;
            req.heroId = this._data.f_heroid;
            req.skinId = parseInt(this._ui.list.selectedItem);
            SocketMgr.Ins.SendMessageBin(req);
        }
        onRenderHandler(item, index) {
            if (index == this._ui.list.selectedIndex) {
                item.sel.visible = true;
                this.updateView1();
            }
            else {
                item.sel.visible = false;
            }
            item.setData(item.dataSource, this._data.f_heroid);
        }
        onInit() {
            TowertMainHeroModel.Ins.on(TowertMainHeroModel.UPDATE_HERO, this, this.updateView);
            this._data = HeroListProxy.Ins.getCfgById(this.Data);
            this.updateView();
        }
        onExit() {
            TowertMainHeroModel.Ins.off(TowertMainHeroModel.UPDATE_HERO, this, this.updateView);
            this.disposeHero();
        }
        updateView() {
            let arr = this._data.f_skin.split("-");
            this._ui.list.array = arr;
            let index = 0;
            let data = TowertMainHeroModel.Ins.getHeroById(this._data.f_heroid);
            for (let i = 0; i < arr.length; i++) {
                if (data && data.skinId == parseInt(arr[i])) {
                    index = i;
                    break;
                }
            }
            this._ui.list.selectedIndex = index;
        }
        updateView1() {
            this.disposeHero();
            let cfg = t_Hero_Skin.Ins.getCfgById(parseInt(this._ui.list.selectedItem));
            let _curScale = HeroListProxy.Ins.getScaleById(this._data.f_heroid);
            this._heroAnim = FightFactory.createByImageId(cfg.f_imageid, this._ui.sp, 0, 0, _curScale);
            if (cfg.f_bufff_desc != "") {
                this._ui.lab.text = cfg.f_bufff_desc;
                this._ui.sp2.visible = true;
            }
            else {
                this._ui.lab.text = "";
                this._ui.sp2.visible = false;
            }
            let status = 0;
            let data = TowertMainHeroModel.Ins.getHeroById(this._data.f_heroid);
            if (data) {
                if (data.skinId == cfg.f_skinid) {
                    status = 1;
                }
                else if (data.skins.indexOf(cfg.f_skinid) != -1) {
                    status = 2;
                }
            }
            if (status == 0) {
                this._ui.img1.visible = false;
                this._ui.btn_js.visible = true;
                this._ui.btn_js.disabled = true;
                this._ui.lab1.text = "未拥有";
            }
            else if (status == 1) {
                this._ui.img1.visible = true;
                this._ui.btn_js.visible = false;
            }
            else if (status == 2) {
                this._ui.img1.visible = false;
                this._ui.btn_js.visible = true;
                this._ui.btn_js.disabled = false;
                this._ui.lab1.text = "穿戴";
            }
        }
        disposeHero() {
            if (this._heroAnim) {
                this._heroAnim.dispose();
                this._heroAnim = null;
            }
        }
    }

    class HeroSkinView extends ViewBase {
        constructor() {
            super(...arguments);
            this.mMask = true;
            this.mMainSnapshot = true;
            this.autoFree = true;
            this.mMaskClick = false;
        }
        onAddLoadRes() {
            this.addAtlas("heroskin.atlas");
        }
        onFirstInit() {
            if (!this.UI) {
                this.UI = this._ui = new ui.views.hero.ui_heroTip2UI;
                this.bindClose(this._ui.btn_close);
                this.btnList.push();
                this._ui.list.itemRender = ui.views.hero.ui_heroItem4UI;
                this._ui.list.renderHandler = new Laya.Handler(this, this.onRenderHandler);
            }
        }
        onRenderHandler(item) {
            item.img.skin = `remote/heroskin/img_${item.dataSource}.png`;
        }
        onInit() {
            let data = t_Hero_Skin.Ins.getCfgById(parseInt(this.Data));
            this._ui.bg.skin = `o/illustrationbg/${data.f_illustration_bg}.jpg`;
            this._ui.lab.text = data.f_skin_name;
            this._ui.list.array = data.f_detail_label.split("|");
            this._ui.lab1.text = data.f_bufff_desc;
            this._ui.lab2.text = data.f_unlock_way;
            this.disposeHero();
            if (!this._heroAnim) {
                this._heroAnim = FightFactory.createByImageId(data.f_imageid, this._ui.sp1, 0, 10, 1.2);
            }
            this._ui.img.visible = false;
            this._ui.img1.visible = false;
            this.disposeSe();
            if (data.f_illustration_type == 1) {
                this._ui.img.visible = true;
                this._ui.img.skin = `o/bigshow/${data.f_illustration}.png`;
            }
            else if (data.f_illustration_type == 2) {
                if (!this._sp) {
                    this._sp = new SimpleEffect(this._ui.sp, `o/spine/bigshow/${data.f_illustration}/${data.f_illustration}`, 30, 80);
                    this._sp.play(0, true);
                }
            }
            if (data.f_qua_label != "") {
                let type = parseInt(data.f_qua_label.split("-")[0]);
                let url = data.f_qua_label.split("-")[1];
                if (type == 1) {
                    this._ui.img1.visible = true;
                    this._ui.img1.skin = `o/illustrationqua/${url}.png`;
                }
                else if (type == 2) {
                    this._sp1 = SpineEffectMgr.createIllustration(data, this._ui.sp2);
                }
            }
        }
        onExit() {
            this.disposeSe();
            this.disposeHero();
        }
        disposeSe() {
            if (this._sp) {
                this._sp.dispose();
                this._sp = null;
            }
            if (this._sp1) {
                this._sp1.dispose();
                this._sp1 = null;
            }
        }
        disposeHero() {
            if (this._heroAnim) {
                this._heroAnim.dispose();
                this._heroAnim = null;
            }
        }
    }

    class HeroItem2 extends ui.views.hero.ui_heroItem2UI {
        constructor() {
            super();
            this.ht.style.fontSize = 24;
            this.ht.style.family = "BOLD";
            this.ht.style.stroke = 4;
            this.ht.style.strokeColor = "#3a1c17";
        }
        setData(value, lv) {
            if (!value)
                return;
            this.lab.text = E.getLang("LV") + value.f_herolevel;
            this.ht.innerHTML = value.f_client_skill;
            this.ht.width = 395;
            if (lv >= value.f_herolevel) {
                this.lock.visible = false;
                this.sp.visible = this.sp1.visible = false;
            }
            else {
                this.lock.visible = true;
                if (TowertMainHeroModel.Ins.isHeroLv(value.f_heroid, lv)) {
                    if (lv + 1 == value.f_herolevel) {
                        this.sp.visible = true;
                        this.sp1.visible = false;
                    }
                    else {
                        this.sp.visible = false;
                        this.sp1.visible = true;
                    }
                }
                else {
                    this.sp.visible = false;
                    this.sp1.visible = true;
                }
            }
        }
    }

