            if (this._yun1) {
                this._yun1.dispose();
                this._yun1 = null;
            }
            if (this._yun2) {
                this._yun2.dispose();
                this._yun2 = null;
            }
            if (this.skel) {
                this.skel.dispose();
                this.skel = null;
            }
