                this._ui.l1.visible = true;
                let count = TowertMainHeroModel.Ins.getAttr();
                let cfg = HeroListLvProxy.Ins.getCfgByIdAndLv(hData.id, hData.level);
                let num = parseInt(cfg.f_global_attribute.split(":")[1]);
