    class MainIconListBase {
        constructor() {
            this.cellGap = 0;
            this.minRow = 1;
        }
        f_posSortHandler(a, b) {
            if (a.f_pos < b.f_pos) {
                return -1;
            }
            else if (a.f_pos > b.f_pos) {
                return 1;
            }
            return 0;
        }
        f_sortSortHandler(a, b) {
            if (a.f_sort < b.f_sort) {
                return -1;
            }
            else if (a.f_sort > b.f_sort) {
                return 1;
            }
            return 0;
        }
    }

    class TopBtnList extends MainIconListBase {
        constructor() {
            super(...arguments);
            this.cellGap = 40;
            this._iconCfgList = [];
            this._dir = 1;
        }
        init() {
            this.curIconList = [];
            let l1 = MainIconProxy.Ins.List;
            for (let i = 0; i < l1.length; i++) {
                let cfg = l1[i];
                if (cfg.f_pos == this.type) {
                    this._iconCfgList.push(cfg);
                }
            }
            this._iconCfgList.sort(this.f_sortSortHandler);
            MainModel.Ins.on(TowerMainEvent.FuncSmallIconUpdate, this, this.onRedUpdate);
            TowerMainModel.Ins.on(TowerMainEvent.FunctionChange, this, this.onRedUpdate);
        }
        onRedUpdate() {
            this.refresh();
        }
        get maxCount() {
            return parseInt(System_RefreshTimeProxy.Ins.getVal(ESystemRefreshTime.RightMaxBtnCount));
        }
        bindBtn(btn) {
            this.arrowBtn = btn;
            btn.on(Laya.Event.CLICK, this, this.onRightClick);
            DebugUtil.draw(btn);
        }
        onRightClick() {
            this.btnDir = -1 * this.btnDir;
            this.refresh();
        }
        set btnDir(v) {
            this._dir = v;
            this.arrowBtn.skin = v == 1 ? `remote/towerMain/yc.png` : `remote/towerMain/yc.png`;
        }
        get btnDir() {
            return this._dir;
        }
        refresh() {
            Laya.timer.callLater(this, this.onUpdate);
        }
        onUpdate() {
            while (this.curIconList.length) {
                let cell = this.curIconList.pop();
                Laya.Pool.recover(TopBtnList.FuncSmallIconKey09, cell);
                cell.dispose();
            }
            let sx = 0;
            let sy = 0;
            let row = 0;
            let cellWidth;
            let openCount = 0;
            let maxH = 0;
            for (let i = 0; i < this._iconCfgList.length; i++) {
                let cfg = this._iconCfgList[i];
                if (openCount >= this.maxCount && this.btnDir == -1) {
                }
                else if (this.isOpen(cfg)) {
                    openCount++;
                    if (row >= this.minRow) {
                        row = 0;
                        if (this.type == 1) {
                            sx += cellWidth;
                            sy = 0;
                        }
                        else if (this.type == 2) {
                            sx -= cellWidth;
                            sy = 0;
                        }
                    }
                    let item = Laya.Pool.getItemByClass(TopBtnList.FuncSmallIconKey09, FuncSmallIcon);
                    this.curIconList.push(item);
                    item.initSkin(ui.views.main.ui_tower_main_iconUI);
                    cellWidth = item.skin.width + this.cellGap - 5;
                    item.refresh(item.skin, cfg.f_funid, EButtonStyle.Pos, sx, sy);
                    item.skin["timeCtl"].visible = false;
                    this.con.addChild(item.skin);
                    sy += item.skin.height + this.cellGap;
                    row++;
                    if (sy >= maxH) {
                        maxH = sy;
                    }
                }
            }
            DebugUtil.draw(this.con, "#ff0000", cellWidth, maxH);
            this.arrowBtn.visible = false;
        }
        isOpen(cfg) {
            return cfg && FunctionModel.Ins.isOpenByFuncId(cfg.f_funid, false);
        }
        updateArrowBtnRed() {
            let l = [];
            for (let i = 0; i < this._iconCfgList.length; i++) {
                let cfg = this._iconCfgList[i];
                if (this.isOpen(cfg)) {
                    l.push(cfg);
                }
            }
            let _newList = [];
            while (l.length > this.maxCount) {
                _newList.push(l.pop());
            }
            for (let i = 0; i < _newList.length; i++) {
                let cfg = _newList[i];
                if (this.hasRedMainCfg(cfg.f_id)) {
                    return cfg.f_funid;
                }
            }
            return 0;
        }
        hasRedMainCfg(id) {
            let cfg = MainIconProxy.Ins.GetDataById(id);
            let red = false;
            if (!red) {
                let funcId = cfg.f_funid;
                if (FunctionModel.Ins.getHasRed(funcId)) {
                    red = true;
                }
            }
            return red;
        }
        getByFuncId(funcId) {
            let l = this.curIconList;
            for (let i = 0; i < l.length; i++) {
                let cell = l[i];
                if (cell.funcId == funcId) {
                    return cell.skin;
                }
            }
        }
    }
    TopBtnList.FuncSmallIconKey09 = "FuncSmallIcon09";

