    class AtlasMgr {
        constructor() {
            this.atlasList = [];
        }
        load(url) {
            let cell = this.atlasList.find(o => o.url == url);
            if (cell) {
                cell.count++;
            }
            else {
                cell = new AtlasVo();
                cell.count = 1;
                cell.url = url;
                this.atlasList.push(cell);
            }
        }
        dispose(url) {
            let cell = this.atlasList.find(o => o.url == url);
            let need;
            if (cell) {
                cell.count--;
                if (cell.count <= 0) {
                    need = true;
                }
            }
            else {
                need = true;
            }
            if (need) {
                AssetConfig.clearTextureRes(url);
            }
        }
    }

